//! Rust split of `pyjitpl.py` dispatch/runtime helpers.
//!
//! Upstream keeps this logic in `rpython/jit/metainterp/pyjitpl.py`
//! alongside `MIFrame` and `MetaInterp`. Rust splits the large file so the
//! JitCode dispatch walker and its runtime helpers can live beside the
//! generated bytecode dispatch without creating a second upstream module.

use std::marker::PhantomData;
use std::sync::Arc;

use majit_ir::{GreenKey, GreenType, OpCode, OpRef, Type, Value};
use smallvec::SmallVec;

use super::{MIFrame, MIFrameStack};
use crate::jitcode::insns::MAX_HOST_CALL_ARITY;
use crate::jitcode::{self, JitArgKind, JitCallArg, JitCallTarget, JitCode, JitCodeRuntimeExt};
use crate::trace_ctx::{ClearReplaceFrames, NonstandardVable, VableArrayStore};
use crate::{TraceAction, TraceCtx};

/// Residual-call argument lists. Eight slots cover the common helper arity
/// (`MAX_HOST_CALL_ARITY` is 16); longer calls spill once.
const CALL_INLINE: usize = 8;
type CallOpRefs = SmallVec<[OpRef; CALL_INLINE]>;
type CallI64s = SmallVec<[i64; CALL_INLINE]>;
type CallTypes = SmallVec<[Type; CALL_INLINE]>;
type CallArgs = SmallVec<[JitCallArg; CALL_INLINE]>;
type CallValues = SmallVec<[Value; CALL_INLINE]>;

/// One `pyjitpl.py` `_get_opimpl_method` handler.
/// `MetaInterpStaticData.opcode_implementations` is a table of these,
/// filled by `setup_insns`.
type OpImplFn<'mi, S, R> =
    fn(&mut JitCodeMachine<'mi, S, R>, &mut TraceCtx, &mut S, &R, u8) -> TraceAction;

fn intern_dispatch_array_descr(
    cache: &parking_lot::Mutex<
        crate::FxIndexMap<crate::pyjitpl::DispatchArrayDescrKey, majit_ir::DescrRef>,
    >,
    cache_key: crate::pyjitpl::DispatchArrayDescrKey,
    mint: impl FnOnce() -> Arc<majit_ir::descr::SimpleArrayDescr>,
) -> majit_ir::DescrRef {
    let mut guard = cache.lock();
    if let Some(cached) = guard.get(&cache_key) {
        return cached.clone();
    }
    let load_is_acquire = cache_key.load_is_acquire;
    let minted = mint();
    let descr: majit_ir::DescrRef = if load_is_acquire {
        Arc::new(Arc::unwrap_or_clone(minted).with_load_is_acquire(true))
    } else {
        minted
    };
    guard.insert(cache_key, descr.clone());
    descr
}

/// `GcLLDescr_boehm.malloc_fixedsize` (`llmodel_alloc`).
///
/// `Some` when the host published the hook, including a null OOM result.
/// `None` leaves the caller on its raw allocator. `GC_malloc` is already
/// zero-filled, and `call_malloc_fixedsize` does not clear a second time.
fn host_malloc_fixedsize(size: usize) -> Option<*mut u8> {
    let addr = majit_gc::malloc_fixedsize_addr();
    if addr == 0 {
        return None;
    }
    let malloc: extern "C" fn(usize) -> *mut u8 = unsafe { std::mem::transmute(addr) };
    Some(malloc(size))
}

/// Which recorded op [`JitCodeMachine::publish_last_guard_resume_snapshot`]
/// points at the snapshot it just captured.
#[derive(Clone, Copy)]
enum GuardStampTarget {
    /// The last recorded op — correct when the guard IS the last op, which is
    /// the case for every guard the dispatcher records itself.
    LastOp,
    /// A guard op counted back from the most recent one (`0` == the most
    /// recent), for a guard that is no longer last (`emit_force_virtualizable`
    /// records GETFIELD_GC / PTR_NE / COND_CALL after a promote).
    #[allow(dead_code)]
    GuardFromEnd(usize),
}

/// Decode a virtualizable shadow Value (RPython Box concrete) back into the
/// raw int/ref/float bit pattern stamped onto the register box
/// (`IntOp.getint` / `RefOp.getref_base` / `FloatOp.getfloat_storage`).
/// `Value::Void` means the vable layout was not available at read time (heap
/// fallback) — callers substitute zero to preserve pre-existing behaviour for
/// test-only paths. All three helpers must match the encoding convention used
/// by `Const::as_raw_i64()` (`value.rs`).
fn value_as_int_bits(value: Value) -> i64 {
    match value {
        Value::Int(v) => v,
        _ => 0,
    }
}

fn value_as_ref_bits(value: Value) -> i64 {
    match value {
        Value::Ref(r) => r.as_usize() as i64,
        _ => 0,
    }
}

fn value_as_float_bits(value: Value) -> i64 {
    match value {
        Value::Float(f) => f.to_bits() as i64,
        _ => 0,
    }
}

/// Heapcache key for one field access resolved from a `BhDescr::Field`.
///
/// `fielddescrof` copies the parent field's slot onto a `Vec` or fat-pointer
/// part and then reads the other word (`.data`, `.len`, `.buf`, `.vtable`).
/// `HeapCache` keys the read by `Descr::index()`, so those two words must not
/// both answer with that slot.  `.vtable` is the vtable word of `&dyn`; it
/// shares the data word's slot and sits one word later.  A part the slot does
/// not describe passes `u32::MAX`, the unassigned sentinel
/// `ensure_heapcache_index` replaces with a unique key.  Every other access
/// keeps `index_in_parent`, including a part whose slot still describes the
/// word.
fn heapcache_index_for_split_part(
    index_in_parent: Option<usize>,
    parent: &majit_jitcode::jitcode::BhSizeSpec,
    name: &str,
    offset: usize,
    field_size: usize,
    field_type: majit_ir::value::Type,
) -> u32 {
    let split_part = name.ends_with(".data")
        || name.ends_with(".len")
        || name.ends_with(".buf")
        || name.ends_with(".vtable");
    let slot_describes_access = index_in_parent.is_some_and(|index| {
        parent.all_fielddescrs.get(index).is_some_and(|spec| {
            spec.offset == offset && spec.field_size == field_size && spec.field_type == field_type
        })
    });
    if split_part && index_in_parent.is_some() && !slot_describes_access {
        return u32::MAX;
    }
    index_in_parent.unwrap_or(0) as u32
}

/// Mirror a serialized `BhFieldSpec` onto a `SimpleFieldDescrSpec` so
/// `make_simple_descr_group_keyed` can rebuild the runtime
/// `SizeDescr.all_fielddescrs` / per-field `FieldDescr` group with the
/// parent back-references the optimizer's virtualize pass relies on.
fn field_spec_from_bh(
    f: &majit_jitcode::jitcode::BhFieldSpec,
) -> majit_ir::descr::SimpleFieldDescrSpec {
    majit_ir::descr::SimpleFieldDescrSpec {
        index: f.index,
        field_key: f.field_key().to_string(),
        // Carry the producer's declaration through unchanged, `None` included:
        // a spec that declared nothing leaves the question to the name
        // fallback rather than arriving as a declaration of the guess.
        is_class_word: f.is_class_word,
        name: f.name.clone(),
        offset: f.offset,
        field_size: f.field_size,
        field_type: f.field_type,
        is_immutable: f.is_immutable,
        is_quasi_immutable: f.is_quasi_immutable,
        flag: f.field_flag,
        virtualizable: false,
        index_in_parent: f.index_in_parent,
        load_is_acquire: f.load_is_acquire,
    }
}

/// Convert a canonical `Size` blackhole descr (from the per-jitcode
/// descr pool) into the optimizer-facing `DescrRef` that `New` /
/// `NewWithVtable` carry.  Mirrors `descr.py get_size_descr` +
/// `:188 init_size_descr`: when the producer shipped a non-empty
/// `all_fielddescrs` (a struct-literal `new`), rebuild the cyclic
/// SizeDescr + per-field FieldDescr group so the optimizer's virtualize
/// pass reads the full field list off `vinfo.descr.all_fielddescrs()`
/// (`optimizeopt/info.rs init_fields`, `virtualize.rs` debug_assert).
/// A transient fieldless allocation carries only size + vtable + type
/// identity, matching `bh_new`/`bh_new_with_vtable` dispatch descrs.
fn size_descr_ref_from_bh(descr: &crate::blackhole::BhDescr) -> majit_ir::DescrRef {
    let headerless = descr.is_headerless();
    if let crate::blackhole::BhDescr::Size {
        size,
        type_id,
        vtable,
        all_fielddescrs,
        is_gc_managed,
        ..
    } = descr
        && !all_fielddescrs.is_empty()
    {
        let specs: Vec<_> = all_fielddescrs.iter().map(field_spec_from_bh).collect();
        let group = majit_ir::descr::make_simple_descr_group_keyed_with_headerless(
            u32::MAX,
            *size,
            *type_id as u32,
            *type_id,
            *vtable as usize,
            *is_gc_managed,
            headerless,
            &specs,
            &[],
        );
        let sd: majit_ir::DescrRef = group.size_descr;
        return sd;
    }
    let size = descr.as_size();
    let vtable = descr.get_vtable();
    let type_id = descr.get_type_id() as u32;
    let mut sd = if vtable != 0 {
        majit_ir::descr::SimpleSizeDescr::with_vtable(u32::MAX, size, type_id, vtable)
    } else {
        majit_ir::descr::SimpleSizeDescr::new(u32::MAX, size, type_id)
    };
    sd.set_headerless(headerless);
    let sd: majit_ir::DescrRef = Arc::new(sd);
    sd
}

/// Resolve a plain `Field` blackhole descr (from the per-jitcode descr
/// pool) to its byte offset plus the optimizer-facing FieldDescr that
/// getfield_gc / setfield_gc records carry (`descr.py FieldDescr`).
/// When the producer attached the owning struct's layout (`parent` from
/// a struct-literal `setfield_gc`), rebuild the descr group so the
/// FieldDescr carries `index_in_parent` (`descr.py`) + `parent_descr
/// = get_size_descr(STRUCT)` (`descr.py`); `optimize_setfield_gc`
/// (`optimizeopt/virtualize.rs`) requires the parent to virtualize
/// the store.  A parentless field (getfield round-trip / non-virtualized
/// store) keeps the placeholder builder.
/// The byte offset a field descriptor names, without minting the optimizer
/// object beside it.
///
/// `field_descr_ref_from_bh` returns this same offset paired with a freshly
/// built descr. A caller that already holds the pool's resolved descr
/// (`MIFrame::runtime_optimizer_descr`) wants only this half, and enforces the
/// same invariant; `site` names the opcode so the abort still says which one.
pub fn field_offset_from_bh(descr: &crate::blackhole::BhDescr, site: &str) -> usize {
    match descr {
        crate::blackhole::BhDescr::Field { offset, .. } => *offset,
        other => panic!("{site}: descriptor is not a Field: {other:?}"),
    }
}

/// `descr.py` `FieldDescr.field_size`. A non-Field descr is a bug, same
/// as a missing descrs slot.
pub fn field_size_from_bh(descr: &crate::blackhole::BhDescr, site: &str) -> usize {
    match descr {
        crate::blackhole::BhDescr::Field { field_size, .. } => *field_size,
        other => panic!("{site}: descriptor is not a Field: {other:?}"),
    }
}

/// `descr.py` `FieldDescr.is_field_signed()`. A non-Field descr is a bug,
/// same as a missing descrs slot.
pub fn is_field_signed_from_bh(descr: &crate::blackhole::BhDescr, site: &str) -> bool {
    match descr {
        crate::blackhole::BhDescr::Field {
            is_field_signed, ..
        } => *is_field_signed,
        other => panic!("{site}: descriptor is not a Field: {other:?}"),
    }
}

/// The heapcache's field key, or `None` for a descr that has none.
///
/// `heapcache.get_field_updater(box, fielddescr)` keys the per-box field
/// cache on the descr object itself, so two fields of one struct can never
/// share an entry.  The key here is `DescrRef::index()`.  A codewriter
/// slot is used when one was stamped (`call.rs get_field_descr`); otherwise
/// `Descr::index()` allocates a unique identity so a hand-assembled
/// jitcode does not collapse every field onto the `u32::MAX` sentinel.
fn heapcache_field_key(fielddescr: &majit_ir::DescrRef) -> Option<u32> {
    let index = fielddescr.index();
    (index != u32::MAX).then_some(index)
}

pub fn field_descr_ref_from_bh(descr: &crate::blackhole::BhDescr) -> (usize, majit_ir::DescrRef) {
    match descr {
        crate::blackhole::BhDescr::Field {
            offset,
            field_size,
            field_type,
            field_flag,
            index_in_parent,
            parent,
            name,
            owner,
            is_immutable,
            is_quasi_immutable,
            load_is_acquire,
            ..
        } => {
            // descr.py get_field_descr keys cache[STRUCT][fieldname] by the
            // STRUCT-local fieldname. Flatten serializes the printable
            // display (`STRUCT._name + '.' + fieldname`) in `name` and the
            // owner separately; asking with the display string mints a
            // parallel descr (exact fieldname, S1-2) whose leftover lands in
            // the unslotted offset band (S1-8).
            let field_key = majit_jitcode::jitcode::bh_field_cache_key(owner, name);
            if let Some(p) = parent {
                if !p.all_fielddescrs.is_empty() {
                    // The descr's own two halves, before any of the branches
                    // below hand it to a reader that would reconcile them:
                    // `index_in_parent` (`descr.py:228`) must name the slot of
                    // the attached parent's list that this field's offset
                    // occupies.  `get_field_descr`'s `derive_index_in_parent`
                    // cannot answer this — it runs only on the mint path, only
                    // once `_cache_size` already holds the parent, and it
                    // overwrites the number it disagrees with.
                    //
                    // Keyed by field name, `heaptracker.py:60-72
                    // get_fielddescr_index_in(STRUCT, fieldname)`; the byte
                    // offset stands in only for the mint sites that carry no
                    // name, and only when exactly one field sits there. A
                    // flattened layout puts an inline aggregate and its first
                    // leaf at one address, so an offset-keyed census would
                    // report a correctly-named descr as misplaced and put a
                    // false reading behind `JITSTATS_BADNESS_FIELDS`.
                    //
                    // A miss is the inline-aggregate floor (`ob_header`,
                    // `int_items`, an enum's `__pos_0`) carrying the documented
                    // `(0, "")` fallback the branches below already describe,
                    // not this defect, so it is not counted either way.
                    let expected = p
                        .all_fielddescrs
                        .iter()
                        .position(|f| {
                            (!name.is_empty() && f.name == *name) || f.field_key() == field_key
                        })
                        .or_else(|| {
                            let mut at = p
                                .all_fielddescrs
                                .iter()
                                .enumerate()
                                .filter(|(_, f)| f.offset == *offset);
                            let (idx, _) = at.next()?;
                            at.next().is_none().then_some(idx)
                        });
                    if let Some(expected) = expected {
                        majit_ir::descr::census_attached_index(expected, *index_in_parent);
                    }
                    let mut specs: Vec<_> =
                        p.all_fielddescrs.iter().map(field_spec_from_bh).collect();
                    if p.type_id == 0 {
                        // Same no-identity sentinel the empty-list branch below
                        // carves out, and the same one
                        // `simple_descr_group_from_bh_size`
                        // (`pyre-jit-trace/src/descr.rs`) carves out for this
                        // exact input. Here it is the more damaging of the two:
                        // the keyed publish would put a whole *field table*
                        // under `LLType::Struct(0)`, and `get_field_descr` keys
                        // `_cache_field[key]` by field name — so a second
                        // type-id-less parent that shares a field name would
                        // resolve to the first parent's descr, and one that does
                        // not would still mint against the first parent's size
                        // descr, since `_cache_size` already holds that slot.
                        // Mint fresh per resolution instead: without an identity
                        // carrier the orthodox reading is "each of these is a
                        // distinct STRUCT".
                        //
                        // The missing key says nothing about the STRUCT's
                        // shape, so `is_gc_managed`/`headerless` are carried
                        // through exactly as the keyed arm carries them.
                        if crate::majit_log_enabled() {
                            eprintln!(
                                "[jit] field_descr_ref_from_bh: fresh-minting a \
                                 type-id-less parent with {} field(s) for field={name:?}",
                                specs.len()
                            );
                        }
                        // A name miss means the getfield names an inline
                        // aggregate (`ob_header`, `int_items`, an enum's
                        // `__pos_0`) that the flattened list only covers
                        // through its leaves — the same miss the keyed path
                        // below takes.  `heaptracker.py:68-69` recurses into a
                        // nested `lltype.Struct` without minting a descr for
                        // the container, and `jtransform.py rewrite_op_getsubstruct
                        // rewrite_op_getsubstruct` lowers a raw one to
                        // `int_add(ptr, offset)` with no descr at all.  Carry
                        // it as one more field of this fresh parent rather than
                        // falling through to the parentless placeholder, so
                        // `protect_speculative_field` still has a parent.
                        let selected = specs
                            .iter()
                            .position(|spec| spec.field_key == field_key || spec.name == *name)
                            .unwrap_or_else(|| {
                                // This row is appended, so its slot is the new
                                // end of the list. The incoming claim numbered
                                // the serialized parent, which does not contain
                                // this field.
                                let slot = specs.len();
                                specs.push(majit_ir::descr::SimpleFieldDescrSpec {
                                    index: u32::MAX,
                                    field_key: field_key.to_string(),
                                    // The container name is all this arm
                                    // has; nothing declared, so the descr
                                    // infers from it.
                                    is_class_word: None,
                                    name: name.clone(),
                                    offset: *offset,
                                    field_size: *field_size,
                                    field_type: *field_type,
                                    is_immutable: *is_immutable,
                                    is_quasi_immutable: *is_quasi_immutable,
                                    flag: *field_flag,
                                    virtualizable: false,
                                    index_in_parent: slot,
                                    load_is_acquire: *load_is_acquire,
                                });
                                specs.len() - 1
                            });
                        let group = majit_ir::descr::make_simple_descr_group_with_flags(
                            u32::MAX,
                            p.size,
                            0,
                            p.vtable as usize,
                            p.is_gc_managed,
                            p.headerless,
                            &specs,
                        );
                        let fd = group.field_descrs[selected].clone();
                        return (*offset, fd as majit_ir::DescrRef);
                    }
                    // descr.py get_field_descr: populate the
                    // gccache (first-write-wins, idempotent across the
                    // matching `new`) then return the *cached*
                    // Arc<FieldDescr>.  The cache (`_cache_size`) keeps the
                    // parent SizeDescr alive process-wide, so the field's
                    // Weak parent back-reference upgrades — a freshly built
                    // group would drop its size descr here (the op only
                    // carries the field) and dangle the parent.
                    majit_ir::descr::make_simple_descr_group_keyed_with_headerless(
                        u32::MAX,
                        p.size,
                        p.type_id as u32,
                        p.type_id,
                        p.vtable as usize,
                        p.is_gc_managed,
                        p.headerless,
                        &specs,
                        &[],
                    );
                    let struct_key = majit_ir::descr::LLType::Struct(p.type_id);
                    let cached = majit_ir::descr::gc_cache()
                        .lock()
                        ._cache_field
                        .get(&struct_key)
                        .and_then(|m| m.get(field_key))
                        .cloned();
                    if let Some(fd) = cached {
                        let fd: majit_ir::DescrRef = fd;
                        return (*offset, fd);
                    }
                    // Name-miss: the getfield names an inline aggregate
                    // (`ob_header`, `int_items`, an enum's `__pos_0`) that the
                    // flattened layout only represents through its leaves, so
                    // the by-name lookup finds nothing.  `heaptracker.py:68-69`
                    // recurses into a nested `lltype.Struct` without minting a
                    // descr for the container at all — `jtransform.py rewrite_op_getsubstruct
                    // rewrite_op_getsubstruct` lowers that access to
                    // `int_add(ptr, offset)`, no descr — so this whole branch
                    // exists only because pyre still emits a `getfield_gc` here.
                    // Until that lowering is ported, the container descr must at
                    // least obey the single-mint rule: go through
                    // `descr.py get_field_descr` so the pool-side and
                    // walker-side resolutions land on one Arc instead of each
                    // minting a fresh one per resolution.
                    let mut gc = majit_ir::descr::gc_cache().lock();
                    if gc._cache_size.contains_key(&struct_key) {
                        let fd = gc.get_field_descr(
                            struct_key,
                            field_key,
                            Some(name.as_str()),
                            *offset,
                            *field_size,
                            *field_type,
                            *is_immutable,
                            *is_quasi_immutable,
                            *field_flag,
                            heapcache_index_for_split_part(
                                *index_in_parent,
                                p,
                                name,
                                *offset,
                                *field_size,
                                *field_type,
                            ),
                            false,
                            *index_in_parent,
                            *load_is_acquire,
                        );
                        return (*offset, fd as majit_ir::DescrRef);
                    }
                } else {
                    // `all_fielddescrs` empty is not the same as "no owning
                    // struct": `descr.py parent_descr = get_size_descr(
                    // gccache, STRUCT, vtable)` derives the parent from the
                    // STRUCT itself, and the flattened field list only supplies
                    // `index_in_parent` (`descr.py`).  Mint the SizeDescr
                    // from what the producer did attach so the field carries a
                    // parent; without one `protect_speculative_field`
                    // (`llmodel.py`, which asserts the parent exists) has no
                    // type to validate against and fails closed, taking the
                    // whole bridge with it.
                    if p.type_id == 0 {
                        // Zero is the no-STRUCT-identity sentinel, not a type.
                        // Publishing under `LLType::Struct(0)` would collapse
                        // every type-id-less parent onto the first-inserted size
                        // descr and field namespace, so the second one would
                        // validate against the first one's size/vtable and could
                        // attach this field to the wrong parent.  Mint fresh
                        // instead — the same carve-out
                        // `simple_descr_group_from_bh_size`
                        // (`pyre-jit-trace/src/descr.rs`) takes.  Its group's
                        // size descr is registered strongly by
                        // `descr_registry::register_size`, so the field's Weak
                        // parent back-reference still upgrades.  The missing key
                        // says nothing about the STRUCT's shape, so
                        // `is_gc_managed`/`headerless` are carried through
                        // exactly as the keyed arm carries them:
                        // `bh_size_spec_from_descr` (`majit-translate`) reads
                        // both straight off a descr while taking `type_id` from
                        // `cache_key()`, so a raw or header-less parent with no
                        // key reaches here and must not regain a GC header.
                        if crate::majit_log_enabled() {
                            eprintln!(
                                "[jit] field_descr_ref_from_bh: fresh-minting a \
                                 type-id-less parent for field={name:?} size={} vtable={:#x}",
                                p.size, p.vtable
                            );
                        }
                        let spec = majit_ir::descr::SimpleFieldDescrSpec {
                            index: u32::MAX,
                            field_key: field_key.to_string(),
                            // A parentless field with no layout carrier:
                            // nothing declared, so the descr infers from the
                            // name.
                            is_class_word: None,
                            name: name.clone(),
                            offset: *offset,
                            field_size: *field_size,
                            field_type: *field_type,
                            is_immutable: *is_immutable,
                            is_quasi_immutable: *is_quasi_immutable,
                            flag: *field_flag,
                            virtualizable: false,
                            // Same floor as the sibling arm above: the spec type
                            // has no way to say "no slot was claimed".
                            index_in_parent: index_in_parent.unwrap_or(0),
                            load_is_acquire: *load_is_acquire,
                        };
                        let group = majit_ir::descr::make_simple_descr_group_with_flags(
                            u32::MAX,
                            p.size,
                            0,
                            p.vtable as usize,
                            p.is_gc_managed,
                            p.headerless,
                            std::slice::from_ref(&spec),
                        );
                        let fd = group.field_descrs[0].clone();
                        return (*offset, fd as majit_ir::DescrRef);
                    }
                    let struct_key = majit_ir::descr::LLType::Struct(p.type_id);
                    let mut gc = majit_ir::descr::gc_cache().lock();
                    // `immutable_flag` is `descr.py:112
                    // heaptracker.is_immutable_struct(STRUCT)`, which reads the
                    // STRUCT's `immutable` hint.  A serialized parent spec
                    // carries no such hint — size, type id, vtable, GC-managed
                    // and headerless are its whole payload — so `false` is not a
                    // choice made over an available alternative but the absence
                    // of the declaration channel, the same absence
                    // `get_field_descr`'s cache-hit branch already resolves for
                    // per-field immutability.  The sibling keyed mint just above
                    // lands on the same `false` through
                    // `SimpleSizeDescr::with_vtable`.
                    gc.get_size_descr(struct_key.clone(), p.size, p.vtable as usize, false);
                    let fd = gc.get_field_descr(
                        struct_key,
                        field_key,
                        Some(name.as_str()),
                        *offset,
                        *field_size,
                        *field_type,
                        *is_immutable,
                        *is_quasi_immutable,
                        *field_flag,
                        heapcache_index_for_split_part(
                            *index_in_parent,
                            p,
                            name,
                            *offset,
                            *field_size,
                            *field_type,
                        ),
                        false,
                        *index_in_parent,
                        *load_is_acquire,
                    );
                    return (*offset, fd as majit_ir::DescrRef);
                }
            }
            // No owning STRUCT at all, so the descr gets no `parent_descr` —
            // a state `descr.py` never produces, since `get_field_descr`
            // always resolves one. It is not a lost parent: every descr that
            // reaches here names a **raw, non-GC aggregate**, which upstream
            // gives no FieldDescr in the first place. `jtransform.py rewrite_op_getsubstruct
            // rewrite_op_getsubstruct` accepts only `gckind == 'raw'` and
            // lowers the access to `int_add(ptr, ofs)` with no descr; pyre
            // still emits a `getfield_gc`, so the descr exists with nothing to
            // own it. Porting that lowering is what removes this branch.
            //
            // Censused over the built descr table (`PYRE_FIELD_IDENTITY_CENSUS`,
            // 2026-08-04): 65 of 1514 Field slots, in three families, all raw —
            // `__pos_N` positional slots of closures / `Tuple<K,V>` /
            // `core::alloc::layout::Layout` (the bulk), the four fields of
            // `Arguments` (a plain Rust struct with no `#[jit_struct]`, so no
            // GC header and no type id), and one owner-less `Adt_0`.
            //
            // They are built but cold: `MAJIT_LOG=1` counts zero resolutions
            // through this branch across `fib_recursive`, `nbody` and
            // `spectral_norm`. So the cost today is the descr table entries,
            // not a declined speculation.
            //
            // The parent stays absent rather than being synthesised. Absent,
            // `protect_speculative_field` (`llmodel.py`) returns the
            // decline that its own `SpeculativeError` models — the speculation
            // is dropped, which is correct for a pointer that carries no type
            // id. A synthesised parent would instead hand its type-id compare a
            // fabricated `sizedescr.type_id()`, turning a safe decline into an
            // accept whenever that invented id happened to match.
            if crate::majit_log_enabled() {
                eprintln!(
                    "[jit] field_descr_ref_from_bh: parentless placeholder for \
                     field={name:?} offset={offset} size={field_size} type={field_type:?} \
                     has_parent={}",
                    parent.is_some()
                );
            }
            (
                *offset,
                Arc::new(
                    majit_ir::descr::SimpleFieldDescr::new(
                        0,
                        *offset,
                        *field_size,
                        *field_type,
                        *is_immutable,
                    )
                    .with_flag(*field_flag)
                    .with_load_is_acquire(*load_is_acquire),
                ) as majit_ir::DescrRef,
            )
        }
        other => panic!("getfield_gc/setfield_gc: descr is not a Field: {other:?}"),
    }
}

/// Build a `CanRaise` [`majit_ir::effectinfo::EffectInfo`] whose field write-set names `write_field`
/// of struct `type_id`, sharing the exact keyed `Arc<SimpleFieldDescr>` that a
/// `getfield_gc_i` on the same `(type_id, write_field)` resolves to.  A
/// residual helper that mutates a struct field through opaque host code —
/// changing a field of the currently selected struct, say — declares them so
/// `OptHeap::force_from_effectinfo` invalidates cached getfields after the
/// call.  Without it the residual call carries an empty write-set and the
/// optimizer can CSE-fold a mutable field load across the call.  This is the
/// residual analogue of the in-trace `setfield_gc` write barrier a traced
/// mutator would emit.
///
/// `fields` is the same `(offset, is_ref, name)` layout the matching getfield
/// passes to `register_struct_layout`; the parented size+field group is rebuilt
/// here identically (`make_simple_descr_group_keyed`, idempotent / first-write-
/// wins) so every field descr published into `gc_cache()._cache_field[Struct
/// (type_id)][name]` is the one `field_descr_ref_from_bh` reads back for its
/// getfield — pointer identity, which `compute_bitstrings` keys on.  Must run
/// before `finish_setup_descrs` (jitcode assembly does), matching the
/// non-trivial-raw-set construction-timing `call_descr` asserts.
///
/// `arrays` is the element-write half: `(item_size, is_item_signed)` per array
/// the residual mutates through its base pointer.  It cannot use the field
/// half's pointer-identity trick — a read's array descr comes from
/// `MetaInterpStaticData::dispatch_array_descr_cache` at trace time while this
/// one is minted during jitcode assembly, so the two are never the same `Arc`.
/// The array descrs built here therefore only have to carry the right SHAPE;
/// `EffectInfo::writes_array_descr_by_shape` is what reads them back, and the
/// remaining fields are pinned to the `Assembler::add_raw_int_array_descr_signed` shape
/// the reads intern (`base_size = 0`, no length header, `Type::Int`).
///
/// An empty `arrays` leaves the affirmative "writes no arrays" that
/// `EffectInfo::const_new` already installs, so a fields-only caller is
/// unaffected by the array half existing.
#[expect(
    clippy::type_complexity,
    reason = "This is the literal nested tuple/list/dict/callable shape at an RPython parity boundary; a wrapper would change structural ownership, while a one-use alias would conceal the audited upstream shape"
)]
pub fn residual_write_effect_info(
    layouts: &[(usize, u64, bool, &[(usize, bool, &str, usize, bool, bool)])],
    arrays: &[(usize, bool)],
    can_raise: bool,
) -> majit_ir::EffectInfo {
    // Mirror `JitCodeBuilder::field_specs_from_layout`: sort by offset so
    // `index_in_parent` is the stable by-offset rank, scalar = one machine word.
    let mut fds = Vec::new();
    for &(struct_size, type_id, is_gc_managed, fields) in layouts {
        let mut ordered: Vec<(usize, bool, &str, usize, bool, bool)> = fields.to_vec();
        ordered.sort_by_key(|&(offset, _, _, _, _, _)| offset);
        let specs: Vec<majit_ir::descr::SimpleFieldDescrSpec> = ordered
            .iter()
            .enumerate()
            .map(
                |(idx, &(offset, is_ref, name, decl_size, decl_signed, is_float))| {
                    // Same split as `field_specs_from_layout`: `get_type_flag`.
                    let (field_type, field_size, flag) = if is_ref {
                        (
                            majit_ir::value::Type::Ref,
                            jitcode::scalar_size(majit_ir::value::Type::Ref),
                            majit_ir::descr::ArrayFlag::Pointer,
                        )
                    } else if is_float {
                        (
                            majit_ir::value::Type::Float,
                            jitcode::scalar_size(majit_ir::value::Type::Float),
                            majit_ir::descr::ArrayFlag::Float,
                        )
                    } else {
                        let flag = if decl_signed {
                            majit_ir::descr::ArrayFlag::Signed
                        } else {
                            majit_ir::descr::ArrayFlag::Unsigned
                        };
                        (majit_ir::value::Type::Int, decl_size, flag)
                    };
                    majit_ir::descr::SimpleFieldDescrSpec {
                        index: u32::MAX,
                        field_key: name.to_string(),
                        // The layout table names fields but declares no header
                        // row, so the descr infers from the name.
                        is_class_word: None,
                        name: name.to_string(),
                        offset,
                        // Same width rule as the `field_specs_from_layout` twin
                        // this mirrors: a `Ref` field is one target word (4 on
                        // wasm32); an `Int` field is its declared storage, which is
                        // a machine word unless the emit site named it narrower.
                        field_size,
                        field_type,
                        is_immutable: false,
                        is_quasi_immutable: false,
                        flag,
                        virtualizable: false,
                        index_in_parent: idx,
                        load_is_acquire: false,
                    }
                },
            )
            .collect();
        majit_ir::descr::make_simple_descr_group_keyed(
            u32::MAX,
            struct_size,
            type_id as u32,
            type_id,
            0,
            is_gc_managed,
            &specs,
        );
        let struct_key = majit_ir::descr::LLType::Struct(type_id);
        fds.extend(fields.iter().map(|(_, _, write_field, _, _, _)| {
            majit_ir::descr::gc_cache()
                .lock()
                ._cache_field
                .get(&struct_key)
                .and_then(|m| m.get(*write_field))
                .cloned()
                .unwrap_or_else(|| {
                    panic!(
                        "residual_write_effect_info: field `{write_field}` not registered for type {type_id}"
                    )
                }) as majit_ir::DescrRef
        }));
    }
    let ads: Vec<majit_ir::DescrRef> = arrays
        .iter()
        .map(|&(item_size, is_item_signed)| {
            majit_ir::descr::make_array_descr_from_lltype_shape(
                /* type_id */ 0,
                // A raw slice data pointer: the base points straight at
                // `items[0]`, so there is no header to skip and no length word
                // to read.
                /* base_size */
                0,
                item_size,
                /* len_offset */ None,
                majit_ir::value::Type::Int,
                /* is_array_of_pointers */ false,
                /* is_array_of_structs */ false,
                is_item_signed,
                // The only arrays reachable here are the header-less buffers
                // an `array_fields` declaration names, which the reads intern
                // through `Assembler::add_raw_int_array_descr_signed`.  The shape
                // predicate ignores this flag, but a descr that disagreed with
                // the read it is meant to match would be a trap for the next
                // reader of either side.
                /* is_gc_managed */
                false,
                /* lendescr */ None,
                /* is_pure */ false,
                /* ei_index */ u32::MAX,
                /* interior_field_descrs */ Vec::new(),
            ) as majit_ir::DescrRef
        })
        .collect();
    let extra_effect = if can_raise {
        majit_ir::ExtraEffect::CanRaise
    } else {
        majit_ir::ExtraEffect::CannotRaise
    };
    let mut ei = majit_ir::EffectInfo::const_new(extra_effect, majit_ir::OopSpecIndex::None);
    ei._write_descrs_fields = Some(fds);
    ei._write_descrs_arrays = Some(ads);
    ei
}

pub trait JitCodeSym {
    fn begin_portal_op(&mut self, _pc: usize) {}
    fn commit_portal_op(&mut self) {}
    fn abort_portal_op(&mut self) {}
    fn total_slots(&self) -> usize;
    fn loop_header_pc(&self) -> usize;
    /// pyjitpl.py `opimpl_jit_merge_point(..., redboxes, orgpc)` →
    /// `reached_loop_header(greenboxes, redboxes)`: the boxes held by the
    /// merge point's red registers, in `(I, R, F)` operand order.
    /// `live_arg_boxes = greenboxes + redboxes` is built from these, so a
    /// sym whose merge point carries real red operands takes its reds from
    /// here. In a bridge the registers were rebuilt from the guard's resume
    /// data and do not sit at the loop's inputarg positions.
    fn set_redboxes(&mut self, _redboxes: &[(OpRef, majit_ir::Type)]) {}
    /// pyjitpl.py:2981-2989 `live_arg_boxes` — this merge point's
    /// loop-carried boxes, in the exact order the closing JUMP emits them.
    ///
    /// RPython builds `live_arg_boxes` ONCE per `reached_loop_header` and
    /// hands the same list to `current_merge_points.append` (the
    /// registration), to `compile_loop`'s LABEL and to `compile_trace`'s
    /// JUMP; `assert len(original_boxes) == len(live_arg_boxes)`
    /// (pyjitpl.py) is free there because there is only one list. The
    /// dispatch loop reaches a merge point with only `JitCodeSym` in scope,
    /// so this hook is how it gets at the construction that
    /// `JitState::collect_jump_args_with_boxes` uses for the close — the two
    /// MUST agree or the cut label's arity will not match the JUMP's
    /// (`compile.py:334 jump.numargs() == label.numargs()`).
    ///
    /// `vable_boxes` is `TraceCtx::collect_virtualizable_typed_boxes()`,
    /// identity last (this hook drops it, mirroring the `.pop()`).
    /// `None` = "no state-field construction" — the caller keeps its own
    /// fallback.
    fn loop_carried_boxes(
        &self,
        _vable_boxes: &[(OpRef, majit_ir::Type)],
    ) -> Option<Vec<(OpRef, majit_ir::Type)>> {
        None
    }

    /// Walk-final int+float scalar values in `collect_scalar_state_field_values`
    /// order, read off the portal frame (`IntOp.getint` / `FloatOp.getfloat_storage`).
    fn collect_portal_scalar_values(&self, _portal: &MIFrame, _ctx: &TraceCtx) -> Vec<i64> {
        Vec::new()
    }

    /// Walk-final ref scalar values, read off the portal frame (`RefOp.getref_base`).
    fn collect_portal_ref_scalar_values(&self, _portal: &MIFrame, _ctx: &TraceCtx) -> Vec<i64> {
        Vec::new()
    }

    // -- State field support (register/tape machines)
    //
    // When state_fields is configured, plain reds live in the portal
    // frame's identity slots (`MIFrame.setup_call`). These accessors are
    // leftover defaults; generated symbols do not override them.

    /// Read a scalar state field's current OpRef.
    fn state_field_ref(&self, _field_idx: usize) -> Option<OpRef> {
        None
    }

    /// Update a scalar state field's OpRef.
    fn set_state_field_ref(&mut self, _field_idx: usize, _value: OpRef) {}

    /// Read a scalar state field's current concrete value.
    fn state_field_value(&self, _field_idx: usize) -> Option<i64> {
        None
    }

    /// Update a scalar state field's concrete value.
    fn set_state_field_value(&mut self, _field_idx: usize, _value: i64) {}

    /// Read an array state field element's current OpRef.
    fn state_array_ref(&self, _array_idx: usize, _elem_idx: usize) -> Option<OpRef> {
        None
    }

    /// Update an array state field element's OpRef.
    fn set_state_array_ref(&mut self, _array_idx: usize, _elem_idx: usize, _value: OpRef) {}

    /// Read an array state field element's current concrete value.
    fn state_array_value(&self, _array_idx: usize, _elem_idx: usize) -> Option<i64> {
        None
    }

    /// Update an array state field element's concrete value.
    fn set_state_array_value(&mut self, _array_idx: usize, _elem_idx: usize, _value: i64) {}

    //
    // A ref state field (`selected: ref(Stack)`) is tracked in the ref
    // register bank so its OpRef carries `Type::Ref`; this gives
    // getfield_gc/setfield_gc on it stable box identity for heap caching.
    // Indexed separately from int scalars (its own `field_idx` space).

    /// Read a ref-typed scalar state field's current OpRef.
    fn state_ref_field_ref(&self, _field_idx: usize) -> Option<OpRef> {
        None
    }

    /// Update a ref-typed scalar state field's OpRef.
    fn set_state_ref_field_ref(&mut self, _field_idx: usize, _value: OpRef) {}

    /// Read a ref-typed scalar state field's current concrete value.
    fn state_ref_field_value(&self, _field_idx: usize) -> Option<i64> {
        None
    }

    /// Update a ref-typed scalar state field's concrete value.
    fn set_state_ref_field_value(&mut self, _field_idx: usize, _value: i64) {}

    //
    // Float state fields live in the float register bank and carry raw f64
    // bits in their concrete shadows.

    /// Read a float-typed scalar state field's current OpRef.
    fn state_float_field_ref(&self, _field_idx: usize) -> Option<OpRef> {
        None
    }

    /// Update a float-typed scalar state field's OpRef.
    fn set_state_float_field_ref(&mut self, _field_idx: usize, _value: OpRef) {}

    /// Read a float-typed scalar state field's current concrete bit pattern.
    fn state_float_field_value(&self, _field_idx: usize) -> Option<i64> {
        None
    }

    /// Update a float-typed scalar state field's concrete bit pattern.
    fn set_state_float_field_value(&mut self, _field_idx: usize, _value: i64) {}

    /// First float-bank register used as a canonical float identity slot.
    fn float_identity_slots_base(&self) -> usize {
        0
    }

    /// `StateFieldLayout::ref_scalar_slot`. `None` when this symbol has no
    /// ref-scalar identity slot for `field_idx`.
    fn ref_scalar_slot(&self, _field_idx: usize) -> Option<usize> {
        None
    }

    /// `StateFieldLayout::float_scalar_slot`. `None` when this symbol has no
    /// float-scalar identity slot for `field_idx`.
    fn float_scalar_slot(&self, _field_idx: usize) -> Option<usize> {
        None
    }

    /// `StateFieldLayout::array_elem_slot`. `None` when this symbol has no
    /// fixed-array element slot for `(array_idx, elem)`.
    fn array_elem_slot(&self, _array_idx: usize, _elem: usize) -> Option<usize> {
        None
    }

    /// First int-bank register used as a canonical identity slot
    /// (`int_scalar_base`). Identity slots occupy `[base, end)`; the base
    /// keeps the dispatch JitCode's int argument registers (`pc` at i0)
    /// out of the seeded range. Default 0 for symbols with no reserved
    /// argument prefix; the macro-generated symbol overrides it.
    fn int_identity_slots_base(&self) -> usize {
        0
    }

    /// Snapshot portal identity slots before an inline recursive-portal
    /// callee. Default `None`: reds live on the portal frame, so there is
    /// no `__JitSym` copy to nest.
    fn snapshot_inline_scalar_state(&self) -> Option<Vec<(majit_ir::OpRef, i64)>> {
        None
    }

    /// Reset leftover `__JitSym` scalar copies. Default no-op: those
    /// copies are gone.
    fn reset_inline_scalar_state_fresh(&mut self) {}

    /// Restore leftover `__JitSym` scalar copies. Default no-op.
    fn restore_inline_scalar_state(&mut self, _snapshot: Vec<(majit_ir::OpRef, i64)>) {}

    /// recursive-call recursive CALL_ASSEMBLER portal entry: build the fresh-frame
    /// reds for a recursive callee run.
    ///
    /// Returns the typed `Value` reds in `extract_live` order for a freshly
    /// allocated callee frame (scalars zeroed, arrays re-allocated at the
    /// caller's live capacity — read from this symbolic state's cached array
    /// lengths), together with an owner box keeping that freshly-allocated
    /// state alive for the callee's `execute_token_raw` run.  The fresh
    /// state's `&state` address is the vable identity embedded in the
    /// returned `Value::Ref` slots, so a guard failure inside the callee
    /// resumes into this scratch frame rather than the caller's state.
    ///
    /// `None` (the default, and for state shapes carrying ref scalars whose
    /// fresh value cannot be synthesized generically) means no portal-entry
    /// support, so the recursive dispatcher aborts to the interpreter
    /// fallback.
    fn recursive_fresh_entry_reds(&self) -> Option<(Vec<majit_ir::Value>, Box<dyn std::any::Any>)> {
        None
    }

    /// Capacities used only by the host allocator for each virtualizable
    /// identity in [`Self::recursive_fresh_entry_reds`].
    ///
    /// These are not portal reds. RPython's `do_recursive_call` passes the
    /// portal's declared red boxes unchanged; allocation sizing belongs to
    /// frame construction, not to the callee call signature.
    fn recursive_fresh_entry_vable_capacities(&self) -> Option<Vec<i64>> {
        None
    }

    /// recursive-call recursive CALL_ASSEMBLER portal entry: the host-Rust allocator and
    /// deallocator for a fresh callee state.
    ///
    /// Returns `(alloc, free)` raw function addresses where
    /// `alloc: extern "C" fn(capacity: i64) -> i64` returns a freshly
    /// `Box::into_raw`-ed state pointer (scalars zeroed, the single virt array
    /// allocated at `capacity`) and `free: extern "C" fn(ptr: i64)` drops it.
    /// The recursive dispatcher records a residual `CallR(alloc)` whose result
    /// feeds the CALL_ASSEMBLER `&state` red and a paired `CallN(free)` after
    /// the call, so the compiled caller loop allocates and frees the callee's
    /// scratch frame at runtime — the host-Rust analog of `gen_malloc_frame`
    /// (rewrite.py:665) for a callee whose vable is a host struct the IR cannot
    /// `New`.
    ///
    /// `None` (the default, and for any shape other than zero ref scalars + no
    /// fixed arrays + exactly one virt array) means the dispatcher aborts to
    /// the interpreter fallback.
    fn recursive_fresh_alloc_free_targets(&self) -> Option<(*const (), *const ())> {
        None
    }
}

pub trait JitCodeRuntime {
    fn label_at(&self, pc: usize) -> usize;

    /// Resolve a `JitCellToken.number` to the production
    /// `Arc<JitCellToken>` that the warm cell / `CompiledEntry::token` /
    /// `alive_loops` already hold.  When the dispatcher sees a
    /// `BC_CALL_ASSEMBLER_*` opcode it asks the runtime for the real Arc
    /// so the recorded descr carries production token identity
    /// (compile.py:187 parity) and skips the synth-Arc +
    /// `jitcell_token_by_number` keepalive fallback.  Returns `None` for
    /// standalone test runtimes that have no warmstate / metainterp.
    fn jitcell_token_arc_for_number(
        &self,
        _token_number: u64,
    ) -> Option<std::sync::Arc<majit_backend::JitCellToken>> {
        None
    }

    /// Recursive portal-call inline decision (pyjitpl.py _opimpl_recursive_call
    /// `opimpl_recursive_call` → `should_unroll_one_iteration` /
    /// `max_unroll_recursion`).  When the dispatcher meets a
    /// `BC_RECURSIVE_CALL_*` opcode it asks the runtime whether to inline
    /// the self-recursive portal call.  The production runtime mirrors
    /// `should_inline_core` through the shared `decide_recursive_inline`,
    /// which needs the callee green key (hashed from `green_values` against
    /// the driver's green spec) plus the trace's `inline_depth` and
    /// `recursive_depth`.  The default is `ResidualCall` so standalone test
    /// runtimes — and any consumer that has not opted in — never enter the
    /// inline path: the dispatcher aborts the trace, exactly as it did
    /// before this opcode family existed.
    fn recursive_inline_decision(
        &self,
        _jd_index: usize,
        _green_values: &[i64],
        _inline_depth: usize,
        _recursive_depth: usize,
    ) -> crate::pyjitpl::InlineDecision {
        crate::pyjitpl::InlineDecision::ResidualCall
    }

    /// Resolve the self-recursive portal jitcode for a `BC_RECURSIVE_CALL_*`
    /// opcode.  A recursive portal call targets the portal jitcode itself,
    /// which is not yet compiled at emit time (self-recursion), so the
    /// opcode carries the jitdriver index rather than a compiled target;
    /// the runtime maps that index back to the portal `JitCode` the
    /// metainterp is currently tracing.  Returns `None` for runtimes with
    /// no portal, in which case the dispatcher aborts the trace.
    fn portal_jitcode(&self, _jd_index: usize) -> Option<std::sync::Arc<JitCode>> {
        None
    }

    /// pyjitpl.py `is_main_jitcode` for a recursive portal this runtime
    /// is about to inline. Default false so fixture runtimes that never
    /// overflow keep an empty log.
    fn is_main_portal(&self, _jd_index: usize) -> bool {
        false
    }

    /// Resolve the CALL_ASSEMBLER target for a `BC_RECURSIVE_CALL_*`
    /// opcode whose inline decision came back `CallAssembler`
    /// (pyjitpl.py → `do_recursive_call(assembler_call=True)`).  The
    /// recursive portal call targets the portal's own compiled loop, keyed
    /// by the green values (the portal green key, pyjitpl.py
    /// `get_assembler_token(greenargs)`).  The runtime hashes the greens
    /// to that key and resolves the production `Arc<JitCellToken>` — used
    /// both for the recorded descr's token identity (compile.py:187 via
    /// `call_assembler_int_arc_typed_with_value`) and to drive the concrete loop
    /// through [`Self::execute_recursive_assembler_int`].  The `u64` is the
    /// resolved green key (compile.py:186 `rd_loop_token`), returned so the
    /// concrete leg keys the same loop the descr names.  Returns `None` for
    /// runtimes with no warmstate / no compiled callee, in which case the
    /// dispatcher aborts the trace and retries.
    fn recursive_call_assembler_target(
        &self,
        _jd_index: usize,
        _green_values: &[i64],
    ) -> Option<(std::sync::Arc<majit_backend::JitCellToken>, u64)> {
        None
    }

    /// Run the recursive callee's compiled loop concretely and return its
    /// integer result, advancing the concrete-shadow state so the caller's
    /// trace continues past the call with the real return value.  A
    /// compiled state-field portal loop exposes only a JITFRAME-ABI entry
    /// (`token._ll_function_addr`, invoked via `backend.execute_token_raw`
    /// which calloc's a frame and passes the frame ptr in reg0) — it is NOT
    /// a positional C-ABI function, so it cannot be called through
    /// `call_int_function`.  The runtime drives `execute_token_raw(token,
    /// reds)` (mirroring `run_compiled_raw_detailed_with_values`
    /// in `pyjitpl.rs`) and decodes the single int FINISH output.  `reds` are
    /// the marshalled red call args (greens are baked into the loop the
    /// `token` already names).  Returns `None` when the loop did not finish
    /// with an int result or when the runtime has no backend (the default,
    /// for standalone test runtimes), in which case the caller aborts.
    fn execute_recursive_assembler_int(
        &self,
        _token: &majit_backend::JitCellToken,
        _reds: &[Value],
    ) -> Option<i64> {
        None
    }

    /// Ref-result sibling of [`Self::execute_recursive_assembler_int`]
    /// (`call_assembler_ref` / `do_residual_call` tp == 'r').  Drives the
    /// callee loop's JITFRAME-ABI entry and decodes the single ref FINISH
    /// output as its raw `GcRef` bits (the same `as_usize() as i64` packing
    /// the `BC_CALL_ASSEMBLER_REF` arm stores through `set_ref_reg`).
    /// Returns `None` when the loop did not finish with a ref result or when
    /// the runtime has no backend (the default), in which case the caller
    /// aborts.
    fn execute_recursive_assembler_ref(
        &self,
        _token: &majit_backend::JitCellToken,
        _reds: &[Value],
    ) -> Option<i64> {
        None
    }

    /// Float-result sibling of [`Self::execute_recursive_assembler_int`]
    /// (`call_assembler_float` / `do_residual_call` tp == 'f').  Drives the
    /// callee loop's JITFRAME-ABI entry and decodes the single float FINISH
    /// output as its `f64::to_bits()` packing (the same `longlong.ZEROF`
    /// packing the `BC_CALL_ASSEMBLER_FLOAT` arm stores through
    /// `set_float_reg`).  Returns `None` when the loop did not finish with a
    /// float result or when the runtime has no backend (the default), in
    /// which case the caller aborts.
    fn execute_recursive_assembler_float(
        &self,
        _token: &majit_backend::JitCellToken,
        _reds: &[Value],
    ) -> Option<i64> {
        None
    }

    /// Void-result sibling of [`Self::execute_recursive_assembler_int`]
    /// (`call_assembler_void` / `do_residual_call` tp == 'v').  Drives the
    /// callee loop's JITFRAME-ABI entry for its side effects; there is no
    /// result to decode.  Returns `Some(())` when the loop finished and
    /// `None` when it did not finish or the runtime has no backend (the
    /// default), in which case the caller aborts.
    fn execute_recursive_assembler_void(
        &self,
        _token: &majit_backend::JitCellToken,
        _reds: &[Value],
    ) -> Option<()> {
        None
    }
}

pub struct ClosureRuntime<FLabel> {
    label_at: FLabel,
}

static SYMBOLIC_RESIDUAL_TRACE_ABORTS: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

/// Number of tracing attempts refused because a residual-call target was still
/// a symbolic path hash: once per reachable-set preflight refusal, however
/// many targets it names, plus once per per-instruction residual-call decline.
pub fn symbolic_residual_trace_aborts() -> u64 {
    SYMBOLIC_RESIDUAL_TRACE_ABORTS.load(std::sync::atomic::Ordering::Relaxed)
}

/// Print the missing-binding diagnostic once per distinct symbolic target.
fn report_symbolic_residual_call_target_once(func: i64, arg_classes: Option<&str>) {
    static REPORTED: std::sync::LazyLock<std::sync::Mutex<std::collections::BTreeSet<i64>>> =
        std::sync::LazyLock::new(|| std::sync::Mutex::new(std::collections::BTreeSet::new()));
    let first_report = REPORTED
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .insert(func);
    if first_report {
        if let Some(path) = super::resolve_symbolic_fnaddr_path(func) {
            eprintln!(
                "residual call target {func:#x} is symbolic path {path:?}, not a code address \
                 (arg classes {arg_classes:?}; None means the static reachable-set scan). The \
                 host did not bind this callee's path — add \
                 it to the fnaddr bindings passed to \
                 `EmbeddedJitCodeTable::materialize_with_symbolic_fnaddrs`."
            );
        } else {
            eprintln!(
                "residual call target {func:#x} is a symbolic path hash, not a code address \
                 (arg classes {arg_classes:?}; None means the static reachable-set scan). The \
                 host did not bind this callee's path — add \
                 it to the fnaddr bindings passed to \
                 `EmbeddedJitCodeTable::materialize_with_symbolic_fnaddrs`, and look the hash up \
                 in the host's symbolic-path table to see which path it names."
            );
        }
    }
}

/// Refuse a `BC_RECURSIVE_CALL_*` before its call has run.
///
/// `pyjitpl.py do_residual_call` writes the call's result
/// (`make_result_of_lastop`) before anything can raise `SwitchToBlackhole`,
/// so a blackhole resumed after the opcode always finds its result register
/// filled. A walk that refuses the call has run nothing and written nothing:
/// converting the post-decode framestack would resume past the call and read
/// whatever the result register held before. Refuse it the way an unbound
/// residual target is refused, so the portal replays the source arm.
fn refuse_unexecuted_recursive_call(ctx: &mut TraceCtx) -> TraceAction {
    ctx.symbolic_residual_abort = true;
    TraceAction::Abort
}

/// Report a residual call whose target is still a `symbolic_fnaddr_for_path`
/// placeholder, once per distinct target.
///
/// A placeholder means the host never bound that callee's path, so the address
/// is a hash of the path rather than code. Jumping to it faults somewhere with
/// no trace of which callee was missing, and answering 0 (the null-target arm
/// below) would quietly substitute a wrong result. `blackhole.rs` already
/// declines the same shape on its own residual-call handlers; this is the
/// tracing side of that check. Every caller returns [`TraceAction::Abort`]
/// before making the call, so discarding the recording needs no rollback.
fn report_symbolic_residual_call_target(
    ctx: &mut TraceCtx,
    func: i64,
    arg_classes: Option<&str>,
) -> TraceAction {
    ctx.symbolic_residual_abort = true;
    SYMBOLIC_RESIDUAL_TRACE_ABORTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    report_symbolic_residual_call_target_once(func, arg_classes);
    TraceAction::Abort
}

/// Refuse a residual call whose target address is null.
///
/// A path hash is refused above. Address 0 is the same hole with no hash:
/// recording it compiles a call of address 0. Decline the trace so the
/// interpreter runs the call.
fn refuse_null_residual_call_target(ctx: &mut TraceCtx, arg_classes: &str) -> TraceAction {
    static ONCE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if !ONCE.swap(true, std::sync::atomic::Ordering::Relaxed) {
        eprintln!("residual call target is null (arg classes {arg_classes:?}); refusing the trace");
    }
    ctx.symbolic_residual_abort = true;
    SYMBOLIC_RESIDUAL_TRACE_ABORTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    TraceAction::Abort
}

/// A walk-local `Dynamic` arrives as a small integer in a Ref register,
/// not a live cell. Residual-calling a helper that drops `Union` through
/// that address is `EXC_BAD_ACCESS`. Abort the walk the same way an
/// unbound symbolic target does, so the portal resumes at the merge point.
fn refuse_walk_local_ref_args(
    ctx: &mut TraceCtx,
    func: usize,
    raw_i: &[i64],
    raw_r: &[i64],
    args: &[OpRef],
    arg_classes: &str,
) -> Option<TraceAction> {
    let small_ref = raw_r.iter().any(|&ptr| {
        let addr = ptr as u64 as usize;
        addr != 0 && addr <= 0x1000
    });
    // `rir` is `operand_stack_store` / `operand_stack_take` of a
    // walk-local `Dynamic`. That address is a real stack slot, so the
    // small-integer check above cannot see it. `rr` is `dynamic_store` /
    // `push_from_cell`; those helpers refuse a non-heap cell themselves.
    let bridge_store = crate::is_bridge_walking() && matches!(arg_classes, "rir");
    // `rii` is `operand_stack_store_int` / `_bool`; `rif` is `_float`.
    // The first `i` is a stack depth. A walk local in that slot is a
    // pointer-sized word. Do not match plain `ri`: that class also
    // carries `track_operation` position bits (`line << 16`).
    // Only during a bridge walk: `rii`/`rif` is also `shift(n, c, mark)`
    // and other helpers whose first int is a payload, not a stack depth.
    let pointer_index = crate::is_bridge_walking()
        && matches!(arg_classes, "rii" | "rif")
        && raw_i.first().is_some_and(|&index| {
            let as_usize = index as u64 as usize;
            as_usize > 0x1_0000
        });
    if !small_ref && !bridge_store && !pointer_index {
        return None;
    }
    ctx.symbolic_residual_abort = true;
    if crate::is_bridge_walking() || ctx.is_bridge_trace {
        ctx.deterministic_bridge_abort = true;
    }
    SYMBOLIC_RESIDUAL_TRACE_ABORTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if crate::majit_log_enabled() {
        eprintln!(
            "[jit] residual refused: walk-local Ref/index arg \
             (fn={func:#x} classes={arg_classes} ints={raw_i:?} \
             refs={raw_r:?} bridge={})",
            crate::is_bridge_walking(),
        );
    }
    Some(TraceAction::Abort)
}

/// Root for a residual Ref result across `history.py` `record_nospec`.
///
/// `record_nospec` reads `ConstPtr.getref_base` only after `_record_op`.
/// `opencoder.py` `Trace._double_ops` can minor-collect inside that record,
/// before the frontend slot exists. The shadow stack is the Const's root;
/// [`Self::word`] is `getref_base` after the record.
struct ResidualRefRoot {
    depth: Option<usize>,
}

impl ResidualRefRoot {
    fn pin(word: i64) -> Self {
        if word == 0 {
            return Self { depth: None };
        }
        let depth = majit_gc::shadow_stack::push(majit_ir::GcRef(word as usize));
        Self { depth: Some(depth) }
    }

    fn word(&self, fallback: i64) -> i64 {
        match self.depth {
            Some(depth) => majit_gc::shadow_stack::get(depth).0 as i64,
            None => fallback,
        }
    }
}

impl Drop for ResidualRefRoot {
    fn drop(&mut self) {
        if let Some(depth) = self.depth.take() {
            // `try_pop_to` saturates: a panic already unwinding must not
            // assert in this drop and hide the original report.
            majit_gc::shadow_stack::try_pop_to(depth);
        }
    }
}

fn host_requested_walk_abort(
    ctx: &mut TraceCtx,
    func: usize,
    arg_classes: &str,
) -> Option<TraceAction> {
    if !crate::take_walk_abort() {
        return None;
    }
    ctx.symbolic_residual_abort = true;
    if crate::is_bridge_walking() || ctx.is_bridge_trace {
        ctx.deterministic_bridge_abort = true;
    }
    SYMBOLIC_RESIDUAL_TRACE_ABORTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if crate::majit_log_enabled() {
        eprintln!(
            "[jit] residual refused: host rejected walk-local Vm/index \
             (fn={func:#x} classes={arg_classes})"
        );
    }
    Some(TraceAction::Abort)
}

/// Refuse a trace whose statically reachable body contains an unbound
/// symbolic residual target, before the walk can execute any body instruction.
fn refuse_reachable_symbolic_residuals(jitcode: &JitCode) -> bool {
    let targets = &jitcode.reachable_symbolic_residuals().targets;
    if targets.is_empty() {
        return false;
    }

    // This whole-reachable-body gate is deliberately coarser than refusing at
    // the call: a symbolic target in an arm this trace would not take blocks
    // the portal too. Such a host cannot complete a trace that does reach the
    // target, and declining before the walk is preferable to duplicating an
    // earlier residual's heap effects.
    SYMBOLIC_RESIDUAL_TRACE_ABORTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    for &target in targets {
        report_symbolic_residual_call_target_once(target, None);
    }
    true
}

