/// `JitCodeRuntime` carrying the `label_at` /
/// `jitcell_token_arc_for_number` closures plus the recursive-call recursive-call
/// seams (inline decision, green-key target resolver, concrete loop
/// executor).  Used by `MetaInterp::interpret` so the
/// dispatcher resolves CALL_ASSEMBLER targets to their production Arcs via
/// `MetaInterp::jitcell_token_by_number` and routes recursive portal calls
/// through the production warmstate / backend.  All closures are built by
/// `MetaInterp::with_trace_ctx_and_token_resolver`, which split-borrows the
/// MetaInterp fields they read.
pub struct ClosureRuntimeWithResolver<
    FLabel,
    FResolve,
    FTarget,
    FDecision,
    FExec,
    FExecR,
    FExecF,
    FExecV,
> {
    label_at: FLabel,
    resolve_token: FResolve,
    recursive_target: FTarget,
    recursive_decision: FDecision,
    recursive_exec: FExec,
    recursive_exec_ref: FExecR,
    recursive_exec_float: FExecF,
    recursive_exec_void: FExecV,
}

impl<FLabel, FResolve, FTarget, FDecision, FExec, FExecR, FExecF, FExecV>
    ClosureRuntimeWithResolver<FLabel, FResolve, FTarget, FDecision, FExec, FExecR, FExecF, FExecV>
{
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        label_at: FLabel,
        resolve_token: FResolve,
        recursive_target: FTarget,
        recursive_decision: FDecision,
        recursive_exec: FExec,
        recursive_exec_ref: FExecR,
        recursive_exec_float: FExecF,
        recursive_exec_void: FExecV,
    ) -> Self {
        Self {
            label_at,
            resolve_token,
            recursive_target,
            recursive_decision,
            recursive_exec,
            recursive_exec_ref,
            recursive_exec_float,
            recursive_exec_void,
        }
    }
}

impl<FLabel, FResolve, FTarget, FDecision, FExec, FExecR, FExecF, FExecV> JitCodeRuntime
    for ClosureRuntimeWithResolver<
        FLabel,
        FResolve,
        FTarget,
        FDecision,
        FExec,
        FExecR,
        FExecF,
        FExecV,
    >
where
    FLabel: Fn(usize) -> usize,
    FResolve: Fn(u64) -> Option<std::sync::Arc<majit_backend::JitCellToken>>,
    FTarget: Fn(usize, &[i64]) -> Option<(std::sync::Arc<majit_backend::JitCellToken>, u64)>,
    FDecision: Fn(usize, &[i64], usize, usize) -> crate::pyjitpl::InlineDecision,
    FExec: Fn(&majit_backend::JitCellToken, &[Value]) -> Option<i64>,
    FExecR: Fn(&majit_backend::JitCellToken, &[Value]) -> Option<i64>,
    FExecF: Fn(&majit_backend::JitCellToken, &[Value]) -> Option<i64>,
    FExecV: Fn(&majit_backend::JitCellToken, &[Value]) -> Option<()>,
{
    fn label_at(&self, pc: usize) -> usize {
        (self.label_at)(pc)
    }

    fn jitcell_token_arc_for_number(
        &self,
        token_number: u64,
    ) -> Option<std::sync::Arc<majit_backend::JitCellToken>> {
        (self.resolve_token)(token_number)
    }

    fn recursive_inline_decision(
        &self,
        jd_index: usize,
        green_values: &[i64],
        inline_depth: usize,
        recursive_depth: usize,
    ) -> crate::pyjitpl::InlineDecision {
        (self.recursive_decision)(jd_index, green_values, inline_depth, recursive_depth)
    }

    fn recursive_call_assembler_target(
        &self,
        jd_index: usize,
        green_values: &[i64],
    ) -> Option<(std::sync::Arc<majit_backend::JitCellToken>, u64)> {
        (self.recursive_target)(jd_index, green_values)
    }

    fn execute_recursive_assembler_int(
        &self,
        token: &majit_backend::JitCellToken,
        reds: &[Value],
    ) -> Option<i64> {
        (self.recursive_exec)(token, reds)
    }

    fn execute_recursive_assembler_ref(
        &self,
        token: &majit_backend::JitCellToken,
        reds: &[Value],
    ) -> Option<i64> {
        (self.recursive_exec_ref)(token, reds)
    }

    fn execute_recursive_assembler_float(
        &self,
        token: &majit_backend::JitCellToken,
        reds: &[Value],
    ) -> Option<i64> {
        (self.recursive_exec_float)(token, reds)
    }

    fn execute_recursive_assembler_void(
        &self,
        token: &majit_backend::JitCellToken,
        reds: &[Value],
    ) -> Option<()> {
        (self.recursive_exec_void)(token, reds)
    }

    fn is_main_portal(&self, _jd_index: usize) -> bool {
        true
    }
}

/// JitCode bytecode interpreter for tracing.
///
/// Borrows `frames: &'mi mut MIFrameStack` from the owning
/// `MetaInterp<M>` so that pyre's runtime keeps a single canonical
/// framestack — matching `pyjitpl.py`'s `self.framestack` invariant
/// where MIFrame.run_one_step and the metainterp share one stack.
///
/// Trace-side helpers that have no MetaInterp handy can wrap an
/// interim stack via [`StandaloneFrameStack`] — the legacy entry
/// points (`trace_jitcode`, test fixtures) take that path.
pub struct JitCodeMachine<'mi, S, R> {
    frames: &'mi mut MIFrameStack,
    pub(super) last_exception_box: Option<OpRef>,
    pub(super) last_exception_value: i64,
    class_of_last_exc_is_const: bool,
    cpu: std::sync::Arc<dyn crate::cpu::Cpu>,
    issubclass: Option<fn(i64, i64) -> bool>,
    /// Outer interpreter pc captured BEFORE the
    /// `MIFrame::setup_call` reset (it sets `frame.pc = 0`),
    /// supplied by callers that walk through `setup_call` between
    /// `MIFrame::setup` and `run_to_end`.  When `Some(pc)`, `run_to_end`
    /// uses it for the `sym.begin_portal_op(pc)` hook and diagnostic
    /// eprintln output instead of the post-`setup_call` zero.  Mirrors
    /// RPython's portal pc handling where the outer interpreter pc is
    /// preserved across `setup_call` (the new callee frame's pc=0 lives
    /// on a separate frame).
    outer_program_pc: Option<usize>,
    /// `pyjitpl.py` `MetaInterp.seen_loop_header_for_jdindex` parity.
    ///
    /// `opimpl_loop_header(jdindex)` writes the per-driver index here so
    /// the next `opimpl_jit_merge_point` can verify the trace passed
    /// through a matching `loop_header` op (`pyjitpl.py`):
    ///
    /// ```text
    /// assert seen_loop_header_for_jdindex == jdindex
    /// seen_loop_header_for_jdindex = -1
    /// reached_loop_header(...)
    /// ```
    ///
    /// `-1` means "no `loop_header` seen since the last merge point" —
    /// the first iteration through the dispatch JitCode lands here
    /// (set by `with_framestack`).  Subsequent iterations enter
    /// `BC_JIT_MERGE_POINT` with this set to the per-driver `jdindex`
    /// because the previous arm's `BC_LOOP_HEADER` handler stamped it.
    /// Pyre's typed `i32` mirrors RPython's `int` (sentinel `-1`).
    seen_loop_header_for_jdindex: i32,
    /// Green register bytes from the last `BC_JIT_MERGE_POINT` decode.
    /// Finish re-reads those slots so a green write after the header is
    /// still in the resume banks.
    last_mp_green_i: Vec<u8>,
    last_mp_green_r: Vec<u8>,
    last_mp_green_f: Vec<u8>,
    /// Red register bytes from the last `BC_JIT_MERGE_POINT` decode.
    /// Header-revisit CloseLoop re-reads those slots (`prepare_list_of_boxes`).
    last_mp_red_i: Vec<u8>,
    last_mp_red_r: Vec<u8>,
    last_mp_red_f: Vec<u8>,
    marker: PhantomData<(S, R)>,
}

/// Owns an [`MIFrameStack`] for legacy `trace_jitcode` callers that
/// do not (yet) hand a `MetaInterp::framestack` borrow into the
/// jitcode interpreter.  Drops back to RPython parity once those
/// call sites migrate.
pub struct StandaloneFrameStack {
    pub frames: MIFrameStack,
}

// `MetaInterp.free_frames_list` for standalone walks that have no
// `MetaInterp`. The metainterp is the current thread's execution
// context; this list is the same pool that attribute would hold.
std::thread_local! {
    static STANDALONE_FREE_FRAMES: std::cell::RefCell<Vec<MIFrame>> =
        const { std::cell::RefCell::new(Vec::new()) };
}

impl StandaloneFrameStack {
    pub fn new() -> Self {
        let mut frames = MIFrameStack::empty();
        STANDALONE_FREE_FRAMES.with(|free| {
            frames.restore_free_frames(std::mem::take(&mut *free.borrow_mut()));
        });
        Self { frames }
    }
}

impl Drop for StandaloneFrameStack {
    fn drop(&mut self) {
        recycle_framestack(std::mem::replace(&mut self.frames, MIFrameStack::empty()));
    }
}

/// `pyjitpl.py MetaInterp.popframe` `free_frames_list.append(frame)`.
///
/// A standalone walk parks its frames on [`STANDALONE_FREE_FRAMES`] (the
/// `MetaInterp.free_frames_list` for walks that have no MetaInterp). Abort
/// used to `mem::take` the stack onto `TraceCtx.aborted_framestack` and then
/// drop it, so the next `StandaloneFrameStack::new` allocated a fresh
/// `MIFrame` (`vec![None; num_regs_and_consts_i]`, 72 B for nine int
/// slots) every deopt. Recycle through the same pool `new` reads.
/// Return `stack` to the standalone pool when the owner is done with it,
/// including early `return`s from `run_pending_abort_blackhole`.
pub struct RecycleFramestackOnDrop(pub MIFrameStack);

impl Drop for RecycleFramestackOnDrop {
    fn drop(&mut self) {
        recycle_framestack(std::mem::replace(&mut self.0, MIFrameStack::empty()));
    }
}

pub fn recycle_framestack(mut stack: MIFrameStack) {
    while let Some(frame) = stack.pop() {
        stack.recycle_frame(frame);
    }
    let parked = stack.take_free_frames();
    if parked.is_empty() {
        return;
    }
    STANDALONE_FREE_FRAMES.with(|free| {
        free.borrow_mut().extend(parked);
    });
}

impl Default for StandaloneFrameStack {
    fn default() -> Self {
        Self::new()
    }
}

struct ActiveStandardVirtualizable {
    vable_opref: OpRef,
    info: std::sync::Arc<crate::virtualizable::VirtualizableInfo>,
    obj: Box<i64>,
    root_depth: usize,
}

impl ActiveStandardVirtualizable {
    fn obj_ptr(&self) -> *mut u8 {
        *self.obj as usize as *mut u8
    }
}

impl Drop for ActiveStandardVirtualizable {
    fn drop(&mut self) {
        majit_gc::shadow_stack::pop_resume_ref_roots_to(self.root_depth);
    }
}

/// `abort/` and `abort/>r` both bail the trace out. The ref-result form
/// is what the assembler emits when the unsupported op still owns an SSA
/// result (`insns.rs` `BC_ABORT_RESULT_R`).
fn trace_abort_bytecode(bytecode: u8) -> bool {
    bytecode == jitcode::insns::BC_ABORT || bytecode == jitcode::insns::BC_ABORT_RESULT_R
}

impl<'mi, S, R> JitCodeMachine<'mi, S, R>
where
    S: JitCodeSym,
    R: JitCodeRuntime,
{
    fn active_standard_virtualizable(&self, ctx: &TraceCtx) -> Option<ActiveStandardVirtualizable> {
        let vable_opref = ctx.standard_virtualizable_box()?;
        let info = ctx.virtualizable_info()?.clone();
        let has_slot = self
            .frames
            .frames
            .iter()
            .rev()
            .any(|frame| frame.ref_regs.contains(&Some(vable_opref)));
        if !has_slot {
            return None;
        }
        let obj = ctx.box_bits(vable_opref)?;
        let root_depth = majit_gc::shadow_stack::resume_ref_roots_depth();
        Some(ActiveStandardVirtualizable {
            vable_opref,
            info,
            obj: Box::new(obj),
            root_depth,
        })
    }

    fn prepare_standard_virtualizable_before_residual_call(
        &mut self,
        ctx: &mut TraceCtx,
    ) -> Option<ActiveStandardVirtualizable> {
        let mut active = self.active_standard_virtualizable(ctx)?;
        unsafe {
            majit_gc::shadow_stack::push_resume_ref_roots(std::slice::from_mut(&mut *active.obj));
            active.info.tracing_before_residual_call(active.obj_ptr());
        }
        ctx.materialize_tokenless_virtualizable_before_residual_call();
        let force_token = ctx.force_token();
        if active.info.has_vable_token() {
            ctx.vable_setfield_descr(
                active.vable_opref,
                force_token,
                active.info.token_field_descr(),
            );
        }
        Some(active)
    }

    /// The escaping half of `vable_after_residual_call` (pyjitpl.py):
    /// `Some` when `tracing_after_residual_call` reports the virtualizable
    /// escaped during this CALL_MAY_FORCE.  Returns the still-rooted
    /// [`ActiveStandardVirtualizable`] so the caller can read the heap object
    /// before dropping the shadow-stack root.
    ///
    /// Two signals meet here.  The token check is the upstream one and answers
    /// "did the callee force the virtualizable".  It cannot answer for a callee
    /// handed the array's raw base address: such a callee never touches the
    /// token, and an `#[jit_interp]` machine has no token to touch
    /// (`without_vable_token`), so the check returns `false` for precisely the
    /// calls most able to invalidate the trace. `TraceCtx` carries that case
    /// from the array-base lowering to this post-call check.
    fn escaped_standard_virtualizable(
        ctx: &mut TraceCtx,
        active: Option<ActiveStandardVirtualizable>,
    ) -> Option<ActiveStandardVirtualizable> {
        // Drained before the `filter`, and unconditionally: with no active
        // virtualizable there is nothing to filter, and a signal left standing
        // would abort the next, unrelated residual call.
        let raw_base_escape = ctx.take_raw_vable_base_escape();
        active.filter(|active| {
            // Evaluated first and not short-circuited past: on a token-bearing
            // virtualizable this call is what clears the token back to NONE,
            // and skipping it would trip the `== 0` assert in
            // `tracing_before_residual_call` at the next call instead.
            let forced = unsafe { active.info.tracing_after_residual_call(active.obj_ptr()) };
            forced || raw_base_escape
        })
    }

    /// `pyjitpl.py` `get_list_of_active_boxes`: when
    /// `after_residual_call`, `pc` is the trailing `-live-` (`:194-198`).
    /// A residual whose calldescr was stamped `RandomEffects` but whose
    /// transform treated it as cannot-raise has no `-live-` (the next
    /// instruction is often an `int_copy` of the following funcptr).
    /// Snapshotting that pc decodes operand bytes as an `all_liveness`
    /// offset and indexes `constants_r` out of range.
    fn after_residual_live_pc(&self, ctx: &TraceCtx) -> Option<usize> {
        let frame = self.frames.frames.last()?;
        let pc = frame.code_cursor;
        let op_live = ctx.metainterp_sd().op_live as u8;
        (frame.jitcode.code.get(pc) == Some(&op_live)).then_some(pc)
    }

    /// `pyjitpl.py vable_after_residual_call` followed by
    /// `generate_guard(rop.GUARD_NOT_FORCED)`. The caller returns any result
    /// other than `Continue`: `SwitchToBlackhole` is the `ABORT_ESCAPE` raise,
    /// and continuing past it would compile the call with no GUARD_NOT_FORCED.
    fn finalize_standard_virtualizable_may_force(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        active: Option<ActiveStandardVirtualizable>,
    ) -> TraceAction {
        // `prepare_standard_virtualizable_before_residual_call` reaches the
        // materialize only through `active_standard_virtualizable(ctx)?`, so a
        // `None` here means no store was recorded before the call.  The reload
        // below still finds a box and a pointer through
        // `standard_virtualizable_box`/`_ptr`, and
        // `set_virtualizable_boxes_with_info` replaces every existing box, so
        // reloading without that materialize gives the trace heap reads with no
        // matching stores and reverts the loop-carried fields to their pre-call
        // values.  Pair the two on one predicate.
        let materialized = active.is_some();
        if let Some(active) = Self::escaped_standard_virtualizable(ctx, active) {
            // pyjitpl.py `self.load_fields_from_virtualizable()` runs
            // BEFORE the abort: the residual call forced the virtualizable and
            // wrote its fields through the heap object, so the tracing-time
            // box cache is stale.  Without this reload the blackhole rebuilds
            // the resumed interpreter state from the pre-call boxes and the
            // forced writes are lost.  The `MetaInterp` side already does this
            // (`vable_after_residual_call`); this dispatcher holds no
            // `MetaInterp`, so it calls the shared `TraceCtx` body directly.
            // `active` stays alive across the read to keep the shadow-stack
            // root for `obj_ptr` — its `Drop` pops that root.
            ctx.load_fields_from_virtualizable(&active.info, active.obj_ptr());
            // pyjitpl.py vable_after_residual_call `raise SwitchToBlackhole(ABORT_ESCAPE,
            // raising_exception=True)` — stash the upstream-orthodox
            // abort reason + `raising_exception` flag on TraceCtx so
            // jitdriver-side `aborted_tracing(stb.reason)` fires with
            // `ABORT_ESCAPE` instead of the generic too-long fallback.
            TraceAction::SwitchToBlackhole(crate::pyjitpl::SwitchToBlackhole::abort_escape())
        } else {
            // pyjitpl.py `generate_guard(rop.GUARD_NOT_FORCED)` runs the
            // recorded guard through `capture_resumedata(resumepc,
            // after_residual_call=True)` (pyjitpl.py) exactly like
            // the exception guards that follow it, so the guard reaches
            // `store_final_boxes_in_guard` with a valid `rd_resume_position`
            // (resume.py:396-397).  A bare `record_guard` leaves it at -1,
            // which the optimizer can only rescue through a patchguardop
            // ancestor.
            //
            // `code_cursor` is post-call and already points at this residual
            // call's trailing `-live-` marker, which the `after_residual_call`
            // snapshot reads directly (`MIFrame::get_list_of_active_snapshot_boxes`
            // in `pyjitpl/frame.rs`); `MIFrame::pc` is
            // only the saved resume position and stays 0 in an inline
            // sub-frame.  Same source as
            // `finish_residual_call_exception_path`, which records the
            // GUARD_NO_EXCEPTION that follows this guard.
            let Some(resume_pc) = self.after_residual_live_pc(ctx) else {
                // pyjitpl.py `generate_guard(rop.GUARD_NOT_FORCED)` is
                // unconditional after a may-force residual. A missing
                // trailing `-live-` cannot suppress that guard: the
                // compiled CALL_MAY_FORCE would then keep stale
                // virtualizable state when a later invocation forces.
                // Decline the trace so lowering can grow the marker;
                // do not emit the call unguarded.
                if materialized {
                    ctx.reload_tokenless_virtualizable_after_residual_call();
                }
                return TraceAction::Abort;
            };
            self.record_state_guard(
                ctx,
                sym,
                OpCode::GuardNotForced,
                &[],
                resume_pc,
                /* after_residual_call */ true,
            );
            if materialized {
                ctx.reload_tokenless_virtualizable_after_residual_call();
            }
            TraceAction::Continue
        }
    }

    /// Record a state-field-JIT guard.  Records the guard with no
    /// inline `op.fail_args` and attaches a snapshot built from the
    /// live `MIFrame` register banks (`pyjitpl.py MetaInterp.generate_guard`
    /// → `capture_resumedata`).  The optimizer's
    /// `store_final_boxes_in_guard` (`optimizeopt/mod.rs`) then
    /// derives `op.fail_args` from the snapshot via `_number_boxes`,
    /// matching `pyjitpl.py MetaInterp.generate_guard` +
    /// `opencoder.py capture_resumedata` +
    /// `resume.py store_final_boxes_in_guard`.
    ///
    /// `resume_pc` is the bytecode position blackhole resumes at on
    /// guard fail.  Mirrors RPython
    /// `MetaInterp.capture_resumedata(resumepc)` (`pyjitpl.py`)
    /// which temporarily swaps `frame.pc = resumepc`, captures the
    /// framestack snapshot, then restores the original `frame.pc` —
    /// keeping the snapshot's PC field aligned with the guard's
    /// resumepc independent of where the dispatcher's `frame.pc`
    /// currently points (typically past the just-decoded instruction
    /// args).
    fn record_state_guard(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        opcode: OpCode,
        args: &[OpRef],
        resume_pc: usize,
        after_residual_call: bool,
    ) -> OpRef {
        self.record_state_guard_with_value(
            ctx,
            sym,
            opcode,
            args,
            resume_pc,
            after_residual_call,
            None,
        )
    }

    /// Sibling of [`Self::record_state_guard`] that attaches `value` at
    /// construction (`history.py History._make_op`).
    /// `pyjitpl.py MetaInterp.generate_guard(GUARD_EXCEPTION)` records a
    /// `RefFrontendOp` with the exception value.
    fn record_state_guard_with_value(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        opcode: OpCode,
        args: &[OpRef],
        resume_pc: usize,
        after_residual_call: bool,
        value: Option<Value>,
    ) -> OpRef {
        // pyjitpl.py generate_guard parity:
        //     if isinstance(box, Const):    # no need for a guard
        //         return
        // The first arg of every DATA guard (GuardTrue/False, GuardValue,
        // GuardClass, ...) is the box being checked; box-less guards pass
        // args=&[] (gate is a no-op). GuardException is the extraarg-only guard
        // (RPython records it with box=None) -- its args[0] is the exception-class
        // Const, not a checked box, so the gate must NOT apply to it.
        if opcode != OpCode::GuardException
            && let Some(&first) = args.first()
            && first.is_constant()
        {
            return first;
        }
        // `pyjitpl.py MetaInterp.generate_guard` records the guard and then
        // captures its live MIFrames. It does not construct a second failarg
        // list (or type list) to decide whether the frame snapshot exists.
        // `resume.py ResumeDataVirtualAdder.finish` derives the final failargs
        // from that snapshot after optimization.
        let guard_op = ctx.record_guard_with_value(opcode, args, 0, value);
        self.publish_last_guard_resume_snapshot(
            ctx,
            sym,
            resume_pc,
            after_residual_call,
            GuardStampTarget::LastOp,
            Some(opcode),
        );
        guard_op
    }

    /// `pyjitpl.py MetaInterp.replace_box` framestack walk for the jitcode
    /// machine. `_nonstandard_virtualizable` calls it immediately.
    unsafe fn walk_miframe_stack(data: *mut (), oldbox: OpRef, newbox: OpRef) {
        let stack = unsafe { &mut *data.cast::<MIFrameStack>() };
        for frame in stack.frames.iter_mut() {
            frame.replace_active_box_in_frame(oldbox, newbox, Type::Ref);
        }
    }

    fn install_replace_frames(&mut self, ctx: &mut TraceCtx) {
        let frames = self.frames as *mut MIFrameStack;
        unsafe { ctx.set_replace_frames(Some(Self::walk_miframe_stack), frames.cast()) };
    }

    /// `pyjitpl.py MIFrame._nonstandard_virtualizable`: record the
    /// `isstandard` `PTR_EQ` and promote it through [`Self::implement_guard_value`]
    /// so the `GUARD_VALUE` captures the live framestack at record time
    /// (`generate_guard` → `capture_resumedata`).
    fn nonstandard_virtualizable(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        pc: usize,
        vable_opref: OpRef,
        fielddescr: &majit_ir::DescrRef,
    ) -> bool {
        match ctx.begin_nonstandard_virtualizable(pc, vable_opref, fielddescr) {
            NonstandardVable::Decided(nonstandard) => nonstandard,
            NonstandardVable::PendingEq {
                eqbox,
                isstandard,
                vable_opref,
                standard_box,
            } => {
                let promoted = self.implement_guard_value(ctx, sym, eqbox, isstandard, pc);
                ctx.commit_nonstandard_virtualizable(
                    promoted,
                    vable_opref,
                    standard_box,
                    fielddescr,
                )
            }
        }
    }

    /// `pyjitpl.py MetaInterp.capture_resumedata`: swap the top frame's
    /// `pc` to `resume_pc`, walk the live framestack, restore `pc`, stamp
    /// the guard. Identity slots already hold the portal reds
    /// (`MIFrame.setup_call` / the walk-start seed); capture does not
    /// copy them.
    ///
    /// `build_state_field_snapshot` reads `frame.pc` directly, so the swap
    /// pins the snapshot's `SnapshotFrame.pc` to the guard's resumepc
    /// independent of the dispatcher's post-decode `frame.pc`.
    ///
    /// `target` selects which recorded op receives the position: the last op,
    /// or a *guard* op counted back from the most recent one. They differ
    /// whenever the guard is not the last thing recorded —
    /// `emit_force_virtualizable` records GETFIELD_GC / PTR_NE / COND_CALL on
    /// top of the vable promote, so that caller needs the guard form or the
    /// position lands on the COND_CALL.
    ///
    /// `diag` carries the guard opcode for the
    /// `callee_rca` trace only; callers re-stamping a guard `TraceCtx`
    /// recorded internally pass `None`.
    fn publish_last_guard_resume_snapshot(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        resume_pc: usize,
        after_residual_call: bool,
        target: GuardStampTarget,
        diag: Option<OpCode>,
    ) {
        let top_idx = self
            .frames
            .frames
            .len()
            .checked_sub(1)
            .expect("publish_last_guard_resume_snapshot: empty framestack");
        let saved_top_pc = self.frames.frames[top_idx].pc;
        // `pyjitpl.py MetaInterp.capture_resumedata` swaps
        // `frame.pc = resumepc` (a JitCode bytecode PC) before the
        // framestack walk. `resume_pc` here is `opcode_pc =
        // code_cursor - 1`, the guard op's JitCode
        // position, whose `opcode_pc - SIZE_LIVE_OP` points at the LIVE
        // marker that `get_list_of_active_boxes` reads.
        // The snapshot's liveness decode REQUIRES this to be a JitCode
        // PC; using an interpreter PC underflows `pc - SIZE_LIVE_OP`.
        // For an `after_residual_call` guard
        // (`finish_residual_call_exception_path`) `resume_pc` is instead
        // the post-call `code_cursor` itself: it already points AT that
        // residual call's trailing LIVE marker, so the snapshot reads it
        // directly (`get_list_of_active_snapshot_boxes`) WITHOUT the `- SIZE_LIVE_OP`
        // step-back. `MIFrame::pc` (the saved resume position) stays 0 in
        // an inline sub-frame, so it must not be used here.
        self.frames.frames[top_idx].pc = resume_pc;
        if crate::bh_debug_enabled() {
            eprintln!(
                "[rec-guard] resume_pc={} frames={} root_i0_reg={:?} root_i0_val={:?}",
                resume_pc,
                self.frames.frames.len(),
                self.frames.frames[0].int_regs.first(),
                self.frames.frames[0]
                    .int_regs
                    .first()
                    .copied()
                    .flatten()
                    .and_then(|op| ctx.box_bits(op)),
            );
        }
        if crate::callee_rca_enabled() {
            let virtualizable_snapshot = ctx.virtualizable_boxes.clone().unwrap_or_default();
            let virtualref_snapshot = ctx.virtualref_boxes.clone();
            let vable_payload: Vec<_> = virtualizable_snapshot
                .iter()
                .enumerate()
                .map(|(idx, op)| {
                    let raw = ctx.box_value(*op).map(|value| match value {
                        majit_ir::Value::Int(v) => v,
                        majit_ir::Value::Ref(r) => r.as_usize() as i64,
                        majit_ir::Value::Float(v) => v.to_bits() as i64,
                        majit_ir::Value::Void => 0,
                    });
                    (idx, *op, raw)
                })
                .collect();
            eprintln!(
                "[callee-rca][record-guard] opcode={:?} resume_pc={} \
                 vable_boxes={} vref_boxes={}",
                diag,
                resume_pc,
                virtualizable_snapshot.len(),
                virtualref_snapshot.len(),
            );
            eprintln!("[callee-rca][record-guard-vable] {:?}", vable_payload);
        }
        // opencoder.py capture_resumedata writes `_snapshot_data` from
        // the framestack. The Vec<Snapshot> path stays for unit tests
        // that never attach the byte buffer.
        let snapshot_id = if ctx.recorder.has_byte_buffer() {
            ctx.capture_resumedata_from_framestack(&mut self.frames.frames, after_residual_call)
        } else {
            let op_live = ctx.metainterp_sd().op_live as u8;
            let all_liveness = ctx.metainterp_sd().liveness_info.snapshot_arc();
            let virtualizable_snapshot = ctx.virtualizable_boxes.clone().unwrap_or_default();
            let virtualref_snapshot = ctx.virtualref_boxes.clone();
            let snapshot = build_state_field_snapshot(
                self.frames,
                op_live,
                &all_liveness,
                after_residual_call,
                &virtualizable_snapshot,
                &virtualref_snapshot,
            );
            ctx.capture_resumedata(snapshot)
        };
        self.frames.frames[top_idx].pc = saved_top_pc;
        match target {
            GuardStampTarget::LastOp => ctx.set_last_guard_resume_position(snapshot_id),
            GuardStampTarget::GuardFromEnd(from_end) => {
                ctx.set_guard_op_resume_position_from_end(from_end, snapshot_id)
            }
        }
    }

    /// pyjitpl.py `MIFrame.implement_guard_value` — promote a box
    /// to a `Const`, guarding that the runtime value still matches.
    ///
    /// ```python
    /// def implement_guard_value(self, box, orgpc):
    ///     if isinstance(box, Const):
    ///         return box     # no promotion needed, already a Const
    ///     else:
    ///         promoted_box = executor.constant_from_op(box)
    ///         self.metainterp.generate_guard(rop.GUARD_VALUE, box, promoted_box,
    ///                                        resumepc=orgpc)
    ///         self.metainterp.replace_box(box, promoted_box)
    ///         return promoted_box
    /// ```
    ///
    /// `generate_guard` is reached here through [`Self::record_state_guard`],
    /// which walks the live framestack and the per-trace virtualizable /
    /// virtualref boxes (`pyjitpl.py capture_resumedata`). That is
    /// the whole point of promoting at this layer: `TraceCtx::promote_int`
    /// (`history.rs`) holds no `MIFrameStack`, so the snapshot it attaches
    /// carries empty `boxes` AND an empty `vable_boxes`, and a guard that
    /// survives optimization then deopts into a frame with no live registers
    /// and a zero-length vable section.
    ///
    /// The promoted constant goes out through [`Self::replace_box`], so a
    /// later read of any slot naming the box folds rather than re-guarding —
    /// including one in a caller frame that `MIFrame::setup_call` copied the
    /// same box into.
    fn implement_guard_value(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        box_: OpRef,
        runtime_value: i64,
        resume_pc: usize,
    ) -> OpRef {
        // `pyjitpl.py` `implement_guard_value`
        if box_.is_constant() {
            return box_;
        }
        // `executor.py` `constant_from_op`.
        let promoted_box = ctx.const_int(runtime_value);
        // `pyjitpl.py` `implement_guard_value`
        self.record_state_guard(
            ctx,
            sym,
            OpCode::GuardValue,
            &[box_, promoted_box],
            resume_pc,
            false,
        );
        // pyjitpl.py `replace_box`.
        self.replace_box(ctx, box_, promoted_box, Type::Int);
        // `pyjitpl.py` `implement_guard_value`
        promoted_box
    }

    /// `pyjitpl.py MetaInterp.replace_box(oldbox, newbox)`.
    ///
    /// The box has just been proven constant, so every record of it made
    /// during tracing has to name the constant instead: each frame's active
    /// boxes, and the virtualref, virtualizable and heapcache records
    /// `TraceCtx::replace_box` owns. Writing back the one register the
    /// opcode read leaves an alias in another register still naming the
    /// non-constant box.
    ///
    /// The concrete-value banks are not touched: the constant stands for the
    /// value the box already had, so every slot that named it already carries
    /// that value.
    fn replace_box(&mut self, ctx: &mut TraceCtx, oldbox: OpRef, newbox: OpRef, oldbox_type: Type) {
        for frame in self.frames.frames.iter_mut() {
            frame.replace_active_box_in_frame(oldbox, newbox, oldbox_type);
        }
        ctx.replace_box(oldbox, newbox);
    }

    /// `pyjitpl.py MIFrame._establish_nullity(box, orgpc)` — returns
    /// `box.nonnull()`, guarding it into the trace on the way.
    ///
    /// ```python
    /// value = box.nonnull()
    /// if heapcache.is_nullity_known(box):
    ///     profiler.count_ops(rop.GUARD_NONNULL, Counters.HEAPCACHED_OPS)
    ///     return value
    /// if value:
    ///     if not self.metainterp.heapcache.is_class_known(box):
    ///         self.metainterp.generate_guard(rop.GUARD_NONNULL, box, resumepc=orgpc)
    /// else:
    ///     if not isinstance(box, Const):
    ///         self.metainterp.generate_guard(rop.GUARD_ISNULL, box, resumepc=orgpc)
    ///         promoted_box = executor.constant_from_op(box)
    ///         self.metainterp.replace_box(box, promoted_box)
    /// heapcache.nullity_now_known(box)
    /// return value
    /// ```
    ///
    /// The nullity question is asked of the box directly — there is no
    /// comparison operation, and none of `GUARD_NONNULL` / `GUARD_ISNULL` /
    /// the two heapcache updates has an analogue in a `PTR_EQ` against null
    /// under a `GUARD_TRUE`.
    fn establish_nullity(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        src: OpRef,
        src_value: i64,
        opcode_pc: usize,
    ) -> bool {
        let value = src_value != 0;
        if ctx.heapcache_nullity_answered(src) {
            ctx.profiler().count_ops(
                OpCode::GuardNonnull,
                crate::pyjitpl::counters::HEAPCACHED_OPS,
            );
            return value;
        }
        if value {
            // A known class already implies non-null, so the guard would be
            // redundant.
            if !ctx.heap_cache().is_class_known(src) {
                self.record_state_guard(ctx, sym, OpCode::GuardNonnull, &[src], opcode_pc, false);
            }
        } else if !src.is_constant() {
            self.record_state_guard(ctx, sym, OpCode::GuardIsnull, &[src], opcode_pc, false);
            let null = ctx.const_null();
            self.replace_box(ctx, src, null, Type::Ref);
        }
        // majit's `nullity_now_known` also records WHICH nullity, where
        // upstream only sets the flag; `is_nullity_known` then answers
        // `Some(false)` for a known-null box rather than conflating it with
        // unknown.
        ctx.heap_cache_mut().nullity_now_known(src);
        value
    }

    /// `pyjitpl.py MIFrame.opimpl_goto_if_not(box, target, orgpc, replace)`.
    ///
    /// ```python
    /// switchcase = box.getint()
    /// if switchcase:
    ///     assert switchcase == 1
    ///     opnum = rop.GUARD_TRUE
    ///     promoted_box = CONST_1
    /// else:
    ///     opnum = rop.GUARD_FALSE
    ///     promoted_box = CONST_0
    /// self.metainterp.generate_guard(opnum, box, resumepc=orgpc)
    /// if not switchcase:
    ///     self.pc = target
    /// if isinstance(box, Const):
    ///     return
    /// if replace:
    ///     self.metainterp.replace_box(box, promoted_box)
    /// ```
    ///
    /// `replace=false` is the `goto_if_not_int_is_true` caller's, whose
    /// condbox "does not appear anywhere in any register" because the arm
    /// just made it.
    fn goto_if_not(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        opcode_pc: usize,
        cond: OpRef,
        cond_value: i64,
        target: usize,
        replace: bool,
    ) {
        let (guard, promoted_value) = if cond_value != 0 {
            // `assert switchcase == 1`. Every producer of this bytecode passes
            // a Rust `bool`, so the operand is 0 or 1 by construction — and
            // the `CONST_1` rebind below is only sound while that holds.
            debug_assert_eq!(cond_value, 1, "goto_if_not: operand is not a bool");
            (OpCode::GuardTrue, 1)
        } else {
            (OpCode::GuardFalse, 0)
        };
        self.record_state_guard(ctx, sym, guard, &[cond], opcode_pc, false);
        if cond_value == 0 {
            self.frames.current_mut().code_cursor = target;
        }
        if cond.is_constant() {
            return;
        }
        if replace {
            let promoted_box = ctx.const_int(promoted_value);
            self.replace_box(ctx, cond, promoted_box, Type::Int);
        }
    }

    /// A merge-point green pc is a guest position only when it is
    /// non-negative. `as usize` wraps a negative into a huge index and the
    /// dispatch loop resumes in unrelated code. `usize::MAX` is the
    /// no-position sentinel the loop already breaks on.
    fn guest_pc_position(pc: i64) -> usize {
        usize::try_from(pc).unwrap_or(usize::MAX)
    }

    /// pyjitpl.py `MIFrame._create_segmented_trace_and_blackhole`,
    /// recording half.
    ///
    /// ```python
    /// metainterp.generate_guard(rop.GUARD_ALWAYS_FAILS)
    /// ...
    /// metainterp.history.record1(rop.FINISH, exception_box, None, descr=token)
    /// ```
    ///
    /// The trace is close enough to `trace_limit` that aborting it would
    /// waste the whole recording, so it is terminated here instead: an
    /// always-failing guard takes every execution back to the interpreter,
    /// and the FINISH behind it exists only to give the segment a
    /// terminator.  The compile half needs the `MetaInterp` the walker
    /// does not hold, so it runs in the driver, in one of the two arms
    /// upstream branches to at pyjitpl.py:
    ///
    /// * [`TraceAction::SegmentedLoop`] — `compile_simple_loop` plus
    ///   `attach_procedure_to_interp` (pyjitpl.py).
    ///   `compile_simple_loop` puts a LABEL at the segment's entry, which
    ///   is what lets a later trace close back into it; without it the
    ///   segmented loop could never be completed (pyjitpl.py).
    /// * [`TraceAction::SegmentedBridge`] — `compile_trace(metainterp,
    ///   resumekey, [exception_box])` with the `target_token is not token`
    ///   give-up (pyjitpl.py).
    fn create_segmented_trace(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        mp_opcode_pc: usize,
        mp_green_pc: Option<i64>,
    ) -> TraceAction {
        // pyjitpl.py `generate_guard(rop.GUARD_ALWAYS_FAILS)`.  The
        // resume position is the merge-point op, whose preceding `-live-`
        // marker names the boxes the blackhole resumes with — the same
        // `(pc, after_residual_call=false)` pair the GUARD_FUTURE_CONDITION
        // emitted at loop close uses.
        self.record_state_guard(
            ctx,
            sym,
            OpCode::GuardAlwaysFails,
            &[],
            mp_opcode_pc,
            /* after_residual_call */ false,
        );
        // pyjitpl.py `_create_segmented_trace_and_blackhole`:
        // `exception_box = ConstInt(ptr2int(llexception.typeptr))` from
        // `jitexc.get_llexception` / `jitexc._get_standard_error`. Every
        // RPython program has the standard AssertionError; a majit host
        // without an exception hierarchy installs no hook, and the FINISH
        // is the unreachable one upstream records, so its ConstInt(0) is
        // never read.
        let typeptr = ctx
            .metainterp_sd()
            .host
            .assertion_error_typeptr
            .map_or(0, |f| f());
        let exception_box = ctx.const_int(typeptr);
        // pyjitpl.py:1639-1640 `if (metainterp.current_merge_points and
        // isinstance(metainterp.resumekey, compile.ResumeFromInterpDescr)):`
        // — a trace that owns a merge point and entered from the
        // interpreter becomes a segmented loop; anything else (a
        // guard-origin bridge) takes the else-arm.
        let is_loop_trace = ctx.current_merge_points_first_greenkey().is_some()
            && ctx.resumekey_original_loop_token().is_none();
        // pyjitpl.py `_create_segmented_trace_and_blackhole`:
        // `token = sd.exit_frame_with_exception_descr_ref;
        // history.record1(rop.FINISH, exception_box, None, descr=token)`,
        // recorded before the branch and seen by both arms.  The loop arm
        // keeps it here.  The bridge arm leaves it to
        // `compile_finish_from_active_session`, which is the port of
        // pyjitpl.py `compile_trace(metainterp, resumekey,
        // [exception_box])` and records the same FINISH with the same
        // descr.  Recording it here as well would give that trace two
        // terminators.
        if is_loop_trace {
            let token = ctx
                .metainterp_sd()
                .exit_frame_with_exception_descr_ref
                .clone()
                .expect("compile.py make_and_attach_done_descrs attaches exit_frame_with_exception_descr_ref");
            ctx.finish(&[exception_box], token);
        }
        // pyjitpl.py:1671-1673: "we now need to blackhole back to the
        // interpreter instead of jumping to some existing code, because we
        // are at a really arbitrary place here."  Under single-pass tracing
        // the walk already RAN everything it recorded, so the interpreter
        // must resume at this merge point's own green pc rather than at the
        // one it was left holding — the same handoff the abort path
        // publishes (`jitdriver.rs` `TraceAction::Abort` arm).  Without it
        // the walked iterations are executed a second time.
        ctx.walk_final_pc = mp_green_pc.map(Self::guest_pc_position);
        ctx.walk_final_reds = Vec::new();
        // pyjitpl.py:1673 `raise SwitchToBlackhole(ABORT_SEGMENTED_TRACE)`.
        if is_loop_trace {
            TraceAction::SegmentedLoop
        } else {
            TraceAction::SegmentedBridge { exception_box }
        }
    }

    /// Resolve the box operand for a vable opcode. The canonical
    /// bytecode (Stage 3a-3c) carries the live struct register as the
    /// leading `r` operand — pyjitpl.py:1166-1170
    /// `_opimpl_setfield_vable_*(struct, ...)` consumes it as the
    /// `struct` argument.
    fn resolve_vable_box(&mut self, vable_reg: usize) -> OpRef {
        self.frames.current_mut().ref_regs[vable_reg]
            .expect("jitcode ref register was uninitialized")
    }

    /// pyjitpl.py: vable field descriptor lookup.  Converts a bytecode
    /// `field_idx` to the cached `DescrRef` from `VirtualizableInfo`
    /// and pairs it with the box operand resolved by
    /// [`resolve_vable_box`].  Mirrors the upstream
    /// `(struct, fielddescr)` argument tuple of
    /// `_opimpl_getfield_vable_*` / `_opimpl_setfield_vable_*`.
    fn vable_field_descr(
        &mut self,
        ctx: &TraceCtx,
        vable_reg: usize,
        field_idx: usize,
    ) -> Option<(OpRef, majit_ir::DescrRef)> {
        let vable_opref = self.resolve_vable_box(vable_reg);
        let descr = ctx
            .virtualizable_info()
            .and_then(|info| info.static_field_descrs().get(field_idx).cloned());
        match descr {
            Some(descr) => Some((vable_opref, descr)),
            None => {
                let declared = ctx
                    .virtualizable_info()
                    .map(|info| info.static_field_descrs().len());
                self.report_absent_vable_descr("static field", field_idx, declared);
                None
            }
        }
    }

    /// Name the reason a vable descriptor lookup declined, under
    /// `MAJIT_VABLE_READ_PROBE`.
    ///
    /// Both causes — no `VirtualizableInfo` bound to the trace at all, and an
    /// index past the declared list — return `None` here and abort the walk
    /// identically, and the abort is reported by jitcode and cursor alone.
    /// Without this the two are indistinguishable from outside, and they call
    /// for opposite fixes: the first is a trace that was started without
    /// `initialize_virtualizable`, the second a codewriter index that does not
    /// match the runtime declaration.
    fn report_absent_vable_descr(&mut self, kind: &str, index: usize, declared: Option<usize>) {
        if !crate::vable_read_probe_enabled() {
            return;
        }
        let depth = self.frames.len();
        let frame = self.frames.current_mut();
        let cause = match declared {
            None => "no vinfo bound to the trace".to_owned(),
            Some(n) => format!("declared {n}"),
        };
        eprintln!(
            "[vable-read-probe] no {kind} descr jitcode={} depth={} cursor={} index={index} {cause}",
            frame.jitcode.name, depth, frame.code_cursor,
        );
    }

    /// Print one control-flow edge under `MAJIT_PCSEQ`
    /// (see `crate::pcseq_enabled`).
    ///
    /// `value` is the concrete word the edge was decided on and `target` the
    /// cursor it moves to, so a run's lines read as the walk's own path.
    /// `d=` is the frame depth and `jitcode=` the frame that owns the edge:
    /// an inlined callee prints too, because the edge that diverts a portal
    /// walk is routinely one of theirs.
    fn pcseq_branch(&mut self, kind: &str, opcode_pc: usize, value: i64, target: Option<usize>) {
        if !crate::pcseq_enabled() {
            return;
        }
        let depth = self.frames.len();
        let name = &self.frames.current_mut().jitcode.name;
        match target {
            Some(t) => eprintln!(
                "@@@PCSEQ {kind} d={depth} jitcode={name} pc={opcode_pc} value={value} -> {t}"
            ),
            None => eprintln!(
                "@@@PCSEQ {kind} d={depth} jitcode={name} pc={opcode_pc} value={value} -> fallthrough"
            ),
        }
    }

    /// pyjitpl.py: vable array descriptor lookup.  Converts a bytecode
    /// array index to the cached `(arrayfielddescr, arraydescr)` pair
    /// from `VirtualizableInfo` and pairs it with the box operand
    /// resolved by [`resolve_vable_box`].
    fn vable_array_descrs(
        &mut self,
        ctx: &TraceCtx,
        vable_reg: usize,
        array_idx: usize,
    ) -> Option<(OpRef, majit_ir::DescrRef, majit_ir::DescrRef)> {
        let vable_opref = self.resolve_vable_box(vable_reg);
        let pair = ctx.virtualizable_info().and_then(|info| {
            let fdescr = info.array_field_descrs().get(array_idx)?.clone();
            let adescr = info.array_descrs.get(array_idx)?.clone();
            Some((fdescr, adescr))
        });
        match pair {
            Some((fdescr, adescr)) => Some((vable_opref, fdescr, adescr)),
            None => {
                let declared = ctx
                    .virtualizable_info()
                    .map(|info| info.array_field_descrs().len());
                self.report_absent_vable_descr("array", array_idx, declared);
                None
            }
        }
    }

    /// Resolve a `d`-argcode descr index against the current frame's
    /// jitcode descrs pool and convert a `CanonicalBhDescr::Array` entry
    /// into a `DescrRef` suitable for `record_op_with_descr`.
    ///
    /// The dispatch JitCode body's opcode-fetch op (BC_GETARRAYITEM_GC_I)
    /// stores the array shape in the canonical pool
    /// (`jitcode/assembler.rs`'s `add_gc_byte_array_descr` →
    /// `CanonicalBhDescr::Array`). The
    /// trace-side recorder needs an `Arc<dyn Descr>` reference; the
    /// translation-wide `MetaInterpStaticData::dispatch_array_descr_cache`
    /// memoises the `Arc<SimpleArrayDescr>` so repeated resolutions of
    /// the same `descr_idx` across traces / bridges return identical
    /// Arcs (stable `Arc::ptr_eq` identity for the trace recorder's
    /// deduplication, optimizer's descr-keyed caches, and backend
    /// regalloc).  RPython's equivalent is `gccache._cache_array`
    /// (`descr.py:20` / `:348`), translation-wide; pyre mirrors the
    /// scope so cross-trace / cross-bridge descr identity holds.
    fn dispatch_array_descr_ref(
        &mut self,
        ctx: &TraceCtx,
        descr_idx: usize,
    ) -> Option<majit_ir::DescrRef> {
        let bh = self.frames.current_mut().runtime_bh_descr(descr_idx)?;
        // PyPy `llmodel.py unpack_arraydescr_size` opens with
        // `assert isinstance(arraydescr, ArrayDescr)` — a malformed
        // jitcode reaching the array-load path is a structural
        // invariant violation rather than a recoverable trace bail.
        // Per CLAUDE.md parity mapping (`RPython assert ↔ Rust
        // debug_assert!`) we mirror the assertion strength: the
        // non-Array case panics in debug builds; release falls through
        // to `None` (the outer `?` then aborts the trace).
        debug_assert!(
            matches!(bh, crate::jitcode::CanonicalBhDescr::Array { .. }),
            "BC_GETARRAYITEM_GC_I: descr_idx {} did not resolve to \
             CanonicalBhDescr::Array (got {:?}) — JitCode malformed",
            descr_idx,
            bh,
        );
        // PyPy `descr.py get_array_descr` keys `_cache_array` on
        // `ARRAY_OR_STRUCT` (the lltype itself), not on the codewriter
        // pool slot, so two emit sites resolving the same array shape
        // collapse to one descr Arc and two emit sites resolving
        // distinct shapes never collide.  Pyre lowered the IR to
        // `BhDescr::Array` before reaching this site, so the cache key
        // threads through every `BhDescr::Array` variant field —
        // mirroring the lltype-identity discrimination upstream
        // gets for free from `dict[ARRAY_OR_STRUCT]`.
        let (
            type_id,
            gc_type_id,
            base_size,
            itemsize,
            len_offset,
            item_type,
            is_array_of_pointers,
            is_array_of_structs,
            is_item_signed,
            is_gc_managed,
            ei_index,
            array_type_id,
            interior_fields,
            load_is_acquire,
        ) = match bh {
            crate::jitcode::CanonicalBhDescr::Array {
                type_id,
                gc_type_id,
                base_size,
                itemsize,
                len_offset,
                item_type,
                is_array_of_pointers,
                is_array_of_structs,
                is_item_signed,
                is_gc_managed,
                interior_fields,
                ei_index,
                array_type_id,
                load_is_acquire,
            } => (
                *type_id,
                *gc_type_id,
                *base_size,
                *itemsize,
                *len_offset,
                *item_type,
                *is_array_of_pointers,
                *is_array_of_structs,
                *is_item_signed,
                *is_gc_managed,
                *ei_index,
                array_type_id.clone(),
                interior_fields.clone(),
                *load_is_acquire,
            ),
            _ => return None,
        };
        // `ei_index` is intentionally NOT part of the cache key:
        // upstream `gccache._cache_array[ARRAY_OR_STRUCT]`
        // (`descr.py get_array_descr`) is keyed on the lltype itself, and the
        // ei_index slot is later assigned by `compute_bitstrings`
        // (`effectinfo.py`) — multiple descrs are free to share an
        // ei_index. It is still passed into
        // `make_array_descr_from_lltype_shape` below so the
        // first-built `SimpleArrayDescr` records the index via
        // `set_ei_index`; subsequent cache hits reuse that same Arc.
        //
        // `array_type_id` IS part of the cache key as the codewriter
        // lltype-identity proxy — two BhDescr::Array entries with
        // identical structural fields but different `array_type_id`
        // represent distinct ARRAYs upstream and must not collapse to
        // a single `SimpleArrayDescr` here.
        let cache_key = crate::pyjitpl::DispatchArrayDescrKey {
            type_id,
            base_size,
            itemsize,
            len_offset,
            item_type,
            is_array_of_pointers,
            is_array_of_structs,
            is_item_signed,
            is_gc_managed,
            array_type_id,
            interior_fields,
            load_is_acquire,
        };
        let cache = &ctx.metainterp_sd().dispatch_array_descr_cache;
        // `make_array_descr_from_lltype_shape` threads
        // `BhDescr::Array` discriminators into the resulting
        // `SimpleArrayDescr`: `type_id` (so cross-trace descr identity
        // stays distinct between two lltypes with the same primitive
        // shape), the pointer/struct flag selection (so `descr.flag`
        // matches RPython `descr.py get_type_flag` precedence),
        // the primitive sign carried on `is_item_signed`, `lendescr` /
        // `is_pure` (both `None` / `false` for the bytecode-array
        // dispatch path — pyre's `program: &[u8]` is a fixed-size
        // mutable buffer), and `ei_index` (`effectinfo.py compute_bitstrings`).
        // `ei_index` is passed in as a side slot stamped on the
        // resulting descr via `set_ei_index` so heap.rs
        // `force_from_effectinfo` (`heap.py`) reads the same
        // bitstring slot the producer wrote; it does NOT participate
        // in the cache key (upstream
        // `gccache._cache_array[ARRAY_OR_STRUCT]` keys on lltype
        // identity, and `compute_bitstrings` later assigns the index
        // slot as a derived attribute multiple descrs are free to
        // share).
        //
        // `arraydescr.all_interiorfielddescrs` (`descr.py`)
        // requires the per-field `SimpleInteriorFieldDescr` to share
        // the parent `Arc<SimpleArrayDescr>` identity, so it can only
        // be published AFTER the helper returns with a stable parent
        // Arc.  Pyre's dispatch path supplies an empty list (this
        // `debug_assert` pins it) — `program: &[u8]` items have no
        // inline-struct layout.
        debug_assert!(
            cache_key.interior_fields.is_empty(),
            "dispatch_array_descr_ref: BhDescr::Array carries non-empty \
             interior_fields {:?} but the descr-mint path here only \
             handles primitive-item arrays (program: &[u8] opcode \
             fetch).  Build per-field SimpleInteriorFieldDescrs from \
             the returned parent Arc and call \
             SimpleArrayDescr::set_all_interiorfielddescrs before \
             relying on the new shape.",
            cache_key.interior_fields,
        );
        Some(intern_dispatch_array_descr(cache, cache_key, || {
            // A length-prefixed array (`len_offset = Some`) needs a real
            // lendescr: the optimizer narrows the array's lenbound on a
            // constant-index read (`heap.py:676 getlenbound().make_gt_const`)
            // and the short preamble re-emits `ARRAYLEN_GC`, whose GC rewrite
            // reads `lendescr.offset()` (`rewrite.rs` ARRAYLEN_GC arm) to load
            // the length word.  Mirrors `descr.py get_field_arraylen_descr
            // get_field_arraylen_descr` — a `("len", ofs, WORD, FLAG_SIGNED)`
            // FieldDescr with no parent.  `program: &[u8]` keeps
            // `len_offset = None` (a fixed-size buffer with no length word) and
            // stays `lendescr = None`.
            let lendescr: Option<majit_ir::DescrRef> = len_offset.map(|ofs| {
                let d: majit_ir::DescrRef =
                    Arc::new(majit_ir::descr::SimpleFieldDescr::new_with_name(
                        u32::MAX,
                        ofs,
                        std::mem::size_of::<usize>(),
                        majit_ir::value::Type::Int,
                        false,
                        majit_ir::descr::ArrayFlag::Signed,
                        "len".to_string(),
                        "len",
                    ));
                d
            });
            majit_ir::descr::make_array_descr_from_lltype_shape(
                // TODO: `make_array_descr_from_lltype_shape`
                // takes the u32 gc tid; this caller has the u64 cache key.
                // Truncate `as u32` until gc_cache routing resolves the proper
                // allocated tid here.
                if gc_type_id != 0 {
                    gc_type_id
                } else {
                    type_id as u32
                },
                base_size,
                itemsize,
                len_offset,
                item_type,
                is_array_of_pointers,
                is_array_of_structs,
                is_item_signed,
                is_gc_managed,
                lendescr,
                false, // is_pure — bytecode array is mutable from the JIT's POV
                ei_index,
                Vec::new(),
            )
        }))
    }

    /// Sibling of [`dispatch_array_descr_ref`] returning the array
    /// geometry triple `(base_size, itemsize, is_item_signed)` from the
    /// canonical pool.  Used by `BC_GETARRAYITEM_GC_I`'s concrete-eval
    /// path so the byte/short/word/long load picks the right size +
    /// sign extension matching the descriptor — matching the
    /// dynasm-side `bh_getarrayitem_gc_i` impl
    /// (`runner.rs`) and PyPy's `llmodel.py
    /// unpack_arraydescr_size + read_int_at_mem(... size, sign)`.
    ///
    /// `debug_assert!` mirrors PyPy's `assert isinstance(arraydescr,
    /// ArrayDescr)` (`llmodel.py`); release falls through to
    /// `None` so the caller's `?` aborts the trace instead of
    /// panicking once `debug_assertions` is off.
    fn dispatch_array_geometry(&mut self, descr_idx: usize) -> Option<(usize, usize, bool)> {
        let bh = self.frames.current_mut().runtime_bh_descr(descr_idx)?;
        debug_assert!(
            matches!(bh, crate::jitcode::CanonicalBhDescr::Array { .. }),
            "BC_GETARRAYITEM_GC_I: descr_idx {} did not resolve to \
             CanonicalBhDescr::Array (got {:?}) — JitCode malformed",
            descr_idx,
            bh,
        );
        match bh {
            crate::jitcode::CanonicalBhDescr::Array {
                base_size,
                itemsize,
                is_item_signed,
                ..
            } => Some((*base_size, *itemsize, *is_item_signed)),
            _ => None,
        }
    }

    /// Construct a `JitCodeMachine` over an existing framestack borrow.
    ///
    /// The caller — typically `MetaInterp::interpret`
    /// or a [`StandaloneFrameStack`] wrapper — pushes the root MIFrame
    /// before calling and pops it after the machine returns.
    pub fn with_framestack(
        frames: &'mi mut MIFrameStack,
        _sub_jitcodes: &[Arc<JitCode>],
        _fn_ptrs: &[JitCallTarget],
    ) -> Self {
        Self {
            frames,
            last_exception_box: None,
            last_exception_value: 0,
            class_of_last_exc_is_const: false,
            cpu: crate::cpu::default_cpu(),
            issubclass: None,
            outer_program_pc: None,
            // pyjitpl.py:2882 / :2916 — sentinel "no loop_header seen yet".
            seen_loop_header_for_jdindex: -1,
            last_mp_green_i: Vec::new(),
            last_mp_green_r: Vec::new(),
            last_mp_green_f: Vec::new(),
            last_mp_red_i: Vec::new(),
            last_mp_red_r: Vec::new(),
            last_mp_red_f: Vec::new(),
            marker: PhantomData,
        }
    }

    pub fn set_cpu(&mut self, cpu: std::sync::Arc<dyn crate::cpu::Cpu>) {
        self.cpu = cpu;
    }

    pub fn set_issubclass(&mut self, issubclass: Option<fn(i64, i64) -> bool>) {
        self.issubclass = issubclass;
    }

    /// Called by [`trace_jitcode`]-style entry points that go through
    /// `MIFrame::setup_call` between `MIFrame::setup` and
    /// `run_to_end`.  `setup_call` resets `frame.pc = 0`
    /// (`pyjitpl/frame.rs`) — preserving the new callee frame's "fresh"
    /// pc-zero entry per RPython's `MIFrame.setup_call` shape — but
    /// that destroys the OUTER interpreter pc that `run_to_end` uses
    /// for `sym.begin_portal_op`.  Captures the pre-`setup_call` pc on
    /// the machine so `run_to_end` can anchor on the outer-interpreter
    /// program pc rather than the freshly-zeroed callee frame pc.
    pub fn set_outer_program_pc(&mut self, pc: usize) {
        self.outer_program_pc = Some(pc);
    }

    /// A root dispatch return finishes the source loop. Its ABI keeps the
    /// interpreter program counter in i0, which has already been advanced by
    /// the matched opcode arm. Preserve it before popping the frame so the
    /// single-pass merge hook resumes native execution at the source loop exit.
    /// The scalar state handoff rides `single_pass_scalar_values` (published by
    /// the jitdriver Finish arm); `value` is the terminator's own result, and
    /// it replaces `walk_finish_values` here so the hook returns the walk's
    /// result rather than a stale one from an earlier close.
    fn capture_single_pass_finish(&mut self, ctx: &mut TraceCtx, value: Option<Value>) {
        // `pyjitpl.py finishframe`: the root frame is still live here
        // (`target.is_none()`), then `popframe` drains it and
        // `jitexc.DoneWithThisFrame*` carries `resultbox`. A guard-resume
        // walk never calls `set_outer_program_pc`; skipping the result
        // because that slot is empty drops `resultbox` and the portal
        // runner re-enters from pc 0.
        if self.frames.len() != 1 {
            return;
        }
        if let Some(pc) = self
            .frames
            .current_mut()
            .int_regs
            .first()
            .copied()
            .flatten()
            .and_then(|op| ctx.box_bits(op))
            && let Ok(pc) = usize::try_from(pc)
        {
            ctx.walk_final_pc = Some(pc);
        }
        self.snapshot_live_portal_greens(ctx);
        ctx.walk_finish_values.clear();
        ctx.walk_finish_values.extend(value);
    }

    /// Read the last merge-point green registers off the live portal frame.
    ///
    /// `handle_jitexception` takes those values from
    /// `ContinueRunningNormally`. A Halt after a green write is not at a
    /// merge point, so this is the header-register snapshot. Abort,
    /// SegmentedLoop, too-long, and the last-portal-frame pop (Continue)
    /// re-read the same slots: the previous merge-point *values* would
    /// otherwise overwrite a later write.
    fn snapshot_live_portal_greens(&mut self, ctx: &mut TraceCtx) {
        if !(self.last_mp_green_i.is_empty()
            && self.last_mp_green_r.is_empty()
            && self.last_mp_green_f.is_empty())
        {
            ctx.portal_green_regs_i.clone_from(&self.last_mp_green_i);
            ctx.portal_green_regs_r.clone_from(&self.last_mp_green_r);
            ctx.portal_green_regs_f.clone_from(&self.last_mp_green_f);
            if let Some(frame) = self.frames.frames.first() {
                ctx.snapshot_portal_greens_from_frame(
                    &frame.int_regs,
                    &frame.ref_regs,
                    &frame.float_regs,
                );
            }
        }
        self.snapshot_live_portal_reds(ctx);
    }

    /// Re-read merge-point red registers off the live portal frame.
    ///
    /// `opimpl_jit_merge_point` feeds `redboxes` into `reached_loop_header`
    /// (`prepare_list_of_boxes`) only at a merge point. Abort / too-long /
    /// Continue before that first merge point still have empty
    /// `last_mp_red_*`, and copying them would replace a valid earlier
    /// snapshot with an empty one. Skip the re-read until a merge point
    /// has listed reds, matching `snapshot_live_portal_greens`.
    fn snapshot_live_portal_reds(&mut self, ctx: &mut TraceCtx) {
        if !(self.last_mp_red_i.is_empty()
            && self.last_mp_red_r.is_empty()
            && self.last_mp_red_f.is_empty())
        {
            ctx.portal_red_regs_i.clone_from(&self.last_mp_red_i);
            ctx.portal_red_regs_r.clone_from(&self.last_mp_red_r);
            ctx.portal_red_regs_f.clone_from(&self.last_mp_red_f);
            let Some(frame) = self.frames.frames.first() else {
                return;
            };
            ctx.snapshot_portal_reds_from_frame(
                &frame.int_regs,
                &frame.ref_regs,
                &frame.float_regs,
            );
        }
    }

    fn read_typeptr_from_exception(&self, exc_value: i64) -> i64 {
        // model.py: ConstPtr wrap then cpu.cls_of_box(box).
        let const_box = majit_ir::operand::Operand::const_from_value(majit_ir::Value::Ref(
            majit_ir::GcRef(exc_value as usize),
        ));
        self.cpu.cls_of_box(&const_box)
    }

    /// rclass.ll_issubclass parity (mirrors the blackhole-side
    /// `handler_goto_if_exception_mismatch` in `blackhole.rs`).
    /// `set_issubclass` wires the active
    /// backend/MetaInterp subclass-range resolver; the standalone fallback
    /// is exact-match only for fixtures without a GC descriptor.
    fn issubclass_of(&self, typeptr: i64, bounding_class: i64) -> bool {
        if let Some(callback) = self.issubclass {
            callback(typeptr, bounding_class)
        } else {
            typeptr == bounding_class
        }
    }

    /// pyjitpl.py `MetaInterp.clear_exception()`:
    ///
    /// ```python
    /// def clear_exception(self):
    ///     self.last_exc_value = lltype.nullptr(rclass.OBJECT)
    /// ```
    ///
    /// `last_exc_box` is intentionally left untouched: PyPy's
    /// `handle_possible_exception` overwrites it whenever
    /// `last_exc_value` becomes non-NULL again, and every reader
    /// (`opimpl_last_exception`, `opimpl_last_exc_value`,
    /// `opimpl_goto_if_exception_mismatch`) gates on `last_exc_value`
    /// before reading the box.
    ///
    /// `BH_LAST_EXC_VALUE` is a structural adapter — the TLS shim used
    /// by `bh_call_*_dispatch` to surface a callee's exception across
    /// the C boundary.  Clearing it together with `last_exception_value`
    /// keeps the two halves of pyre's split exception channel in sync
    /// (RPython has a single `last_exc_value` field that the executor
    /// writes directly).
    pub fn clear_exception(&mut self) {
        self.last_exception_value = 0;
        crate::blackhole::BH_LAST_EXC_VALUE.with(|c| c.set(0));
    }

    /// Pop the current frame during a return / exception unwind.  Restores
    /// the caller's nested standard vable (installed by a recursive-portal
    /// INLINE frame on push) and returns the frame's nested sym scalar-state
    /// snapshot, if any, so a `sym`-holding caller can restore it (this
    /// method has no `sym` in scope).
    fn pop_exception_frame(&mut self, ctx: &mut TraceCtx) -> Option<Vec<(OpRef, i64)>> {
        if let Some(mut frame) = self.frames.pop() {
            if frame.inline_frame {
                ctx.pop_inline_frame();
            }
            // pyjitpl.py finishframe_exception -> popframe(
            // leave_portal_frame=True): a portal frame whose push recorded
            // ENTER_PORTAL_FRAME unwinds through here, so record the matching
            // LEAVE_PORTAL_FRAME just as the normal-return pop does.
            if frame.portal_entered {
                // pyjitpl.py `popframe`: `portal_call_depth -= 1` then
                // `leave_portal_frame` when `jitcode.jitdriver_sd`.
                ctx.adjust_portal_call_depth(-1);
                let jd_box = ctx.const_int(frame.portal_jd as i64);
                ctx.record_op(OpCode::LeavePortalFrame, &[jd_box]);
                if frame.portal_trace_logged {
                    ctx.push_portal_trace_event(frame.portal_jd, None, ctx.get_trace_position());
                }
            }
            let portal_scalar_state = frame.portal_scalar_state.take();
            self.frames.recycle_frame(frame);
            portal_scalar_state
        } else {
            None
        }
    }

    fn unwind_to_exception_handler(&mut self, ctx: &mut TraceCtx) -> TraceAction {
        const SIZE_LIVE_OP: usize = majit_jitcode::liveness::OFFSET_SIZE + 1;

        while !self.frames.is_empty() {
            let mut handled = false;
            {
                let frame = self.frames.current_mut();
                let code = &frame.jitcode.code;
                let mut position = if frame.pc != 0 || frame.code_cursor == 0 {
                    frame.pc
                } else {
                    frame.code_cursor
                };

                if position < code.len() {
                    let mut opcode = code[position];
                    if opcode == jitcode::insns::BC_LIVE {
                        position += SIZE_LIVE_OP;
                        if position < code.len() {
                            opcode = code[position];
                        }
                    }
                    if opcode == jitcode::insns::BC_CATCH_EXCEPTION && position + 2 < code.len() {
                        let target =
                            u16::from_le_bytes([code[position + 1], code[position + 2]]) as usize;
                        frame.pc = target;
                        frame.code_cursor = target;
                        handled = true;
                    } else if opcode == jitcode::insns::BC_RVMPROF_CODE && position + 2 < code.len()
                    {
                        let leaving_idx = code[position + 1] as usize;
                        let unique_id_idx = code[position + 2] as usize;
                        let leaving = frame.getint(ctx, leaving_idx).unwrap_or(0);
                        let unique_id = frame.getint(ctx, unique_id_idx).unwrap_or(0);
                        majit_rlib::rvmprof::cintf::jit_rvmprof_code(leaving, unique_id);
                    }
                }
            }
            if handled {
                let frame = self.frames.current_mut();
                if frame.jitcode.code[frame.last_opcode_position] != jitcode::insns::BC_RERAISE {
                    super::record_application_traceback(
                        self.last_exception_value,
                        ctx.virtualizable_heap_ptr().unwrap_or(std::ptr::null()),
                        frame,
                    );
                }
                return TraceAction::Continue;
            }
            {
                let frame = self.frames.current_mut();
                super::record_application_traceback(
                    self.last_exception_value,
                    ctx.virtualizable_heap_ptr().unwrap_or(std::ptr::null()),
                    frame,
                );
            }
            self.pop_exception_frame(ctx);
        }
        // RPython parity for `pyjitpl.py:2533-2538`: framestack drained
        // without finding a `catch_exception`, so close the trace with
        // a FINISH carrying `last_exc_box` and let the normal
        // `TraceAction::Finish` dispatch path run `finish_and_compile`
        // (mirrors `compile_exit_frame_with_exception` →
        // `compile.compile_trace(...)`, `pyjitpl.py`).
        // `Abort` is only correct when there is no pending exception —
        // that happens when `BC_RERAISE` fires with no prior
        // `last_exception_value` (the `BC_RERAISE` arm in this file already
        // shortcuts to Abort for that case, so here the exception slot
        // is guaranteed non-zero).
        if let Some(exc_box) = self.last_exception_box {
            // `pyjitpl.py excvalue = self.last_exc_value`, snapshotted
            // next to `last_exc_box` so the consumer can raise it after the
            // compile (`pyjitpl.py:2558-2562`).
            let exc_value = self.last_exception_value;
            // Upstream's `last_exc_value` dies with the MetaInterp the moment
            // `finishframe_exception` raises out of it.  Pyre's half of that
            // state is the `BH_LAST_EXC_VALUE` TLS shared with the blackhole,
            // and every *other* way out of a frame clears it (`clear_exception`
            // at each `BC_*_RETURN`).  This exit hands the value to the caller
            // on the action instead, so the channel closes here too — leaving it
            // set makes the interpreter re-surface the trace's exception at its
            // next residual-call boundary.
            self.clear_exception();
            TraceAction::Finish {
                finish_args: vec![exc_box],
                finish_arg_types: vec![majit_ir::Type::Ref],
                exit_with_exception: true,
                exc_value,
            }
        } else {
            TraceAction::Abort
        }
    }

    fn finish_residual_call_exception_path(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        effectinfo: &majit_ir::descr::EffectInfo,
    ) -> TraceAction {
        let exc = crate::blackhole::BH_LAST_EXC_VALUE.with(|c| c.get());
        if !effectinfo.check_can_raise(false) {
            // pyjitpl.py:1956 / :3397-3398
            //     def assert_no_exception(self):
            //         assert not self.last_exc_value
            // RPython `assert` survives translation as a runtime check —
            // mirror that strength with `assert!` rather than the looser
            // `debug_assert!` so a contract-violating cannot-raise call
            // never silently continues with stale TLS state.
            assert_eq!(
                exc, 0,
                "residual call with cannot-raise EffectInfo set BH_LAST_EXC_VALUE={exc:#x}"
            );
            return TraceAction::Continue;
        }

        // pyjitpl.py generate_guard always passes the recorded
        // op through `capture_resumedata(resumepc, after_residual_call)`.
        // For GUARD_NO_EXCEPTION / GUARD_EXCEPTION (and GUARD_NOT_FORCED /
        // GUARD_ALWAYS_FAILS) `after_residual_call=True` so the snapshot
        // walks `frame.pc` directly instead of stepping back to the
        // preceding LIVE marker (`MIFrame::get_list_of_active_boxes` in
        // `pyjitpl/frame.rs` / pyjitpl.py).
        // `next_u*()` advances `code_cursor`; unlike RPython's single `pc`,
        // `MIFrame::pc` is only the saved resume position.  Capture the
        // post-call bytecode cursor so the snapshot reads the trailing
        // `-live-` marker for this residual call.
        let Some(resume_pc) = self.after_residual_live_pc(ctx) else {
            // pyjitpl.py `handle_possible_exception` always
            // `generate_guard(GUARD_EXCEPTION)` or
            // `generate_guard(GUARD_NO_EXCEPTION)`. A missing trailing
            // `-live-` cannot skip that guard: the compiled residual would
            // then follow the recorded success path when a later invocation
            // raises, or unwind without GUARD_EXCEPTION. Decline the trace
            // so lowering can grow the marker; do not emit the call unguarded.
            return TraceAction::Abort;
        };

        if exc == 0 {
            self.record_state_guard(
                ctx,
                sym,
                OpCode::GuardNoException,
                &[],
                resume_pc,
                /* after_residual_call */ true,
            );
            return TraceAction::Continue;
        }

        // pyjitpl.py execute_ll_raised(..., constant=False) is the path used
        // by residual calls, then handle_possible_exception() records
        // GUARD_EXCEPTION and finishframe_exception() unwinds from the current
        // frame.
        self.last_exception_value = exc;
        self.class_of_last_exc_is_const = false;
        let class_is_const = self.class_of_last_exc_is_const;
        let typeptr = self.read_typeptr_from_exception(exc);
        let exc_class_box = ctx.const_int(typeptr);
        let guard_op = self.record_state_guard_with_value(
            ctx,
            sym,
            OpCode::GuardException,
            &[exc_class_box],
            resume_pc,
            /* after_residual_call */ true,
            Some(Value::Ref(majit_ir::GcRef(exc as usize))),
        );
        self.last_exception_box = Some(if class_is_const {
            ctx.const_ref(exc)
        } else {
            guard_op
        });
        self.class_of_last_exc_is_const = true;
        self.unwind_to_exception_handler(ctx)
    }

    /// pyjitpl.py handle_possible_exception parity for
    /// CALL_ASSEMBLER_* arms.  CALL_ASSEMBLER always can raise (the
    /// callee is arbitrary compiled code), so there is no
    /// `check_can_raise` gate — the exception path is unconditional.
    fn finish_call_assembler_exception_path(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
    ) -> TraceAction {
        let exc = crate::blackhole::BH_LAST_EXC_VALUE.with(|c| c.get());
        // `code_cursor` is post-call and points at this CALL_ASSEMBLER's
        // trailing `-live-` marker. `MIFrame::pc` is only the saved resume
        // position and stays 0 in an inline sub-frame, so do not use it for
        // this after-residual-call snapshot.
        let resume_pc = self.frames.current_mut().code_cursor;

        if exc == 0 {
            self.record_state_guard(
                ctx,
                sym,
                OpCode::GuardNoException,
                &[],
                resume_pc,
                /* after_residual_call */ true,
            );
            return TraceAction::Continue;
        }

        self.last_exception_value = exc;
        self.class_of_last_exc_is_const = false;
        let class_is_const = self.class_of_last_exc_is_const;
        let typeptr = self.read_typeptr_from_exception(exc);
        let exc_class_box = ctx.const_int(typeptr);
        let guard_op = self.record_state_guard_with_value(
            ctx,
            sym,
            OpCode::GuardException,
            &[exc_class_box],
            resume_pc,
            /* after_residual_call */ true,
            Some(Value::Ref(majit_ir::GcRef(exc as usize))),
        );
        self.last_exception_box = Some(if class_is_const {
            ctx.const_ref(exc)
        } else {
            guard_op
        });
        self.class_of_last_exc_is_const = true;
        self.unwind_to_exception_handler(ctx)
    }

    /// Fused `goto_if_not_<cmp>` recording, mirroring
    /// `opimpl_goto_if_not_<cmp>` (pyjitpl.py). Two fast paths skip
    /// the compare op + guard:
    ///  - same-box (pyjitpl.py `if <not float> and b1 is b2`): `x <cmp> x`
    ///    is statically determined (FASTPATHS_SAME_BOXES), so neither the
    ///    compare nor a guard is recorded; gated off for float opcodes.
    ///  - both-constant: `self.execute(<CMP>, b1, b2)` folds to a `Const` via
    ///    `execute_and_record` when `_all_constants(b1, b2)` (pyjitpl.py)
    ///    so nothing is recorded, and `opimpl_goto_if_not` then sees a `Const`
    ///    condbox so `generate_guard` records no guard either (pyjitpl.py,
    ///    2583).
    ///    Only a non-constant, non-same-box operand pair materialises the compare
    /// + guard. The branch is followed identically in all cases (`taken`
    ///   already reflects the concrete condition): `taken` = condition true =
    ///   fall through; `!taken` jumps to `target`.
    #[expect(
        clippy::too_many_arguments,
        reason = "The parameter order mirrors the corresponding RPython metainterpreter routine; grouping arguments into a Rust-only context object would obscure line-by-line parity and frame ownership"
    )]
    fn record_or_fold_fused_guard(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        opcode: OpCode,
        lhs: OpRef,
        rhs: OpRef,
        taken: bool,
        opcode_pc: usize,
        target: usize,
    ) {
        // pyjitpl.py:547 `if <not float> and b1 is b2:` same-box fast path:
        // `x <cmp> x` is statically determined (FASTPATHS_SAME_BOXES: eq/le/ge
        // => True, ne/lt/gt => False), so neither the compare op nor a guard
        // is recorded. Gated off for float opcodes because NaN breaks
        // reflexivity (`NaN <cmp> NaN` is not constant). `b1 is b2` is object
        // identity; for `OpRef` producers that is position equality, so
        // distinct variables never collide and the predicate can only fire on
        // a genuinely identical box. `taken` already carries the concrete
        // (constant) result, so the trailing branch handling is shared.
        //
        // The two operands of a self-compare usually reach this point as
        // distinct register copies (the codewriter colours each into its own
        // `SameAsI`/`SameAsR` slot), so `same_box` is false here and the
        // residual `int_eq(x, x)` is instead folded by the optimizer's `_eq`
        // rule (`autogenintrules.rs autogen_eq_b`); this fast path fires only
        // when the operands genuinely share a register.
        let is_float = matches!(
            opcode,
            OpCode::FloatLt
                | OpCode::FloatLe
                | OpCode::FloatEq
                | OpCode::FloatNe
                | OpCode::FloatGt
                | OpCode::FloatGe
        );
        let same_box = !is_float && lhs.same_box(rhs);
        if !same_box {
            let cond = ctx.execute_and_record(
                Some(self.cpu.as_ref()),
                opcode,
                None,
                &[lhs, rhs],
                Some(majit_ir::Value::Int(taken as i64)),
                self.last_exception_value,
            );
            let guard = if taken {
                OpCode::GuardTrue
            } else {
                OpCode::GuardFalse
            };
            // `generate_guard`'s `if isinstance(box, Const): return` is
            // `record_state_guard`'s own first gate, so a folded `cond`
            // suppresses the guard without a second test here.
            self.record_state_guard(ctx, sym, guard, &[cond], opcode_pc, false);
        }
        if !taken {
            self.frames.current_mut().code_cursor = target;
        }
    }

    fn stash_portal_reds(&self, ctx: &mut TraceCtx, sym: &S) {
        // `reached_loop_header` builds a fresh `live_arg_boxes` each visit
        // from the `jit_merge_point` operands (`prepare_list_of_boxes`).
        // Scalar writeback values still come off the portal frame.
        //
        // `pyjitpl.py finishframe` compiles with the portal frame's boxes
        // still live (`compile_done_with_this_frame`); `virtualizable.py`
        // `write_from_resume_data_partial` then writes every static field
        // back. The typed-return opimpls stash those identity-slot values
        // before popping the frame. `run_to_end` restashes on every
        // non-Continue; with the stack already drained that restash must
        // not clear the return snapshot, or a `void_return` Finish writes
        // nothing and the native suffix reads the trace-start reds.
        let Some(root) = self.frames.frames.first() else {
            return;
        };
        ctx.close_scalar_values = None;
        ctx.close_ref_scalar_values = None;
        let scalars = sym.collect_portal_scalar_values(root, ctx);
        if !scalars.is_empty() {
            ctx.close_scalar_values = Some(scalars);
        }
        let refs = sym.collect_portal_ref_scalar_values(root, ctx);
        if !refs.is_empty() {
            ctx.close_ref_scalar_values = Some(refs);
        }
    }

    /// `pyjitpl.py` `MetaInterp._interpret`: step the top frame until the
    /// framestack drains or a step returns a terminal action. After each
    /// continued step, `TraceCtx::is_too_long` aborts the trace the way
    /// `MetaInterp.blackhole_if_trace_too_long` does.
    pub fn run_to_end(&mut self, ctx: &mut TraceCtx, sym: &mut S, runtime: &R) -> TraceAction {
        self.install_replace_frames(ctx);
        // SAFETY: the guard is a local of this call and `ctx` is borrowed for
        // longer, so it is dropped while the `TraceCtx` it names is alive.
        let _clear = unsafe { ClearReplaceFrames::new(ctx) };
        // A previous walk may have left a committed-residual latch.
        let _ = crate::take_residual_committed();
        // Same latch class: a blackhole residual that refused a walk-local
        // arms `request_walk_abort` with no walker to consume it. The next
        // walk must not die on its first `run_one_step`.
        if crate::take_walk_abort() && crate::majit_log_enabled() {
            eprintln!("[jit] dropped leftover walk-abort at run_to_end");
        }
        // Stable program-pc anchor for the state-field-JIT portal op —
        // the outer interpreter pc that `trace_jitcode` was invoked with.
        // Survives `BC_INLINE_CALL`'s `frame.pc = frame.code_cursor`
        // mutation and `record_state_guard`'s `frame.pc = resume_pc`
        // swap, both of which corrupt the live `frame.pc` past the
        // portal-entry instant.
        //
        // Prefer `self.outer_program_pc` when supplied — entries that
        // go through `MIFrame::setup_call` between `MIFrame::setup` and
        // `run_to_end` (e.g. the `trace_jitcode` / `trace_jitcode_with_args`
        // wrappers) capture the outer pc BEFORE the `setup_call` reset
        // (`MIFrame::setup_call` sets `self.pc = 0`).  Without that, the portal-op
        // bookkeeping and diagnostics would anchor on the freshly-zeroed
        // callee entry instead of the actual interpreter pc.  Falls back
        // to `frame.pc` for callers that skip `setup_call` (e.g. legacy
        // `framestack`-borrow paths where the frame is already populated
        // upstream).
        let portal_pc = self
            .outer_program_pc
            .unwrap_or_else(|| self.frames.current_mut().pc);
        sym.begin_portal_op(portal_pc);
        while !self.frames.is_empty() {
            // Catch panics from BigInt overflow in runtime stack operations.
            // RPython doesn't have this issue (no BigInt); we abort the trace.
            let action = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                self.run_one_step(ctx, sym, runtime)
            })) {
                Ok(a) => a,
                Err(payload) => {
                    if crate::majit_log_enabled() {
                        let message = if let Some(msg) = payload.downcast_ref::<&str>() {
                            *msg
                        } else if let Some(msg) = payload.downcast_ref::<String>() {
                            msg.as_str()
                        } else {
                            "<non-string panic payload>"
                        };
                        eprintln!(
                            "[jit] trace_jitcode panic while tracing pc={}: {}",
                            self.frames.current_mut().pc,
                            message
                        );
                    }
                    // The unwind left `code_cursor` inside the panicking
                    // instruction, so the frames name no resumable position.
                    ctx.abort_after_panic = true;
                    self.snapshot_live_portal_greens(ctx);
                    sym.abort_portal_op();
                    return TraceAction::Abort;
                }
            };
            if !matches!(action, TraceAction::Continue) {
                self.stash_portal_reds(ctx, sym);
                if (crate::majit_log_enabled() || crate::tldbg_enabled()) && self.frames.is_empty()
                {
                    // Every `Finish` return drains the framestack first.
                    eprintln!(
                        "[interpret] run_to_end action={:?} ops={} framestack drained",
                        action,
                        ctx.num_recorded_ops(),
                    );
                } else if crate::majit_log_enabled() || crate::tldbg_enabled() {
                    let fr = self.frames.current_mut();
                    let last_op = fr
                        .jitcode
                        .code
                        .get(fr.last_opcode_position)
                        .copied()
                        .unwrap_or(0xff);
                    let why = match last_op {
                        jitcode::insns::BC_UNREACHABLE => "unreachable",
                        jitcode::insns::BC_ABORT => "abort",
                        jitcode::insns::BC_ABORT_PERMANENT => "abort-permanent",
                        _ => "",
                    };
                    eprintln!(
                        "[interpret] run_to_end action={:?} ops={} cursor={} last_op=0x{last_op:02x} reason={why} jitcode={}",
                        action,
                        ctx.num_recorded_ops(),
                        fr.code_cursor,
                        fr.jitcode.name(),
                    );
                }
                if matches!(
                    action,
                    TraceAction::Abort
                        | TraceAction::SwitchToBlackhole(_)
                        | TraceAction::SegmentedLoop
                        | TraceAction::SegmentedBridge { .. }
                ) {
                    // A degraded-stub abort (`BC_ABORT` jitcode) applied
                    // nothing. The merge-point greens already on the ctx
                    // are the CRN banks; re-reading live i0 after the
                    // shared prologue would resume one byte past the
                    // opcode (`warmspot.py handle_jitexception` reads
                    // green_int[0]).
                    let stub_abort = matches!(action, TraceAction::Abort)
                        && self.frames.frames.len() > 1
                        && self.frames.frames.last().is_some_and(|f| {
                            f.jitcode.code.as_slice() == [crate::jitcode::insns::BC_ABORT]
                        });
                    if !stub_abort {
                        self.snapshot_live_portal_greens(ctx);
                    }
                }
                match action {
                    TraceAction::CloseLoop | TraceAction::Finish { .. } => sym.commit_portal_op(),
                    _ => sym.abort_portal_op(),
                }
                return action;
            }
            // pyjitpl.py `_interpret`:
            //
            //     while True:
            //         self.framestack[-1].run_one_step()
            //         self.blackhole_if_trace_too_long()
            //
            // The overflow is answered right here — `pyjitpl.py raise
            // SwitchToBlackhole(ABORT_TOO_LONG)` — even though a source opcode
            // may be half-executed, because its handler (pyjitpl.py
            // `run_blackhole_interp_to_cancel_tracing` → blackhole.py
            // `convert_and_run_from_pyjitpl`) finishes the current jitcode
            // frames in the blackhole before control returns to the
            // interpreter, so the opcode's remaining effects still run.
            //
            // The check sits below the action test for the same reason it sits
            // after `run_one_step()` upstream: a step that raises its own
            // terminal exception never reaches `blackhole_if_trace_too_long`,
            // so a closing step commits its trace even when that step pushed
            // the recorded op count past `trace_limit`.
            if ctx.is_too_long() {
                if crate::majit_log_enabled() {
                    eprintln!(
                        "[jit] trace_jitcode aborting: trace too long at portal pc={}",
                        portal_pc
                    );
                }
                self.stash_portal_reds(ctx, sym);
                self.snapshot_live_portal_greens(ctx);
                sym.abort_portal_op();
                return TraceAction::Abort;
            }
        }

        // The jitcode ran to completion (all frames empty).  The overflow check
        // above ran on every step that got here, so the trace is within budget.
        sym.commit_portal_op();
        TraceAction::Continue
    }

    /// Execute a `BC_RECURSIVE_CALL_*` opcode (pyjitpl.py _opimpl_recursive_call
    /// `opimpl_recursive_call`).
    ///
    /// Payload matches `jtransform.py handle_recursive_call` /
    /// `blackhole.py bhimpl_recursive_call_*`:
    ///   jdindex `i` (const-pool register), then `I R F I R F` lists,
    ///   then the dest byte for a typed result (`recursive_call_v` has none).
    ///
    /// `result_kind` is `Some(Int/Ref/Float)` for the typed opcodes and
    /// `None` for the void opcode.  The green register sources carry the
    /// portal green key in green declaration order; each green's
    /// `JitArgKind` selects the register bank it is read from (a ref
    /// `program` green from the ref bank, an int `pc` green from the int
    /// bank), so the concrete green value hashes against
    /// `green_args_spec`.  `green_pc` (the concrete of the first green,
    /// or 0) keys the per-depth `recursive_depth` count and seeds the
    /// portal frame's entry pc — the first green is the int portal pc.
    ///
    /// This mirrors the `BC_INLINE_CALL` machinery (frame push, argument
    /// marshalling, return-slot wiring), but resolves both the callee and
    /// the inline decision through `JitCodeRuntime` because the portal is
    /// self-recursive and has no compiled target in any descrs slot at
    /// emit time.  With the default `JitCodeRuntime` (decision
    /// `ResidualCall`, `portal_jitcode` `None`) it aborts the trace, so
    /// only a runtime that overrides both methods reaches the inline path.
    fn exec_recursive_call(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        runtime: &R,
        result_kind: Option<JitArgKind>,
    ) -> TraceAction {
        // Decode the payload off the caller frame, advancing its cursor
        // past the whole instruction.  As in BC_INLINE_CALL, the caller's
        // `pc` is set to `code_cursor` so a later `make_result_of_lastop`
        // (driven by the portal's typed return) keys `resulttypes[pc]` at
        // the post-operand offset the emitter recorded.
        let (jd_index, result_dst, greens_i, greens_r, greens_f, reds_i, reds_r, reds_f) = {
            let frame = self.frames.current_mut();
            let jd_reg = frame.next_reg() as usize;
            let read_list = |frame: &mut crate::pyjitpl::frame::MIFrame| {
                let n = frame.next_u8() as usize;
                (0..n)
                    .map(|_| frame.next_reg() as usize)
                    .collect::<Vec<_>>()
            };
            let greens_i = read_list(frame);
            let greens_r = read_list(frame);
            let greens_f = read_list(frame);
            let reds_i = read_list(frame);
            let reds_r = read_list(frame);
            let reds_f = read_list(frame);
            let result_dst = match result_kind {
                Some(_) => {
                    let dest = frame.next_reg() as usize;
                    if dest == crate::jitcode::NO_RETURN_REG as usize {
                        None
                    } else {
                        Some(dest)
                    }
                }
                None => None,
            };
            // Caller-side result-slot bookkeeping (BC_INLINE_CALL:3298-3300).
            frame._result_argcode = match (result_kind, result_dst) {
                (Some(JitArgKind::Int), Some(_)) => b'i',
                (Some(JitArgKind::Ref), Some(_)) => b'r',
                (Some(JitArgKind::Float), Some(_)) => b'f',
                _ => b'v',
            };
            frame.result_arg_index = result_dst;
            frame.pc = frame.code_cursor;
            (
                jd_reg, result_dst, greens_i, greens_r, greens_f, reds_i, reds_r, reds_f,
            )
        };
        let jd_index = self.read_int_reg(ctx, jd_index).1 as usize;

        // `pyjitpl.py` `boxes3` concatenates the three kind lists (I then R
        // then F).  `green_pc` is the first int green — the portal entry pc.
        let mut green_values = Vec::with_capacity(greens_i.len() + greens_r.len() + greens_f.len());
        for &src in &greens_i {
            green_values.push(self.read_int_reg(ctx, src).1);
        }
        for &src in &greens_r {
            green_values.push(self.read_ref_reg(ctx, src).1);
        }
        for &src in &greens_f {
            green_values.push(self.read_float_reg(ctx, src).1);
        }
        let green_pc = greens_i
            .first()
            .map(|&src| self.read_int_reg(ctx, src).1 as usize)
            .unwrap_or(0);

        let recursive_depth = ctx.recursive_depth((jd_index, green_pc));
        let inline_depth = ctx.inline_depth();
        let decision = runtime.recursive_inline_decision(
            jd_index,
            &green_values,
            inline_depth,
            recursive_depth,
        );
        if decision != crate::pyjitpl::InlineDecision::Inline {
            // pyjitpl.py `_opimpl_recursive_call` →
            // `do_recursive_call(assembler_call=True)`: instead of inlining
            // the portal frame, force the caller vable to heap, record a
            // CALL_ASSEMBLER into the callee's own compiled loop (resolved
            // by green key), and reload on return.  Mirrors the
            // `BC_CALL_ASSEMBLER_INT` arm verbatim except for token
            // resolution (green key, not the jitcode fn_ptr_idx slot).
            //
            // `CallAssembler` and `ResidualCall` both arrive here, because
            // upstream draws no line between them at this point: with
            // `warmrunnerstate.inlining` true (always, here —
            // `WarmEnterState::inlining` in `warmstate.rs` defaults to `true`)
            // every path that does not `perform_call` sets
            // `assembler_call = True` and falls into `do_recursive_call`.  The
            // callee-not-compiled case is not a residual call there; the token
            // is built on demand further down, by `direct_assembler_call` →
            // `get_assembler_token` → `compile_tmp_callback`
            // (warmstate.py).  The two variants differ only in whether a token
            // was already PROVEN when the decision was taken, and
            // `decide_recursive_inline` cannot prove one: it is pure in five
            // scalars with no synthesiser in reach.  The synthesiser sits
            // behind the seam this arm consults —
            // `Runtime::recursive_call_assembler_target`, which the production
            // resolver backs with `get_assembler_token` / `compile_tmp_callback`
            // — so asking it is what turns "no token proven yet" into
            // upstream's on-demand token rather than a lost trace.
            //
            // A seam that still comes back empty aborts inside
            // `exec_recursive_call_assembler`, which is the retry-until-the-
            // callee-compiles behaviour this arm used to take unconditionally,
            // now reached only when no token can be built at all.
            //
            // pyjitpl.py's true residual path
            // (`assembler_call = False`, `do_residual_call`) is reachable only
            // when `inlining` is false, which is never the case here, so it is
            // intentionally unmodelled.
            return self.exec_recursive_call_assembler(
                ctx,
                sym,
                runtime,
                result_kind,
                jd_index,
                result_dst,
                &green_values,
            );
        }
        // pc-aligned portal runtimes (dispatch.rs test fixtures) wire
        // `portal_jitcode`; enter their portal at `green_pc` as before.
        if let Some(portal) = runtime.portal_jitcode(jd_index) {
            // pyjitpl.py `_opimpl_recursive_call` `boxes3` concatenates I then
            // R then F; `newframe(jitcode, greenkey)` → `f.setup(jitcode,
            // greenkey)` uses that one `greenkey` for unique_id and
            // `portal_trace_positions`.
            let mut types = Vec::with_capacity(greens_i.len() + greens_r.len() + greens_f.len());
            types.extend(std::iter::repeat(GreenType::Int).take(greens_i.len()));
            types.extend(std::iter::repeat(GreenType::Ref).take(greens_r.len()));
            types.extend(std::iter::repeat(GreenType::Float).take(greens_f.len()));
            let typed = GreenKey::with_types(green_values.clone(), types);
            let greenkey: crate::pyjitpl::PortalGreenKey = (typed.get_uhash(), typed);
            let mut portal_frame =
                self.frames
                    .take_frame(portal, green_pc, Some(greenkey.clone()), Some(ctx));
            portal_frame.code_cursor = green_pc;
            ctx.push_inline_frame((jd_index, green_pc), u32::MAX);
            // pyjitpl.py `MetaInterp.newframe`: `portal_call_depth += 1`, then
            // `unique_id = jitcode.jitdriver_sd.warmstate.get_unique_id(greenkey)`
            // and `enter_portal_frame(jd_no, unique_id)`.
            ctx.adjust_portal_call_depth(1);
            let unique_id = ctx.unique_id_for_greenkey(jd_index, &greenkey);
            let jd_box = ctx.const_int(jd_index as i64);
            let uid_box = ctx.const_int(unique_id as i64);
            ctx.record_op(OpCode::EnterPortalFrame, &[jd_box, uid_box]);
            // pyjitpl.py `newframe`: ENTER_PORTAL_FRAME and the
            // `portal_trace_positions` append sit on adjacent lines.
            // The machine forwards the log half through
            // `portal_trace_push_fn` into MetaInterp.
            if runtime.is_main_portal(jd_index) {
                ctx.push_portal_trace_event(jd_index, Some(greenkey), ctx.get_trace_position());
                portal_frame.portal_trace_logged = true;
            }
            portal_frame.inline_frame = true;
            // pyjitpl.py:2461-2492 pairing: this push recorded ENTER_PORTAL_FRAME,
            // so the frame's normal-return / exception-return pop records the
            // matching LEAVE_PORTAL_FRAME (popframe leave_portal_frame default
            // True). The merge-point cut path pops this frame itself and re-emits
            // LEAVE (leave_portal_frame=False), so it never flows through those
            // auto-LEAVE pops.
            portal_frame.portal_entered = true;
            portal_frame.portal_jd = jd_index;
            // Portal args are greens+reds per kind, the same concatenation
            // `bhimpl_recursive_call_*` passes to `cpu.bh_call_*`.
            for (dst, &src) in greens_i.iter().chain(reds_i.iter()).enumerate() {
                let (value, concrete) = self.read_int_reg(ctx, src);
                #[cfg(feature = "jit-audits")]
                majit_ir::reg_write_audit::note_int_write(
                    portal_frame.int_regs.as_ptr() as usize,
                    dst,
                    Some(value),
                );
                portal_frame.int_regs[dst] = Some(value);
                debug_assert_box_holds(ctx, value, Value::Int(concrete));
            }
            for (dst, &src) in greens_r.iter().chain(reds_r.iter()).enumerate() {
                let (value, concrete) = self.read_ref_reg(ctx, src);
                portal_frame.ref_regs[dst] = Some(value);
                debug_assert_box_holds(ctx, value, Value::Ref(majit_ir::GcRef(concrete as usize)));
            }
            for (dst, &src) in greens_f.iter().chain(reds_f.iter()).enumerate() {
                let (value, concrete) = self.read_float_reg(ctx, src);
                portal_frame.float_regs[dst] = Some(value);
                debug_assert_box_holds(ctx, value, Value::Float(f64::from_bits(concrete as u64)));
            }
            match result_kind {
                Some(JitArgKind::Int) => portal_frame.return_i = result_dst,
                Some(JitArgKind::Ref) => portal_frame.return_r = result_dst,
                Some(JitArgKind::Float) => portal_frame.return_f = result_dst,
                None => {}
            }
            self.frames.push(portal_frame);
            return TraceAction::Continue;
        }

        // State-field production runtime leaves `portal_jitcode` None.  The
        // former inline re-entry path recorded a fresh per-driver callee
        // vable identity leaked for the process lifetime — no RPython/PyPy
        // analog (PyPy reconstructs the callee vable from resumedata per
        // resume) — so it is removed.  This shape aborts until a
        // trace-scoped rebuild lands.
        //
        // Sending it to `exec_recursive_call_assembler` instead — which is
        // what `_opimpl_recursive_call` does for every path that does not
        // `perform_call`, and which reads as the obvious repair — does NOT
        // work today, measured: the seam resolves its token through
        // `get_assembler_token` → `compile_tmp_callback`, and that requires
        // `jitdriver_sd.portal_runner_adr`.  Registering a driver without one
        // violates `register_jitdriver_sd`'s documented invariant, and the
        // `#[jit_interp]` macro install path has no hook that supplies it, so
        // `majit/examples/tl` — the only crate in the corpus that emits
        // `BC_RECURSIVE_CALL_*` — registers a driver with `portal_runner_adr`
        // still 0.  Routing this arm there panics that `debug_assert!`; the
        // `catch_unwind` in `run_to_end` swallows it into an abort whose
        // rollback does not undo what the seam already did to the interpreter
        // state, and `tl`'s `jit_recursive_call_matches_interp` then reads a
        // wrong stack.  In release the same shape is worse than a panic: the
        // assertion compiles out and `funcbox` bakes address 0.
        //
        // The prerequisite is therefore a portal runner on the driver
        // (`warmspot.py` `jd.portal_runner_adr = adr_of(ll_portal_runner)`;
        // `eval.rs` wires one for jd0, which is why production has no such
        // hole), not a decision-routing change here.
        refuse_unexecuted_recursive_call(ctx)
    }

    /// pyjitpl.py `do_recursive_call(assembler_call=True)` for a
    /// `BC_RECURSIVE_CALL_*` opcode whose inline decision was
    /// `CallAssembler`.  Runs the 8-step `do_residual_call` /
    /// CALL_ASSEMBLER protocol (force caller vable → concrete call →
    /// reload → record `CallAssembler*`), reusing the same vable helpers the
    /// `BC_CALL_ASSEMBLER_INT` arm in this file uses, but resolving
    /// the callee loop token by GREEN KEY via the `JitCodeRuntime` seam
    /// (the portal is self-recursive and has no `fn_ptr_idx` slot) and
    /// driving the concrete leg through `execute_recursive_assembler_int`
    /// (`execute_token_raw`, JITFRAME-ABI) rather than `call_int_function`
    /// (positional C-ABI) — a compiled state-field loop has no C-ABI entry.
    /// Because the callee runs as its own compiled loop with its caller's
    /// state forced to the heap, there is no shared-shadow aliasing and no
    /// caller-frame resume coupling — the callee's guards resume in its own
    /// blackhole.  Wires all four result kinds (`Int` / `Ref` / `Float` /
    /// `Void`): each drives its kind-specific concrete executor
    /// (`execute_recursive_assembler_{int,ref,float,void}`), records the
    /// matching `CallAssembler{I,R,F,N}` descr via
    /// `call_assembler_{int,ref,float,void}_arc_typed`, and writes the result
    /// into the correct register bank (`Void` has no result).
    #[allow(clippy::too_many_arguments)]
    fn exec_recursive_call_assembler(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        runtime: &R,
        result_kind: Option<JitArgKind>,
        jd_index: usize,
        result_dst: Option<usize>,
        green_values: &[i64],
    ) -> TraceAction {
        // Validate the (result_kind, result_dst) pairing: the three typed
        // kinds carry a destination register, `Void` carries none.  Any
        // other shape is a malformed opcode — abort.
        match (result_kind, result_dst) {
            (Some(JitArgKind::Int), Some(_))
            | (Some(JitArgKind::Ref), Some(_))
            | (Some(JitArgKind::Float), Some(_))
            | (None, None) => {}
            _ => return refuse_unexecuted_recursive_call(ctx),
        }

        // The greens carry the portal green key (pyjitpl.py:3593-3599
        // `get_assembler_token(greenargs)`), already read from the correct
        // register bank per `JitArgKind` by the caller in green declaration
        // order.
        // The seam returns the callee loop token (for both the recorded
        // descr's identity and the concrete entry) plus the resolved green
        // key (compile.py `rd_loop_token`).  The concrete int leg keys
        // off the token; the green key is the loop identity S3's
        // resume-layout enrichment will need.
        let (token_arc, _green_key) =
            match runtime.recursive_call_assembler_target(jd_index, green_values) {
                Some(target) => target,
                None => return refuse_unexecuted_recursive_call(ctx),
            };

        // Build the callee's red args.  A recursive portal call runs the
        // callee as its own compiled loop with a FRESH frame
        // (`direct_assembler_call` in `pyjitpl.rs` passes red args positionally;
        // tl.py `Stack(len(code))` is a fresh stack), so the reds are the
        // freshly-allocated callee state — not the caller's live registers.
        // Greens are baked into the callee loop's green key, not passed as
        // call args.  `recursive_fresh_entry_reds` yields the fresh reds in
        // `extract_live` order (scalars zeroed, then the `&state` identity
        // Ref) together with an owner box keeping
        // that state alive for the concrete `execute_recursive_assembler_int`
        // run.
        let (fresh_values, fresh_owner) = match sym.recursive_fresh_entry_reds() {
            Some(pair) => pair,
            None => return refuse_unexecuted_recursive_call(ctx),
        };
        let fresh_capacities = match sym.recursive_fresh_entry_vable_capacities() {
            Some(capacities) => capacities,
            None => return refuse_unexecuted_recursive_call(ctx),
        };
        let (alloc_fp, free_fp) = match sym.recursive_fresh_alloc_free_targets() {
            Some(targets) => targets,
            None => return refuse_unexecuted_recursive_call(ctx),
        };
        // The trace-time fresh state stands in for the residual allocator's
        // result (byte-identical by construction — both build a fresh state,
        // scalars zeroed, the virt array at the captured capacity).  Held
        // alive across the concrete leg; dropped at function exit (the
        // compiled loop's recorded `CallN` free owns runtime deallocation).
        let _fresh_owner = fresh_owner;
        // The compiled caller loop cannot `New` a host state through the IR,
        // so each virt-array `&state` red is recorded as a residual `CallR`
        // to the macro-generated host allocator (the host analog of
        // `gen_malloc_frame`, rewrite.py), paired with a residual `CallN`
        // free after the call.  The allocator EI cannot raise (`Box::new`
        // aborts on OOM, never raising a pyre exception), is non-elidable and
        // non-loop-invariant (each call yields a distinct frame; eliding or
        // hoisting would alias frames), and `can_collect = false` (a host
        // `Box` allocation never triggers pyre's GC).
        let fresh_call_ei = majit_ir::EffectInfo {
            can_collect: false,
            ..majit_ir::EffectInfo::new(
                majit_ir::descr::ExtraEffect::CannotRaise,
                majit_ir::descr::OopSpecIndex::None,
            )
        };
        let mut args = Vec::with_capacity(fresh_values.len());
        let mut red_values = Vec::with_capacity(fresh_values.len());
        let mut arg_types = Vec::with_capacity(fresh_values.len());
        let mut alloc_results: Vec<OpRef> = Vec::new();
        let mut capacities = fresh_capacities.into_iter();
        let mut idx = 0;
        while idx < fresh_values.len() {
            match fresh_values[idx] {
                majit_ir::Value::Int(n) => {
                    args.push(OpRef::const_int(n));
                    red_values.push(majit_ir::Value::Int(n));
                    arg_types.push(majit_ir::Type::Int);
                    idx += 1;
                }
                majit_ir::Value::Ref(_) => {
                    // Allocation capacity is frame-construction metadata, not
                    // an extra portal red (pyjitpl.py `do_recursive_call`).
                    let cap = match capacities.next() {
                        Some(cap) => cap,
                        None => return refuse_unexecuted_recursive_call(ctx),
                    };
                    let cap_arg = OpRef::const_int(cap);
                    let alloc_result = ctx.call_ref_typed_with_effect(
                        alloc_fp,
                        &[cap_arg],
                        &[majit_ir::Type::Int],
                        fresh_call_ei.clone(),
                    );
                    alloc_results.push(alloc_result);
                    args.push(alloc_result);
                    red_values.push(fresh_values[idx]);
                    arg_types.push(majit_ir::Type::Ref);
                    idx += 1;
                }
                _ => return refuse_unexecuted_recursive_call(ctx),
            }
        }
        if capacities.next().is_some() {
            return refuse_unexecuted_recursive_call(ctx);
        }

        // 8-step `do_residual_call(assembler_call=True)` protocol, mirroring
        // the `BC_CALL_ASSEMBLER_INT` arm in this file, except the
        // concrete leg runs the callee's compiled loop through the
        // JITFRAME-ABI `execute_recursive_assembler_int` seam (which wraps
        // `execute_token_raw`) rather than a positional C-ABI call — a
        // compiled state-field loop has no C-ABI entry.
        self.clear_exception();
        // pyjitpl.py:2017 — vrefs walk + vinfo stamp before the call.
        ctx.vrefs_before_residual_call();
        let active_vable = self.prepare_standard_virtualizable_before_residual_call(ctx);
        // Concrete leg + `CallAssembler{I,R,F,N}` record + result writeback,
        // one arm per result kind.  The concrete executor decodes the FINISH
        // output in the kind's raw packing (int as-is, ref as its `GcRef`
        // bits, float as `f64::to_bits()`); the recorded descr is emitted by
        // the matching `call_assembler_*_arc_typed`, and the traced result op
        // is written into the result kind's register bank.  `Void` runs the
        // callee for its side effects with no result to decode or write.
        //
        // `vrefs_after_residual_call` fires between the concrete run and the
        // CALL_ASSEMBLER record in every arm (pyjitpl.py).
        match result_kind {
            Some(JitArgKind::Int) => {
                let concrete =
                    match runtime.execute_recursive_assembler_int(&token_arc, &red_values) {
                        Some(value) => value,
                        None => return TraceAction::Abort,
                    };
                ctx.vrefs_after_residual_call();
                let traced = ctx.call_assembler_int_arc_typed_with_value(
                    token_arc, &args, &arg_types, concrete,
                );
                self.set_int_reg(
                    ctx,
                    result_dst.expect("int result kind requires a destination"),
                    Some(traced),
                    Some(concrete),
                );
            }
            Some(JitArgKind::Ref) => {
                let concrete =
                    match runtime.execute_recursive_assembler_ref(&token_arc, &red_values) {
                        Some(value) => value,
                        None => return TraceAction::Abort,
                    };
                ctx.vrefs_after_residual_call();
                let traced = ctx.call_assembler_ref_arc_typed_with_value(
                    token_arc, &args, &arg_types, concrete,
                );
                self.set_ref_reg(
                    ctx,
                    result_dst.expect("ref result kind requires a destination"),
                    Some(traced),
                    Some(concrete),
                );
            }
            Some(JitArgKind::Float) => {
                let concrete =
                    match runtime.execute_recursive_assembler_float(&token_arc, &red_values) {
                        Some(value) => value,
                        None => return TraceAction::Abort,
                    };
                ctx.vrefs_after_residual_call();
                let traced = ctx.call_assembler_float_arc_typed_with_value(
                    token_arc, &args, &arg_types, concrete,
                );
                self.set_float_reg(
                    ctx,
                    result_dst.expect("float result kind requires a destination"),
                    Some(traced),
                    Some(concrete),
                );
            }
            None => {
                if runtime
                    .execute_recursive_assembler_void(&token_arc, &red_values)
                    .is_none()
                {
                    return TraceAction::Abort;
                }
                ctx.vrefs_after_residual_call();
                ctx.call_assembler_void_arc_typed(token_arc, &args, &arg_types);
            }
        }
        // `pyjitpl.py do_residual_call` step 5: "invalidate the heapcache
        // based on the CALL_MAY_FORCE operation executed above in step 2",
        // `heapcache.invalidate_caches_varargs(opnum1, descr, allboxes)`.
        // `opnum1` is `CALL_MAY_FORCE_*` for the result kind, `descr` is
        // `targetjitdriver_sd.portal_calldescr` and `allboxes` is
        // `[funcbox] + greenboxes + redboxes` (`_opimpl_recursive_call`, with
        // `funcbox = ConstInt(adr2int(targetjitdriver_sd.portal_runner_ptr))`).
        let opnum1 = majit_ir::OpCode::call_may_force_for_type(match result_kind {
            Some(JitArgKind::Int) => majit_ir::Type::Int,
            Some(JitArgKind::Ref) => majit_ir::Type::Ref,
            Some(JitArgKind::Float) => majit_ir::Type::Float,
            None => majit_ir::Type::Void,
        });
        let (portal_runner_adr, portal_calldescr) = {
            let jd = ctx.metainterp_sd().jitdrivers_sd.get(jd_index);
            (
                jd.map_or(0, |jd| jd.portal_runner_adr),
                jd.and_then(|jd| jd.portal_calldescr.clone()),
            )
        };
        let effectinfo = portal_calldescr
            .as_ref()
            .and_then(|descr| descr.as_call_descr())
            .map(|calldescr| calldescr.get_extra_info());
        let mut allboxes = Vec::with_capacity(1 + green_values.len() + args.len());
        allboxes.push(OpRef::const_int(portal_runner_adr));
        // The greens are constants whichever kind they carry; the heapcache
        // only asks a box whether it is unescaped, which no constant is.
        allboxes.extend(green_values.iter().map(|&green| OpRef::const_int(green)));
        allboxes.extend_from_slice(&args);
        ctx.heapcache_invalidate_caches_varargs(opnum1, effectinfo, &allboxes);
        // Free each fresh allocation after the call: the compiled loop's
        // residual `CallN`.  Recorded after CALL_ASSEMBLER so the callee has
        // the state for the duration of its run; the trace-time owner box is
        // dropped at function exit.
        for alloc_result in &alloc_results {
            ctx.call_void_typed_with_effect(
                free_fp,
                &[*alloc_result],
                &[majit_ir::Type::Ref],
                fresh_call_ei.clone(),
            );
        }
        let vable_opref = active_vable.as_ref().map(|a| a.vable_opref);
        let action = self.finalize_standard_virtualizable_may_force(ctx, sym, active_vable);
        if !matches!(action, TraceAction::Continue) {
            return action;
        }
        // pyjitpl.py:2080-2081 KEEPALIVE on the vable box.
        if let Some(vbox) = vable_opref {
            ctx.record_op(majit_ir::OpCode::Keepalive, &[vbox]);
        }
        self.finish_call_assembler_exception_path(ctx, sym)
    }

    /// Report where a bytecode-level abort was DECIDED, which the merge point
    /// structurally cannot.
    ///
    /// `[jit] trace action at pc=N -> Abort` is emitted by the generated merge
    /// point (`majit-macros/src/jit_interp/codegen_trace.rs`), so `N` is the
    /// **portal pc** — where the walk started, not where it stopped. Read
    /// literally it names the wrong dispatch arm: braininterp's abort reports
    /// `pc=7` (`[`) and fires at `pc=14` (`]`). tla's and tinyframe's headers
    /// already warned that this pc is the trace START, and the warning did not
    /// prevent the misreading — a message that must be read against a comment
    /// elsewhere will eventually be read on its own.
    ///
    /// `depth`/`body` are the other half, and they are the part the opcode
    /// cannot supply: **`BC_ABORT` has two emitter families** in `majit-macros`
    /// — the per-arm degraded stubs (`jitcode_lower/dispatch.rs`'s
    /// `__sub_builder.abort()` sites) and a bounds-check bailout in the
    /// dispatch body (`__builder.abort()`). Both emit this one opcode, so
    /// seeing it identifies neither the arm nor the family. They are told apart
    /// by *where* it ran: a degraded arm aborts inside its own sub-JitCode, an
    /// inline frame whose whole body is the single abort byte, so
    /// `depth>1 body=1` is the stub and the dispatch body is neither.
    ///
    /// `JitCode.name` is the direct answer and the macro now supplies it: the
    /// arm's sub-JitCode is named `<Interp>::<arm pattern>` and the dispatch
    /// body's is the machine function's own name, so the line says which arm
    /// aborted instead of leaving it to be inferred. The frame shape stays in
    /// the message because it is the independent check — a name is a label the
    /// emitter chose, `depth`/`body` is what actually ran — and because a host
    /// still on an older builder emits `""` here.
    fn log_bytecode_abort(&mut self, insn: &str) {
        if !crate::majit_log_enabled() {
            return;
        }
        let depth = self.frames.len();
        let frame = self.frames.current_mut();
        eprintln!(
            "[jit] {insn} decided in {:?} at pos={} depth={depth} body={} \
             (depth>1 body=1 = a degraded arm stub; the merge point's \
             `trace action at pc=` reports the PORTAL pc, not this one)",
            frame.jitcode.name(),
            frame.last_opcode_position,
            frame.jitcode.code.len(),
        );
    }

    /// `pyjitpl.py` `MIFrame.run_one_step`: execute the frame forward,
    /// leaving the loop only when the current frame changes (`ChangeFrame`,
    /// a call or a return) or an instruction ends the trace. `live` and
    /// `goto` advance the position in the loop itself.
    ///
    /// After each executed instruction the loop returns when the frame
    /// changed or `TraceCtx::is_too_long` is set, so `run_to_end` can answer
    /// the overflow the way `MetaInterp.blackhole_if_trace_too_long` does.
    /// `optrace_step` only prints when opcode tracing is on.
    pub fn run_one_step(&mut self, ctx: &mut TraceCtx, sym: &mut S, runtime: &R) -> TraceAction {
        self.install_replace_frames(ctx);
        // SAFETY: the guard is a local of this call and `ctx` is borrowed for
        // longer, so it is dropped while the `TraceCtx` it names is alive.
        let _clear = unsafe { ClearReplaceFrames::new(ctx) };
        let depth = self.frames.len();
        loop {
            let Some(frame) = self.frames.frames.last_mut() else {
                return TraceAction::Continue;
            };
            let pc = frame.code_cursor;
            match frame.bytecode().get(pc).copied() {
                Some(jitcode::insns::BC_LIVE) => {
                    frame.code_cursor = pc + 3;
                    continue;
                }
                Some(jitcode::insns::BC_JUMP) => {
                    frame.code_cursor = frame
                        .peek_u16_at(pc + 1)
                        .expect("BC_JUMP target operand is truncated")
                        as usize;
                    self.optrace_step();
                    continue;
                }
                _ => {}
            }
            self.optrace_step();
            let action = self.execute_one_instruction(ctx, sym, runtime);
            if !matches!(action, TraceAction::Continue)
                || self.frames.len() != depth
                || ctx.is_too_long()
            {
                return action;
            }
        }
    }

    /// Print the current opcode when `optrace_enabled`. Never aborts the walk.
    fn optrace_step(&mut self) {
        if crate::optrace_enabled() {
            let fr = self.frames.current_mut();
            let cur = fr.code_cursor;
            let anchor_pc = fr.pc;
            let opcode = fr.jitcode.code.get(cur).copied().unwrap_or(0xff);
            let name = fr.jitcode.name.clone();
            eprintln!(
                "[optrace] depth={} cursor={} pc={} opcode={} jitcode={}",
                self.frames.len(),
                cur,
                anchor_pc,
                opcode,
                name
            );
        }
    }

    /// One instruction of [`Self::run_one_step`]'s loop: pop a finished frame,
    /// or decode and execute the instruction at the cursor.
    ///
    /// Opcode bodies live in `opimpl_*` methods and are reached through
    /// [`Self::OPCODE_IMPLEMENTATIONS`], the port of `pyjitpl.py`
    /// `opcode_implementations` (`setup_insns` / `_get_opimpl_method`).
    fn execute_one_instruction(
        &mut self,
        ctx: &mut TraceCtx,
        sym: &mut S,
        runtime: &R,
    ) -> TraceAction {
        if crate::take_walk_abort() || majit_backend::take_null_mem_access() {
            ctx.symbolic_residual_abort = true;
            if crate::is_bridge_walking() || ctx.is_bridge_trace {
                ctx.deterministic_bridge_abort = true;
            }
            return TraceAction::Abort;
        }
        if self.frames.is_empty() {
            return TraceAction::Continue;
        }

        let finished = {
            let frame = self.frames.current_mut();
            frame.finished()
        };
        if finished {
            if self.frames.len() == 1 {
                // The walk is about to return Continue with an empty
                // framestack. Re-read `last_mp_green_*` off this last
                // portal frame so a later header-revisit CloseLoop
                // publishes values written after the merge-point stamp
                // (`bhimpl_jit_merge_point`).
                self.snapshot_live_portal_greens(ctx);
            }
            let mut finished_frame = self.frames.pop().expect("finished frame stack was empty");
            if finished_frame.inline_frame {
                ctx.pop_inline_frame();
            }
            // pyjitpl.py finishframe -> popframe(leave_portal_frame=True):
            // a portal frame whose push recorded ENTER_PORTAL_FRAME returns
            // normally here, so record the matching LEAVE_PORTAL_FRAME. Ordinary
            // BC_INLINE_CALL frames (inline_frame=true, portal_entered=false)
            // recorded no ENTER and record no LEAVE.
            if finished_frame.portal_entered {
                // pyjitpl.py `popframe`: `portal_call_depth -= 1` then
                // `leave_portal_frame` when `jitcode.jitdriver_sd`.
                ctx.adjust_portal_call_depth(-1);
                let jd_box = ctx.const_int(finished_frame.portal_jd as i64);
                ctx.record_op(OpCode::LeavePortalFrame, &[jd_box]);
                if finished_frame.portal_trace_logged {
                    ctx.push_portal_trace_event(
                        finished_frame.portal_jd,
                        None,
                        ctx.get_trace_position(),
                    );
                }
            }
            // [FR] Restore the caller's sym scalar/fixed-array state that this
            // inline recursive-portal frame overwrote.
            if let Some(snapshot) = finished_frame.portal_scalar_state.take() {
                sym.restore_inline_scalar_state(snapshot);
            }
            if let Some(parent) = self.frames.frames.last_mut()
                && let Some((return_kind, callee_src)) =
                    finished_frame.jitcode.trailing_return_info()
            {
                match return_kind {
                    JitArgKind::Int => {
                        let caller_dst = finished_frame
                            .return_i
                            .expect("inline int return missing caller destination");
                        parent.int_regs[caller_dst] = finished_frame.int_regs[callee_src as usize];
                    }
                    JitArgKind::Ref => {
                        let caller_dst = finished_frame
                            .return_r
                            .expect("inline ref return missing caller destination");
                        parent.ref_regs[caller_dst] = finished_frame.ref_regs[callee_src as usize];
                    }
                    JitArgKind::Float => {
                        let caller_dst = finished_frame
                            .return_f
                            .expect("inline float return missing caller destination");
                        parent.float_regs[caller_dst] =
                            finished_frame.float_regs[callee_src as usize];
                    }
                }
            }
            self.frames.recycle_frame(finished_frame);
            return TraceAction::Continue;
        }

        let bytecode = {
            let frame = self.frames.current_mut();
            frame.last_opcode_position = frame.code_cursor;
            frame.next_u8()
        };
        // pyjitpl.py MIFrame.run_one_step:
        // staticdata.opcode_implementations[op](self, pc)
        Self::OPCODE_IMPLEMENTATIONS[bytecode as usize](self, ctx, sym, runtime, bytecode)
    }

    /// Trace the canonical `inline_call_{r,ir,irf}_*` family by entering a
    /// callee frame.  RPython `rpython/jit/metainterp/pyjitpl.py _opimpl_inline_call1`
    /// enters the frame, and `:144-160` copies each grouped argument
    /// positionally.
    fn exec_typed_inline_call(
        &mut self,
        ctx: &mut TraceCtx,
        _sym: &S,
        bytecode: u8,
    ) -> TraceAction {
        let (has_i_list, has_f_list, return_kind) = match bytecode {
            jitcode::insns::BC_INLINE_CALL_R_I => (false, false, Some(JitArgKind::Int)),
            jitcode::insns::BC_INLINE_CALL_R_R => (false, false, Some(JitArgKind::Ref)),
            jitcode::insns::BC_INLINE_CALL_R_V => (false, false, None),
            jitcode::insns::BC_INLINE_CALL_IR_I => (true, false, Some(JitArgKind::Int)),
            jitcode::insns::BC_INLINE_CALL_IR_R => (true, false, Some(JitArgKind::Ref)),
            jitcode::insns::BC_INLINE_CALL_IR_V => (true, false, None),
            jitcode::insns::BC_INLINE_CALL_IRF_F => (true, true, Some(JitArgKind::Float)),
            jitcode::insns::BC_INLINE_CALL_IRF_R => (true, true, Some(JitArgKind::Ref)),
            jitcode::insns::BC_INLINE_CALL_IRF_I => (true, true, Some(JitArgKind::Int)),
            jitcode::insns::BC_INLINE_CALL_IRF_V => (true, true, None),
            _ => unreachable!("typed inline-call dispatch arm passed bytecode {bytecode}"),
        };

        let sub_idx = self.frames.current_mut().next_u16() as usize;
        // `descr_at` resolves the callee from the per-jitcode `exec.descrs`
        // pool (runtime-built jitcodes) or the shared global build-time pool
        // (LLBC-extracted jitcodes, whose per-jitcode pool is empty).
        // `as_jitcode_owned`, so a recursive helper's back edge upgrades
        // the same way `BC_INLINE_CALL` does. `as_jitcode` is owning-edges
        // only and would abort a self-call.
        let sub_jitcode = self
            .frames
            .current_mut()
            .jitcode
            .descr_at(sub_idx)
            .and_then(crate::jitcode::RuntimeBhDescr::as_jitcode_owned);
        let Some(sub_jitcode) = sub_jitcode else {
            // The callee is in neither pool; abort the trace instead of
            // crashing the process. Consume the remaining operands so
            // `publish_walk_abort_handoff` (`top.pc = top.code_cursor`)
            // lands on the next instruction, not a count/register byte.
            if crate::majit_log_enabled() {
                eprintln!(
                    "[interpret] inline_call descrs[{sub_idx}] missing (pool={})",
                    crate::jitcode::global_build_descr_pool().is_some(),
                );
            }
            let caller = self.frames.current_mut();
            if has_i_list {
                let n = caller.next_u8() as usize;
                for _ in 0..n {
                    let _ = caller.next_reg();
                }
            }
            let n_r = caller.next_u8() as usize;
            for _ in 0..n_r {
                let _ = caller.next_reg();
            }
            if has_f_list {
                let n_f = caller.next_u8() as usize;
                for _ in 0..n_f {
                    let _ = caller.next_reg();
                }
            }
            if return_kind.is_some() {
                let _ = caller.next_reg();
            }
            return TraceAction::Abort;
        };
        assert!(
            !sub_jitcode.reads_identity_slots(),
            "inline_call callee {:?} emits load/store_state_field*; only the portal JitCode may",
            sub_jitcode.name()
        );
        let mut sub_frame = self.frames.take_frame(sub_jitcode, 0, None, Some(ctx));
        sub_frame.inline_frame = true;

        // pyjitpl.py newframe decoder + fill_registers: write each callee
        // slot as the caller bytecode names it. Do not collect the index
        // lists (9 usizes = 72 B).
        let result_dst = {
            let caller = self.frames.current_mut();
            if has_i_list {
                let n = caller.next_u8() as usize;
                caller.fill_registers(&mut sub_frame, n, b'I');
            }
            let n_r = caller.next_u8() as usize;
            caller.fill_registers(&mut sub_frame, n_r, b'R');
            if has_f_list {
                let n_f = caller.next_u8() as usize;
                caller.fill_registers(&mut sub_frame, n_f, b'F');
            }
            let result_dst = return_kind.map(|_| caller.next_reg() as usize);
            caller._result_argcode = match return_kind {
                Some(JitArgKind::Int) => b'i',
                Some(JitArgKind::Ref) => b'r',
                Some(JitArgKind::Float) => b'f',
                None => b'v',
            };
            caller.result_arg_index = result_dst;
            caller.pc = caller.code_cursor;
            ctx.push_inline_frame((sub_idx, caller.pc), u32::MAX);
            result_dst
        };

        sub_frame.return_i = None;
        sub_frame.return_r = None;
        sub_frame.return_f = None;
        match return_kind {
            Some(JitArgKind::Int) => {
                sub_frame.return_i =
                    Some(result_dst.expect("BC_INLINE_CALL_*_I must encode an int destination"));
            }
            Some(JitArgKind::Ref) => {
                sub_frame.return_r =
                    Some(result_dst.expect("BC_INLINE_CALL_*_R must encode a ref destination"));
            }
            Some(JitArgKind::Float) => {
                sub_frame.return_f =
                    Some(result_dst.expect("BC_INLINE_CALL_IRF_F must encode a float destination"));
            }
            None => {}
        }
        self.frames.push(sub_frame);
        TraceAction::Continue
    }

    fn set_int_reg(
        &mut self,
        ctx: &mut TraceCtx,
        reg: usize,
        opref: Option<OpRef>,
        value: Option<i64>,
    ) {
        let frame = self.frames.current_mut();
        #[cfg(feature = "jit-audits")]
        majit_ir::reg_write_audit::note_int_write(frame.int_regs.as_ptr() as usize, reg, opref);
        frame.int_regs[reg] = opref;
        if let (Some(op), Some(v)) = (opref, value) {
            debug_assert_box_holds(ctx, op, Value::Int(v));
        }
    }

    /// Write an identity-slot red on the current frame. Only the portal
    /// JitCode emits `load_state_field*` / `store_state_field*`
    /// (`pyjitpl.py` `MIFrame.setup_call` copies declared args only).
    fn set_int_identity_slot(
        &mut self,
        ctx: &mut TraceCtx,
        slot: usize,
        opref: Option<OpRef>,
        value: Option<i64>,
    ) {
        let frame = self.frames.current_mut();
        #[cfg(feature = "jit-audits")]
        majit_ir::reg_write_audit::note_int_write(frame.int_regs.as_ptr() as usize, slot, opref);
        frame.int_regs[slot] = opref;
        if let (Some(op), Some(v)) = (opref, value) {
            debug_assert_box_holds(ctx, op, Value::Int(v));
        }
    }

    fn set_ref_identity_slot(
        &mut self,
        ctx: &mut TraceCtx,
        slot: usize,
        opref: Option<OpRef>,
        value: Option<i64>,
    ) {
        let frame = self.frames.current_mut();
        frame.ref_regs[slot] = opref;
        if let (Some(op), Some(v)) = (opref, value) {
            debug_assert_box_holds(ctx, op, Value::Ref(majit_ir::GcRef(v as usize)));
        }
    }

    fn set_float_identity_slot(
        &mut self,
        ctx: &mut TraceCtx,
        slot: usize,
        opref: Option<OpRef>,
        value: Option<i64>,
    ) {
        let frame = self.frames.current_mut();
        frame.float_regs[slot] = opref;
        if let (Some(op), Some(v)) = (opref, value) {
            debug_assert_box_holds(ctx, op, Value::Float(f64::from_bits(v as u64)));
        }
    }

    fn read_int_identity_slot(&mut self, ctx: &TraceCtx, slot: usize) -> (OpRef, i64) {
        let frame = self.frames.current_mut();
        let opref = frame.int_regs[slot].expect("int identity slot uninitialized");
        (
            opref,
            ctx.box_bits(opref)
                .expect("int identity value uninitialized"),
        )
    }

    fn read_ref_identity_slot(&mut self, ctx: &TraceCtx, slot: usize) -> (OpRef, i64) {
        let frame = self.frames.current_mut();
        let opref = frame.ref_regs[slot].expect("ref identity slot uninitialized");
        (
            opref,
            ctx.box_bits(opref)
                .expect("ref identity value uninitialized"),
        )
    }

    fn read_float_identity_slot(&mut self, ctx: &TraceCtx, slot: usize) -> (OpRef, i64) {
        let frame = self.frames.current_mut();
        let opref = frame.float_regs[slot].expect("float identity slot uninitialized");
        (
            opref,
            ctx.box_bits(opref)
                .expect("float identity value uninitialized"),
        )
    }

    fn read_int_reg(&mut self, ctx: &TraceCtx, reg: usize) -> (OpRef, i64) {
        let frame = self.frames.current_mut();
        let opref = frame.int_regs[reg].expect("jitcode register was uninitialized");
        (
            opref,
            ctx.box_bits(opref)
                .expect("jitcode concrete register was uninitialized"),
        )
    }

    fn set_ref_reg(
        &mut self,
        ctx: &mut TraceCtx,
        reg: usize,
        opref: Option<OpRef>,
        value: Option<i64>,
    ) {
        let frame = self.frames.current_mut();
        frame.ref_regs[reg] = opref;
        if let (Some(op), Some(v)) = (opref, value) {
            debug_assert_box_holds(ctx, op, Value::Ref(majit_ir::GcRef(v as usize)));
        }
    }

    fn read_ref_reg(&mut self, ctx: &TraceCtx, reg: usize) -> (OpRef, i64) {
        let frame = self.frames.current_mut();
        let opref = frame.ref_regs[reg].expect("jitcode ref register was uninitialized");
        (
            opref,
            ctx.box_bits(opref)
                .expect("jitcode concrete ref register was uninitialized"),
        )
    }

    fn set_float_reg(
        &mut self,
        ctx: &mut TraceCtx,
        reg: usize,
        opref: Option<OpRef>,
        value: Option<i64>,
    ) {
        let frame = self.frames.current_mut();
        frame.float_regs[reg] = opref;
        if let (Some(op), Some(v)) = (opref, value) {
            debug_assert_box_holds(ctx, op, Value::Float(f64::from_bits(v as u64)));
        }
    }

    fn read_float_reg(&mut self, ctx: &TraceCtx, reg: usize) -> (OpRef, i64) {
        let frame = self.frames.current_mut();
        let opref = frame.float_regs[reg].expect("jitcode float register was uninitialized");
        (
            opref,
            ctx.box_bits(opref)
                .expect("jitcode concrete float register was uninitialized"),
        )
    }

    fn read_call_arg(&mut self, ctx: &TraceCtx, arg: JitCallArg) -> (OpRef, i64, majit_ir::Type) {
        match arg.kind {
            JitArgKind::Int => {
                let (opref, value) = self.read_int_reg(ctx, arg.reg as usize);
                (opref, value, majit_ir::Type::Int)
            }
            JitArgKind::Ref => {
                let (opref, value) = self.read_ref_reg(ctx, arg.reg as usize);
                (opref, value, majit_ir::Type::Ref)
            }
            JitArgKind::Float => {
                let (opref, value) = self.read_float_reg(ctx, arg.reg as usize);
                (opref, value, majit_ir::Type::Float)
            }
        }
    }

    #[expect(
        clippy::type_complexity,
        reason = "This is the literal nested tuple/list/dict/callable shape at an RPython parity boundary; a wrapper would change structural ownership, while a one-use alias would conceal the audited upstream shape"
    )]
    fn read_canonical_call_args(
        &mut self,
        ctx: &TraceCtx,
        arg_classes: &str,
        args_i: &[JitCallArg],
        args_r: &[JitCallArg],
        args_f: &[JitCallArg],
    ) -> (
        CallOpRefs,
        CallI64s,
        CallTypes,
        CallI64s,
        CallI64s,
        CallI64s,
    ) {
        // pyjitpl.py `_build_allboxes`: one walk over the calldescr's
        // argument classes, taking the next encoded register of that kind.
        let mut raw_i = CallI64s::with_capacity(args_i.len());
        let mut raw_r = CallI64s::with_capacity(args_r.len());
        let mut raw_f = CallI64s::with_capacity(args_f.len());
        let mut next_i = 0usize;
        let mut next_r = 0usize;
        let mut next_f = 0usize;
        let mut args = CallOpRefs::with_capacity(arg_classes.len());
        let mut concrete_args = CallI64s::with_capacity(arg_classes.len());
        let mut arg_types = CallTypes::with_capacity(arg_classes.len());
        for class in arg_classes.chars() {
            let (bank, next, raw, kind) = match class {
                'i' | 'S' => (args_i, &mut next_i, &mut raw_i, "int"),
                'r' => (args_r, &mut next_r, &mut raw_r, "ref"),
                'f' | 'L' => (args_f, &mut next_f, &mut raw_f, "float"),
                other => panic!(
                    "BC_RESIDUAL_CALL_*_V calldescr has unsupported \
                     arg class {other:?}"
                ),
            };
            let arg = *bank.get(*next).unwrap_or_else(|| {
                panic!(
                    "BC_RESIDUAL_CALL_*_V calldescr arg_classes \
                     expected {kind} arg #{}, only {} encoded",
                    *next,
                    bank.len()
                )
            });
            *next += 1;
            let (opref, concrete, arg_type) = self.read_call_arg(ctx, arg);
            raw.push(concrete);
            args.push(opref);
            concrete_args.push(concrete);
            arg_types.push(arg_type);
        }

        assert_eq!(
            next_i,
            args_i.len(),
            "BC_RESIDUAL_CALL_*_V encoded extra int args not present in calldescr"
        );
        assert_eq!(
            next_r,
            args_r.len(),
            "BC_RESIDUAL_CALL_*_V encoded extra ref args not present in calldescr"
        );
        assert_eq!(
            next_f,
            args_f.len(),
            "BC_RESIDUAL_CALL_*_V encoded extra float args not present in calldescr"
        );
        (args, concrete_args, arg_types, raw_i, raw_r, raw_f)
    }

    fn trace_binop_i(&mut self, ctx: &mut TraceCtx, opcode: OpCode) {
        // `[lhs][rhs][dst]` canonical argcode order matching the
        // `bhhandler_ii_i!` blackhole decoder.
        let (lhs_idx, rhs_idx, dst) = {
            let frame = self.frames.current_mut();
            let lhs_idx = frame.next_reg() as usize;
            let rhs_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (lhs_idx, rhs_idx, dst)
        };
        let lhs = self.read_int_reg(ctx, lhs_idx);
        let rhs = self.read_int_reg(ctx, rhs_idx);
        let (opref, value) = self.execute_binop_i(ctx, opcode, lhs, rhs);
        self.set_int_reg(ctx, dst, Some(opref), Some(value));
    }

    /// `pyjitpl.py MIFrame.execute(opnum, b1, b2)` over two int boxes.
    ///
    /// Returns the result box paired with the value the traced iteration
    /// produced, which is what an opimpl that chains several of these needs
    /// in order to test an intermediate for constancy.
    fn execute_binop_i(
        &mut self,
        ctx: &mut TraceCtx,
        opcode: OpCode,
        (lhs, lhs_value): (OpRef, i64),
        (rhs, rhs_value): (OpRef, i64),
    ) -> (OpRef, i64) {
        if lhs == rhs
            && let Some(fast) = fastpath_same_boxes(opcode)
        {
            return (ctx.const_int(fast), fast);
        }
        let value = eval_binop_i(opcode, lhs_value, rhs_value);
        // The returned `value` stays `eval_binop_i`'s, not the funnel's: on
        // the fold path the two agree, and where the constant evaluator
        // declines — an out-of-range shift, a zero divisor — the funnel
        // records instead of folding and stamps the op with exactly this value.
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[lhs, rhs],
            Some(majit_ir::Value::Int(value)),
            self.last_exception_value,
        );
        (opref, value)
    }

    /// `pyjitpl.py opimpl_int_between` — `a <= b < c`, expanded here into
    /// `uint_lt(b - a, c - a)`, or into `int_eq(b, a)` when the span is one.
    ///
    /// The three-argument form is a jitcode op with no resop behind it: the
    /// tracer never records one, which is why no backend has to lower it.
    /// `blackhole.py bhimpl_int_between` evaluates the jitcode op directly,
    /// so the op itself stays.
    fn trace_int_between(&mut self, ctx: &mut TraceCtx) {
        // `[a][b][c][dst]` matching the `bhhandler_iii_i!` decoder.
        let (a_idx, b_idx, c_idx, dst) = {
            let frame = self.frames.current_mut();
            let a_idx = frame.next_reg() as usize;
            let b_idx = frame.next_reg() as usize;
            let c_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (a_idx, b_idx, c_idx, dst)
        };
        let a = self.read_int_reg(ctx, a_idx);
        let b = self.read_int_reg(ctx, b_idx);
        let c = self.read_int_reg(ctx, c_idx);
        let span = self.execute_binop_i(ctx, OpCode::IntSub, c, a);
        let (opref, value) = if span.0.is_constant() && span.1 == 1 {
            self.execute_binop_i(ctx, OpCode::IntEq, b, a)
        } else {
            let offset = self.execute_binop_i(ctx, OpCode::IntSub, b, a);
            self.execute_binop_i(ctx, OpCode::UintLt, offset, span)
        };
        self.set_int_reg(ctx, dst, Some(opref), Some(value));
    }

    /// `pyjitpl.py opimpl_int_{add,sub,mul}_ovf` — the overflow-checked
    /// arithmetic op fused with its branch (`blackhole.py:478-497`
    /// `int_*_jump_if_ovf`).  Records the `IntAddOvf`/`IntSubOvf`/`IntMulOvf`
    /// resop, then a `GuardNoOverflow` (traced iteration did not overflow) or
    /// a `GuardOverflow` + branch to the overflow label (it did).  The guard's
    /// resume position is this op, so on failure the blackhole re-executes
    /// `int_*_jump_if_ovf` and performs the overflow branch itself.
    fn trace_int_binop_jump_if_ovf(&mut self, ctx: &mut TraceCtx, sym: &mut S, opcode: OpCode) {
        // Canonical `Lii>i` encoding: [target:u16][lhs:u8][rhs:u8][dst:u8].
        let (opcode_pc, target, lhs_idx, rhs_idx, dst) = {
            let frame = self.frames.current_mut();
            let opcode_pc = frame.code_cursor - 1;
            let target = frame.next_u16() as usize;
            let lhs_idx = frame.next_u8() as usize;
            let rhs_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (opcode_pc, target, lhs_idx, rhs_idx, dst)
        };
        let (lhs, lhs_value) = self.read_int_reg(ctx, lhs_idx);
        let (rhs, rhs_value) = self.read_int_reg(ctx, rhs_idx);
        let (wrapped, overflowed) = match opcode {
            OpCode::IntAddOvf => lhs_value.overflowing_add(rhs_value),
            OpCode::IntSubOvf => lhs_value.overflowing_sub(rhs_value),
            OpCode::IntMulOvf => lhs_value.overflowing_mul(rhs_value),
            _ => unreachable!("trace_int_binop_jump_if_ovf: {opcode:?}"),
        };
        // `elif self.metainterp.ovf_flag: self.pc = lbl; return None # but
        // don't emit GUARD_OVERFLOW`. Upstream folds the constant pair either
        // way — `do_int_add_ovf` answers 0 and raises the flag when the
        // arithmetic leaves range — and takes the branch with neither the
        // operation nor its guard recorded. `execute_binary_int_const` spells
        // these with `checked_*` and declines instead, because the optimizer
        // shares it and there the operation and its guard are what carry the
        // overflow, so the overflowing-constant case is decided here. The
        // funnel's own fold gate is the condition mirrored.
        if overflowed && lhs.is_constant() && rhs.is_constant() && self.last_exception_value == 0 {
            // `execute_and_record` counts the operation before it decides to
            // fold, and this returns in its place.
            ctx.profiler().count_ops(opcode, crate::counters::OPS);
            self.frames.current_mut().code_cursor = target;
            return;
        }
        // `int_*_ovf` produces the wrapping result and sets the overflow flag;
        // the box-less guard below checks that flag.  An all-constant pair in
        // range folds and needs neither.
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[lhs, rhs],
            Some(majit_ir::Value::Int(wrapped)),
            self.last_exception_value,
        );
        if !opref.is_constant() {
            let guard = if overflowed {
                OpCode::GuardOverflow
            } else {
                OpCode::GuardNoOverflow
            };
            // The guard is box-less, so `record_state_guard`'s Const gate —
            // which reads `args[0]` — cannot see that the operation folded.
            self.record_state_guard(ctx, sym, guard, &[], opcode_pc, false);
        }
        if overflowed {
            // Overflow branch taken: the result register is not written; follow
            // the label (matches `bhimpl_int_*_jump_if_ovf` returning `None`).
            self.frames.current_mut().code_cursor = target;
        } else {
            self.set_int_reg(ctx, dst, Some(opref), Some(wrapped));
        }
    }

    fn trace_unary_i(&mut self, ctx: &mut TraceCtx, opcode: OpCode) {
        // RPython `assembler.py:165-174` argcode order: `[src][dst]`
        // for `int_neg/i>i` / `int_invert/i>i` (`bhhandler_i_i!`
        // canonical decoder reads `code[position]=src`,
        // `code[position+1]=dst`).
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (src_idx, dst)
        };
        let (src, src_value) = self.read_int_reg(ctx, src_idx);
        let value = eval_unary_i(opcode, src_value);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[src],
            Some(majit_ir::Value::Int(value)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(value));
    }

    /// Ref binop tracer helper returning an int result.
    /// `[lhs][rhs][dst]` canonical argcode order, matching the
    /// `bhhandler_rr_i!` blackhole decoder.
    fn trace_binop_r_to_i(&mut self, ctx: &mut TraceCtx, opcode: OpCode) {
        let (lhs_idx, rhs_idx, dst) = {
            let frame = self.frames.current_mut();
            let lhs_idx = frame.next_reg() as usize;
            let rhs_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (lhs_idx, rhs_idx, dst)
        };
        let (lhs, lhs_value) = self.read_ref_reg(ctx, lhs_idx);
        let (rhs, rhs_value) = self.read_ref_reg(ctx, rhs_idx);
        if lhs == rhs
            && let Some(fast) = fastpath_same_boxes(opcode)
        {
            let dest_box = ctx.const_int(fast);
            self.set_int_reg(ctx, dst, Some(dest_box), Some(fast));
            return;
        }
        let value = match opcode {
            OpCode::PtrEq | OpCode::InstancePtrEq => (lhs_value == rhs_value) as i64,
            OpCode::PtrNe | OpCode::InstancePtrNe => (lhs_value != rhs_value) as i64,
            other => panic!("trace_binop_r_to_i: unsupported opcode {other:?}"),
        };
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[lhs, rhs],
            Some(majit_ir::Value::Int(value)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(value));
    }

    /// Unary ref nullity checks trace as PTR_EQ/PTR_NE against CONST_NULL.
    /// `[src][dst]` canonical argcode order, matching the
    /// `bhhandler_r_i!` blackhole decoder.
    fn trace_ptr_nullity(&mut self, ctx: &mut TraceCtx, nonzero: bool) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (src_idx, dst)
        };
        let (src, src_value) = self.read_ref_reg(ctx, src_idx);
        let null = ctx.const_null();
        let opcode = if nonzero {
            OpCode::PtrNe
        } else {
            OpCode::PtrEq
        };
        let value = if nonzero {
            (src_value != 0) as i64
        } else {
            (src_value == 0) as i64
        };
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[src, null],
            Some(majit_ir::Value::Int(value)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(value));
    }

    /// Per-opname float binop tracer helper.
    /// `[lhs][rhs][dst]` canonical argcode order, matching the
    /// `bhhandler_ff_f!` blackhole decoder.
    fn trace_binop_f(&mut self, ctx: &mut TraceCtx, opcode: OpCode) {
        let (lhs_idx, rhs_idx, dst) = {
            let frame = self.frames.current_mut();
            let lhs_idx = frame.next_reg() as usize;
            let rhs_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (lhs_idx, rhs_idx, dst)
        };
        let (lhs, lhs_value) = self.read_float_reg(ctx, lhs_idx);
        let (rhs, rhs_value) = self.read_float_reg(ctx, rhs_idx);
        let value = eval_binop_f(opcode, lhs_value, rhs_value);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[lhs, rhs],
            Some(majit_ir::Value::Float(f64::from_bits(value as u64))),
            self.last_exception_value,
        );
        self.set_float_reg(ctx, dst, Some(opref), Some(value));
    }

    /// Float comparison `float_lt/ff>i` etc.: two float operands, an int
    /// (`0`/`1`) result written to the int bank. `[lhs][rhs][dst]` argcode
    /// order matching the `bhhandler_ff_i!` decoder.
    fn trace_compare_f(&mut self, ctx: &mut TraceCtx, opcode: OpCode) {
        let (lhs_idx, rhs_idx, dst) = {
            let frame = self.frames.current_mut();
            let lhs_idx = frame.next_u8() as usize;
            let rhs_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (lhs_idx, rhs_idx, dst)
        };
        let (lhs, lhs_value) = self.read_float_reg(ctx, lhs_idx);
        let (rhs, rhs_value) = self.read_float_reg(ctx, rhs_idx);
        let value = eval_float_cmp(opcode, lhs_value, rhs_value);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[lhs, rhs],
            Some(majit_ir::Value::Int(value)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(value));
    }

    fn trace_unary_f(&mut self, ctx: &mut TraceCtx, opcode: OpCode) {
        // `[src][dst]` canonical argcode order, matching the
        // `bhhandler_f_f!` blackhole decoder.
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_reg() as usize;
            let dst = frame.next_reg() as usize;
            (src_idx, dst)
        };
        let (src, src_value) = self.read_float_reg(ctx, src_idx);
        let value = eval_unary_f(opcode, src_value);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            opcode,
            None,
            &[src],
            Some(majit_ir::Value::Float(f64::from_bits(value as u64))),
            self.last_exception_value,
        );
        self.set_float_reg(ctx, dst, Some(opref), Some(value));
    }

    /// `cast_int_to_float/i>f`: read an int operand, widen it to `f64`, and
    /// write the float bank. `[src][dst]` argcode order (`bhhandler_i_f!`). The
    /// float value travels as its `i64` bits, matching `trace_binop_f`.
    fn trace_cast_int_to_float(&mut self, ctx: &mut TraceCtx) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (src_idx, dst)
        };
        let (src, src_value) = self.read_int_reg(ctx, src_idx);
        let fvalue = src_value as f64;
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            OpCode::CastIntToFloat,
            None,
            &[src],
            Some(majit_ir::Value::Float(fvalue)),
            self.last_exception_value,
        );
        self.set_float_reg(ctx, dst, Some(opref), Some(fvalue.to_bits() as i64));
    }

    /// `cast_ptr_to_int/r>i`: the pointer word moves to the int bank.
    /// `[src][dst]`. Identity on the bits (`bhimpl_cast_ptr_to_int`).
    fn trace_cast_ptr_to_int(&mut self, ctx: &mut TraceCtx) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (src_idx, dst)
        };
        let (src, bits) = self.read_ref_reg(ctx, src_idx);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            OpCode::CastPtrToInt,
            None,
            &[src],
            Some(majit_ir::Value::Int(bits)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(bits));
    }

    /// `cast_int_to_ptr/i>r`: the int word moves to the ref bank.
    /// `[src][dst]`. Identity on the bits (`bhimpl_cast_int_to_ptr`).
    fn trace_cast_int_to_ptr(&mut self, ctx: &mut TraceCtx) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (src_idx, dst)
        };
        let (src, bits) = self.read_int_reg(ctx, src_idx);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            OpCode::CastIntToPtr,
            None,
            &[src],
            Some(majit_ir::Value::Ref(majit_ir::GcRef(bits as usize))),
            self.last_exception_value,
        );
        self.set_ref_reg(ctx, dst, Some(opref), Some(bits));
    }

    /// `cast_float_to_int/f>i`: truncate a float-bank value toward zero into the
    /// int bank — the inverse of `trace_cast_int_to_float`, and a VALUE cast, not
    /// the bitcast below. `[src][dst]`. The float travels as its `i64` bits, so
    /// the concrete value is `f64::from_bits(bits) as i64`, matching
    /// `bhimpl_cast_float_to_int` (`blackhole.py`) exactly — including
    /// Rust's saturating behaviour on non-finite and out-of-range inputs, which
    /// `execute_cast_const` deliberately refuses to constant-fold so the runtime
    /// stays the single source of that policy.
    fn trace_cast_float_to_int(&mut self, ctx: &mut TraceCtx) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (src_idx, dst)
        };
        let (src, bits) = self.read_float_reg(ctx, src_idx);
        let ivalue = f64::from_bits(bits as u64) as i64;
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            OpCode::CastFloatToInt,
            None,
            &[src],
            Some(majit_ir::Value::Int(ivalue)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(ivalue));
    }

    /// `convert_float_bytes_to_longlong/f>i`: reinterpret a float's 64-bit
    /// pattern as an int. `[src][dst]`. The i64 bits are exactly what
    /// the float register box already carries, so the concrete value is identity.
    fn trace_convert_float_bytes_to_longlong(&mut self, ctx: &mut TraceCtx) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (src_idx, dst)
        };
        let (src, bits) = self.read_float_reg(ctx, src_idx);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            OpCode::ConvertFloatBytesToLonglong,
            None,
            &[src],
            Some(majit_ir::Value::Int(bits)),
            self.last_exception_value,
        );
        self.set_int_reg(ctx, dst, Some(opref), Some(bits));
    }

    /// `convert_longlong_bytes_to_float/i>f`: reinterpret an int's 64-bit
    /// pattern as a float — the inverse bitcast. `[src][dst]`.
    fn trace_convert_longlong_bytes_to_float(&mut self, ctx: &mut TraceCtx) {
        let (src_idx, dst) = {
            let frame = self.frames.current_mut();
            let src_idx = frame.next_u8() as usize;
            let dst = frame.next_u8() as usize;
            (src_idx, dst)
        };
        let (src, bits) = self.read_int_reg(ctx, src_idx);
        let opref = ctx.execute_and_record(
            Some(self.cpu.as_ref()),
            OpCode::ConvertLonglongBytesToFloat,
            None,
            &[src],
            Some(majit_ir::Value::Float(f64::from_bits(bits as u64))),
            self.last_exception_value,
        );
        self.set_float_reg(ctx, dst, Some(opref), Some(bits));
    }
}

/// A typed `*_return` reached a caller that declared no destination for it.
///
/// `pyjitpl.py finishframe` writes the result into `framestack[-1]`
/// whenever the stack is non-empty, and `pyjitpl.py
/// make_result_of_lastop` takes the destination from
/// `ord(self.bytecode[self.pc-1])` — the result operand of the CALLER's
/// `inline_call_*` instruction.  There is no no-destination case to fall
/// through, and none can arise: `jtransform.py rewrite_call` builds the
/// name as `'%s_%s_%s' % (namebase, kinds, reskind)` with `reskind =
/// getkind(op.result.concretetype)[0]`, so the caller's `_i`/`_r`/`_f`/`_v`
/// suffix and the callee's terminator are ONE decision taken once, from the
/// callee's own result type.
///
/// Pyre records the destination as the last operand of `BC_INLINE_CALL`
/// (`NO_RETURN_REG` for void) and recovers its kind from `_resulttypes`.
/// Reaching a typed return with `NO_RETURN_REG` is the disagreement.
/// Reaching this means an encoder minted `inline_call_*_v` for a callee that
/// ends in a typed return: the value has nowhere to go, and continuing would
/// drop it in silence and leave the caller reading a stale register — the same
/// shape as the green write `lower_stmt_fallback` used to discard, one layer
/// down.
///
/// This does NOT abort the process. `run_to_end` wraps every `run_one_step`
/// in `catch_unwind` (see the `abort_after_panic` site above), so the unwind is
/// caught and converted to [`TraceAction::Abort`] — the trace is discarded and
/// the interpreter answers, with the message printed only under `MAJIT_LOG`.
/// That is the point: it puts this mismatch on the same disposition as the
/// sibling site in [`MetaInterp::run_one_step`]'s finished-frame branch, which
/// reaches the same catch through `expect("inline int return missing caller
/// destination")`. Before this, the two disagreed — that one aborted the trace,
/// this one let the walk continue against a register the callee never wrote.
fn typed_return_without_caller_destination(insn: &str, argcode: char) -> ! {
    panic!(
        "{insn} returned an `{argcode}` value into a non-empty framestack, but the \
         caller's BC_INLINE_CALL encoded NO_RETURN_REG for that bank. The \
         `inline_call_*_{argcode}` form and the callee's terminator are one \
         decision (jtransform.py:434 `reskind`) and this pair disagrees, so the \
         returned value has no destination"
    );
}

/// Legacy entry point used by tests and integrations that still hold
/// `JitCode` by reference and do not pass a `MetaInterp` framestack
/// borrow.  Allocates a [`StandaloneFrameStack`], pushes the root
/// frame, runs the machine, and discards the stack — preserving
/// pre-unification semantics for callers that have not yet migrated.
pub fn trace_jitcode<S, FLabel>(
    ctx: &mut TraceCtx,
    sym: &mut S,
    jitcode: &JitCode,
    pc: usize,
    label_at: FLabel,
) -> TraceAction
where
    S: JitCodeSym,
    FLabel: Fn(usize) -> usize,
{
    trace_jitcode_with_args(ctx, sym, jitcode, pc, label_at, &[])
}

/// RPython `MIFrame.setup_call(original_boxes)` entry variant for callers
/// that have explicit JitCode argument boxes.
pub fn trace_jitcode_with_args<S, FLabel>(
    ctx: &mut TraceCtx,
    sym: &mut S,
    jitcode: &JitCode,
    pc: usize,
    label_at: FLabel,
    argboxes: &[(JitArgKind, OpRef, i64)],
) -> TraceAction
where
    S: JitCodeSym,
    FLabel: Fn(usize) -> usize,
{
    let runtime = ClosureRuntime::new(label_at);
    trace_jitcode_with_args_and_runtime(ctx, sym, jitcode, pc, &runtime, argboxes)
}

/// Production wire-up: variant that takes a pre-built
/// `JitCodeRuntime` instance, so the caller can provide a
/// `ClosureRuntimeWithResolver` carrying both `label_at` and the
/// `jitcell_token_arc_for_number` callback — the second is what lets
/// `BC_CALL_ASSEMBLER_*` dispatch hit the production `Arc<JitCellToken>`
/// instead of the `_by_number_typed` synth-Arc fallback.
pub fn trace_jitcode_with_args_and_runtime<S, R>(
    ctx: &mut TraceCtx,
    sym: &mut S,
    jitcode: &JitCode,
    pc: usize,
    runtime: &R,
    argboxes: &[(JitArgKind, OpRef, i64)],
) -> TraceAction
where
    S: JitCodeSym,
    R: JitCodeRuntime,
{
    if refuse_reachable_symbolic_residuals(jitcode) {
        return TraceAction::Abort;
    }
    let jitcode_arc = Arc::new(jitcode.clone());
    let mut standalone = StandaloneFrameStack::new();
    let mut frame = standalone
        .frames
        .take_frame(jitcode_arc, pc, None, Some(ctx));
    // `setup_call` (`pyjitpl/frame.rs`) resets `frame.pc = 0` on the
    // newly-constructed callee frame; preserve the outer interpreter
    // pc on the machine so `run_to_end`'s portal-pc anchor reflects
    // the actual outer pc rather than the post-reset zero.
    let outer_pc = pc;
    frame.setup_call(argboxes);
    ctx.stamp_argboxes(argboxes);
    standalone.frames.push(frame);
    let mut machine = JitCodeMachine::<S, _>::with_framestack(&mut standalone.frames, &[], &[]);
    machine.set_outer_program_pc(outer_pc);
    let action = machine.run_to_end(ctx, sym, runtime);
    drop(machine);

    publish_walk_abort_handoff(ctx, &action, &mut standalone);
    action
}

/// `MIFrame.pc` for `BlackholeInterpreter.setposition`.
///
/// `_get_opimpl_method` assigns `pc` at an instruction boundary. A cursor
/// that sits on an operand byte is not that boundary;
/// `last_opcode_position` is the opcode `run_one_step` saved before the
/// decode. A cursor that is already a startpoint stays.
pub(crate) fn snap_pc_to_instruction_start(frame: &MIFrame) -> usize {
    let cursor = frame.code_cursor;
    let opcode_at = frame.last_opcode_position;
    if frame.jitcode.is_valid_startpoint(cursor) {
        cursor
    } else if frame.jitcode.is_valid_startpoint(opcode_at) {
        opcode_at
    } else {
        cursor
    }
}

/// Publish an aborted walk's resume handoff onto the trace ctx.
///
/// The walk executes the portal JitCode forward against the real
/// interpreter-owned heap.  If it aborts, its root frame still has the source
/// interpreter pc in i0: dispatch advances i0 before executing the opcode arm.
/// Preserve that position before the temporary frame is dropped so the
/// jit_merge_point single-pass handoff can resume after the committed prefix
/// instead of replaying it from the trace header.
///
/// i0 alone only names a sound resume position when the walk stopped at a
/// source-opcode boundary; `pyjitpl.py run_blackhole_interp_to_cancel_tracing
/// run_blackhole_interp_to_cancel_tracing` does not depend on that, because
/// `blackhole.py convert_and_run_from_pyjitpl` finishes the current jitcode
/// frames in the blackhole and takes the resume position from the
/// `jit_merge_point` they reach.  Hand the whole framestack to the abort
/// consumer so it can do that; i0 stays as the fallback for a consumer that
/// declines the conversion.  CloseLoop and Finish already capture their own
/// positions; Abort and SwitchToBlackhole need this recovery handoff
/// (`pyjitpl.py _interpret` answers a `SwitchToBlackhole` with
/// `run_blackhole_interp_to_cancel_tracing` on the live framestack).
///
/// Shared by every walk entry: where the walk started does not change what a
/// consumer needs in order to resume from where it stopped.
pub fn publish_walk_abort_handoff(
    ctx: &mut TraceCtx,
    action: &TraceAction,
    standalone: &mut StandaloneFrameStack,
) {
    if matches!(
        action,
        TraceAction::Abort | TraceAction::SwitchToBlackhole(_)
    ) && !standalone.frames.is_empty()
    {
        // `None` is itself a resume choice: the generated dispatch loop falls
        // through and re-runs the source arm. The trace-start reachable-set
        // gate makes that sound for every statically named target because no
        // residual in the refused trace has executed. A funcptr read from a
        // runtime Int register is invisible to that scan and reaches this
        // site-level backstop; it also takes the arm-replay position, because
        // the post-decode framestack would skip the refused call altogether.
        //
        // That replay is only sound when no residual has committed. A bound
        // helper such as `iter_next_store` may already have popped the
        // iterator; re-running the merge-point opcode then raises
        // `no iterator to advance`. Compiled code can have made that
        // call before the guard failed, so a bridge walk that then
        // refuses an unbound residual (`__len`, `scope_rewind`) must
        // not fall back to the loop header either — `pyjitpl.py
        // run_blackhole_interp_to_cancel_tracing` converts the live
        // framestack instead. Keep i0 and the framestack when the host
        // marked a committed residual or this walk is already a
        // guard-resume bridge.
        if std::mem::replace(&mut ctx.symbolic_residual_abort, false)
            && !crate::take_residual_committed()
            && !crate::is_bridge_walking()
            && !ctx.is_bridge_trace
        {
            return;
        }
        if let Some(pc) = standalone.frames.frames[0]
            .int_regs
            .first()
            .copied()
            .flatten()
            .and_then(|op| ctx.box_bits(op))
            .and_then(|pc| usize::try_from(pc).ok())
        {
            ctx.walk_final_pc = Some(pc);
        }
        // An arm that failed to lower is emitted as a degraded stub: a
        // sub-JitCode whose entire body is the single `abort` byte, pushed by
        // the arm's `BC_INLINE_CALL` (`jit_interp/jitcode_lower/dispatch.rs`
        // emits `__sub_builder.abort()` as the whole body).  The arm's own code
        // never runs, so the opcode applies NOTHING.
        //
        // i0 is the wrong resume position for exactly that case, and wrong in
        // the silent direction: dispatch advances i0 before running the arm, so
        // i0 names the position AFTER an opcode that did not execute.  Resuming
        // there drops the opcode.  The offset is the shared prologue advance,
        // not the instruction width, so a multi-byte opcode resumes inside its
        // own operands and the interpreter decodes an operand as an opcode.
        //
        // The opcode's own boundary is the position the walk last passed
        // through the merge point, which is where the interpreter is by
        // construction re-enterable.  Re-running the opcode is sound precisely
        // because the stub applied nothing.
        //
        // `last_mp_green_pc` is `None` for a driver that declares no greens —
        // its merge point yields no concrete pc at all — so this correction
        // does not apply there and the i0 position stands, unchanged.
        let stub_resume_pc = if standalone.frames.frames.len() > 1
            && standalone
                .frames
                .frames
                .last()
                .is_some_and(|f| f.jitcode.code.as_slice() == [crate::jitcode::insns::BC_ABORT])
        {
            ctx.last_mp_green_pc
        } else {
            None
        };
        if let Some(pc) = stub_resume_pc {
            ctx.walk_final_pc = Some(pc);
        }
        if stub_resume_pc.is_none()
            && let Some(root) = standalone.frames.frames.first()
        {
            ctx.snapshot_portal_greens_from_frame(&root.int_regs, &root.ref_regs, &root.float_regs);
        }
        // `run_to_end` already re-read live greens on Abort. The shared
        // prologue has advanced i0, so that snapshot's first int green is
        // one past the opcode. `warmspot.py handle_jitexception` resumes
        // from `ContinueRunningNormally` green_int[0]; a stub applied
        // nothing, so that slot is the merge-point opcode
        // (`last_mp_green_pc`).
        if let Some(pc) = stub_resume_pc {
            let bits = pc as i64;
            if let Some((ints, _, _)) = ctx.live_portal_greens.as_mut()
                && let Some(slot) = ints.first_mut()
            {
                *slot = bits;
            }
            if let Some((ints, _, _)) = ctx.close_greens.as_mut()
                && let Some(slot) = ints.first_mut()
            {
                *slot = bits;
            }
        }
        // Every frame below the top already carries its own resume position:
        // `BC_INLINE_CALL` sets `frame.pc = frame.code_cursor` on the caller
        // before pushing the callee.  The top frame's is still the last guard's
        // `orgpc` swap, so publish the position the walk actually stopped at —
        // `copy_data_from_miframe` (`blackhole.py`) reads `frame.pc` as
        // each level's `setposition`.  A finished step leaves `code_cursor`
        // on the next instruction, and that offset is a startpoint.  An abort
        // inside operand decode leaves the cursor on an operand byte of the
        // same jitcode.  `setposition` then dispatches that byte.
        // `last_opcode_position` is the boundary `run_one_step` saved before
        // consuming the opcode, so that is the pc the blackhole frame runs.
        //
        // A stub abort corrected above declines the conversion for the same
        // reason `abort_after_panic` does — the frames name no work the
        // blackhole should finish.  Publishing them anyway is what makes the
        // correction inert: `pending_abort_blackhole` is consumed in preference
        // to `single_pass_outcome`, so the stale position wins with no error.
        // The flag is taken unconditionally so declining here cannot leave it
        // set for the next abort.
        let abort_after_panic = std::mem::replace(&mut ctx.abort_after_panic, false);
        if !abort_after_panic && stub_resume_pc.is_none() {
            if let Some(top) = standalone.frames.frames.last_mut() {
                top.pc = snap_pc_to_instruction_start(top);
            }
            ctx.aborted_framestack = Some(std::mem::take(&mut standalone.frames));
        }
    }
}

/// Enter the walk at the jitcode position a guard failed on.
///
/// `pyjitpl.py handle_guard_failure` →
/// `initialize_state_from_guard_failure` → `rebuild_state_after_failure`
/// rebuilds one `MIFrame` per encoded resume section, fills its live registers
/// from the guard's numbering, and calls `setup_resume_at_op(pc)` on each —
/// whose whole body is `self.pc = pc`.  `interpret()` then continues the walk
/// from there, so everything the failing opcode had left to do is recorded
/// into the bridge instead of being run somewhere the bridge cannot see.
///
/// The other entries in this file start a walk at a position the interpreter
/// is re-enterable at — jitcode entry, or a merge point — and derive the
/// register file by running forward from it.  A guard is neither: it sits
/// mid-opcode, so the register file cannot be re-derived and has to be handed
/// over.  `frames` is that file, one entry per rebuilt frame and one register
/// per live register within it.
///
/// `frames` arrives in the resume stream's own order — outermost caller first
/// — and is pushed in that order, so the walk resumes in the innermost frame
/// with its callers underneath it, which is where `rebuild_from_resumedata`
/// leaves `metainterp.framestack`.  A frame below the
/// top is suspended inside a `BC_INLINE_CALL`, and the two things that call
/// left on the live frames are restored here rather than re-derived: the
/// caller's own `_result_argcode` / `result_arg_index`, which the next
/// snapshot capture reads to blank the not-yet-written result register
/// (`opencoder.py _ensure_parent_resumedata`), and the callee's `return_*`,
/// which its typed return writes through (`make_result_of_lastop`).
///
/// `outer_program_pc` is the interpreter-space anchor `run_to_end` reports
/// portal positions against; the guard's own position is jitcode-space and
/// says nothing about it.
pub fn trace_jitcode_at_resume_framestack<S, R>(
    ctx: &mut TraceCtx,
    sym: &mut S,
    frames: &[crate::jit_state::GuardResumeFrame],
    outer_program_pc: usize,
    runtime: &R,
) -> TraceAction
where
    S: JitCodeSym,
    R: JitCodeRuntime,
{
    if frames
        .first()
        .is_some_and(|frame| refuse_reachable_symbolic_residuals(&frame.jitcode))
    {
        return TraceAction::Abort;
    }
    let mut standalone = StandaloneFrameStack::new();
    for (depth, resume_frame) in frames.iter().enumerate() {
        let mut frame = standalone.frames.take_frame(
            resume_frame.jitcode.clone(),
            resume_frame.pc,
            None,
            Some(ctx),
        );
        // `resume.py rebuild_from_resumedata` does `newframe`, then
        // `setup_resume_at_op`, then `consume_boxes` into that frame's
        // registers. The resume list already holds the portal reds.
        for reg in &resume_frame.regs {
            let index = reg.index as usize;
            let bank_regs = match reg.bank {
                majit_ir::Type::Ref => &mut frame.ref_regs,
                majit_ir::Type::Float => &mut frame.float_regs,
                _ => &mut frame.int_regs,
            };
            // A register the jitcode does not declare is one the guard cannot
            // have been holding, so there is no value to lose by skipping it —
            // and indexing past the bank would panic on a mismatch that is
            // already recoverable.
            if index >= bank_regs.len() {
                continue;
            }
            bank_regs[index] = Some(reg.opref);
            let stamped = match reg.bank {
                majit_ir::Type::Ref => Value::Ref(majit_ir::GcRef(reg.value as usize)),
                majit_ir::Type::Float => Value::Float(f64::from_bits(reg.value as u64)),
                _ => Value::Int(reg.value),
            };
            // `resume.py consume_boxes` stores the box; the value was
            // attached at `load_box_from_cpu` (`GuardResumeFrame.regs` producer).
            debug_assert_box_holds(ctx, reg.opref, stamped);
        }
        // The walker reads from `code_cursor`; `pc` is what a snapshot taken
        // inside this frame reports. `setup_resume_at_op` is both.
        frame.code_cursor = resume_frame.pc;
        frame.pc = resume_frame.pc;
        if depth > 0 {
            // What `BC_INLINE_CALL` marks its pushed frame with, and what the
            // return path reads back to decide whether to pop the ctx's inline
            // ledger with it.
            frame.inline_frame = true;
        }
        standalone.frames.push(frame);
        if depth == 0 {
            continue;
        }
        // The caller's half of the suspended call, in the shape
        // `BC_INLINE_CALL` left it: the callee frame it pushed carries the
        // caller register its typed return writes to, and the caller itself
        // carries the same slot for the next snapshot to blank.
        let caller_index = depth - 1;
        let caller_pc = frames[caller_index].pc;
        if let Some(sub_idx) = resume_frame.sub_idx {
            ctx.push_inline_frame((sub_idx, caller_pc), u32::MAX);
        }
        let (argcode, dst) = match frames[caller_index].result_slot {
            Some((JitArgKind::Int, dst)) => {
                standalone.frames.frames[depth].return_i = Some(dst);
                (b'i', Some(dst))
            }
            Some((JitArgKind::Ref, dst)) => {
                standalone.frames.frames[depth].return_r = Some(dst);
                (b'r', Some(dst))
            }
            Some((JitArgKind::Float, dst)) => {
                standalone.frames.frames[depth].return_f = Some(dst);
                (b'f', Some(dst))
            }
            None => (b'v', None),
        };
        let caller = &mut standalone.frames.frames[caller_index];
        caller._result_argcode = argcode;
        caller.result_arg_index = dst;
    }

    let mut machine = JitCodeMachine::<S, _>::with_framestack(&mut standalone.frames, &[], &[]);
    machine.set_outer_program_pc(outer_program_pc);
    let action = machine.run_to_end(ctx, sym, runtime);
    drop(machine);
    publish_walk_abort_handoff(ctx, &action, &mut standalone);
    action
}

/// Enter a trace at a JitDriver merge point rather than the jitcode's entry.
///
/// `trace_jitcode_with_args_and_runtime` starts the walk at pc 0 (setup_call
/// resets it), so it replays the portal function's prologue. A `reds='auto'`
/// driver whose portal carries a prologue — jd1's
/// `_unpackiterable_unknown_length` builds `items` and computes `greenkey`
/// before its loop — cannot re-run that prologue: the merge-point hook holds
/// only the loop-carried reds (`w_iterator`, `items`), not the original
/// prologue inputs (`w_iterable`). Replaying from pc 0 would call
/// `length_hint(w_iterable)` on a red that is not `w_iterable`.
///
/// This entry seeds the reds/green directly into the registers the
/// `jit_merge_point` op at `header_pc` names, then begins the walk AT
/// `header_pc` so the recorded trace is exactly the loop body. The op payload
/// (`blackhole.py` `@arguments("i","I","R","F","I","R","F")`) lists the
/// green {I,R,F} register slots then the red {I,R,F} slots, each as
/// `[len:u8][reg:u8 * len]`. The green ref is seeded as a `Const`
/// (verify_green_args); each red as its InputArg, paired positionally with
/// the op's red lists in i/r/f bank order (`collect_jump_args`).  The
/// extracted `unpackiterable_portal` merge point carries a red Int
/// (`root_base`) plus three red Refs, so the caller must pass that shape
/// rather than assuming every red is a Ref.
pub fn trace_jitcode_from_merge_point<S, R>(
    ctx: &mut TraceCtx,
    sym: &mut S,
    jitcode: &JitCode,
    header_pc: usize,
    runtime: &R,
    green_args: &[(JitArgKind, i64)],
    red_args: &[(JitArgKind, OpRef, i64)],
) -> TraceAction
where
    S: JitCodeSym,
    R: JitCodeRuntime,
{
    if refuse_reachable_symbolic_residuals(jitcode) {
        return TraceAction::Abort;
    }
    let mut standalone = StandaloneFrameStack::new();
    let frame = setup_frame_from_merge_point(
        ctx,
        &mut standalone.frames,
        Arc::new(jitcode.clone()),
        header_pc,
        green_args,
        red_args,
    );
    standalone.frames.push(frame);
    let mut machine = JitCodeMachine::<S, _>::with_framestack(&mut standalone.frames, &[], &[]);
    machine.set_outer_program_pc(header_pc);
    machine.run_to_end(ctx, sym, runtime)
}

/// `history.py *FrontendOp` / `resoperation.py InputArgInt(intval)`:
/// a non-constant box is born with its value. Register writes only store
/// the box (`pyjitpl.py MIFrame.make_result_of_lastop` / `setup_call`).
///
/// `None` from [`TraceCtx::lookup_opref_concrete`] is the documented
/// residual-call / guard / unstamped family (plus test fixtures that
/// mint OpRefs without `record_op*`): skip the check, matching that
/// reader's contract. A present value that disagrees is a producer bug.
fn debug_assert_box_holds(ctx: &TraceCtx, opref: OpRef, expected: Value) {
    let _ = (ctx, opref, expected);
    #[cfg(debug_assertions)]
    {
        if opref.is_constant() {
            return;
        }
        if let Some(got) = ctx.lookup_opref_concrete(opref) {
            debug_assert_eq!(
                got, expected,
                "box {opref:?} already holds {got:?}, register write supplied {expected:?}"
            );
        }
    }
}

/// Write one merge-point argument into the register its bank owns.
/// Greens and reds differ only in where the `OpRef` came from — a
/// freshly minted constant for a green, the caller's live box for a red — so
/// the write itself is shared. The concrete lives on the box
/// (`ConstInt.getint` / `*FrontendOp.getint`).
fn seed_register(frame: &mut MIFrame, kind: JitArgKind, reg: usize, opref: OpRef, _value: i64) {
    match kind {
        JitArgKind::Int => {
            frame.int_regs[reg] = Some(opref);
        }
        JitArgKind::Ref => {
            frame.ref_regs[reg] = Some(opref);
        }
        JitArgKind::Float => {
            frame.float_regs[reg] = Some(opref);
        }
    }
}

/// The six register lists a `jit_merge_point` names, in
/// (green I, green R, green F, red I, red R, red F) order.
/// `bhimpl_jit_merge_point` decodes the same layout.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct MergePointBanks {
    pub green_i: Vec<usize>,
    pub green_r: Vec<usize>,
    pub green_f: Vec<usize>,
    pub red_i: Vec<usize>,
    pub red_r: Vec<usize>,
    pub red_f: Vec<usize>,
}

/// Decode the six `[len:u8][reg:u8 * len]` lists after the merge-point
/// opcode and jdindex bytes.
pub fn decode_jit_merge_point_banks(code: &[u8], header_pc: usize) -> MergePointBanks {
    let mut slot_regs: [Vec<usize>; 6] = std::array::from_fn(|_| Vec::new());
    let mut cur = header_pc + 2;
    for regs in slot_regs.iter_mut() {
        let len = code[cur] as usize;
        cur += 1;
        for _ in 0..len {
            regs.push(code[cur] as usize);
            cur += 1;
        }
    }
    MergePointBanks {
        green_i: std::mem::take(&mut slot_regs[0]),
        green_r: std::mem::take(&mut slot_regs[1]),
        green_f: std::mem::take(&mut slot_regs[2]),
        red_i: std::mem::take(&mut slot_regs[3]),
        red_r: std::mem::take(&mut slot_regs[4]),
        red_f: std::mem::take(&mut slot_regs[5]),
    }
}

/// Build an [`MIFrame`] whose first instruction is a JitDriver merge point.
///
/// `MIFrame::setup_call` is the ordinary callee-entry path and resets the
/// bytecode cursor to the function prologue.  A warm-loop entry instead owns
/// the values named by the marker itself; replaying the prologue both records
/// work outside the loop and can read inputs the marker does not carry.  This
/// is the typed generalization of [`trace_jitcode_from_merge_point`]'s
/// one-green-ref setup, preserving declaration order within each i/r/f bank.
pub fn setup_frame_from_merge_point(
    ctx: &mut TraceCtx,
    frames: &mut MIFrameStack,
    jitcode_arc: Arc<JitCode>,
    header_pc: usize,
    green_args: &[(JitArgKind, i64)],
    red_args: &[(JitArgKind, OpRef, i64)],
) -> MIFrame {
    let banks = decode_jit_merge_point_banks(&jitcode_arc.code, header_pc);
    let slot_regs = [
        banks.green_i,
        banks.green_r,
        banks.green_f,
        banks.red_i,
        banks.red_r,
        banks.red_f,
    ];
    let mut frame = frames.take_frame(jitcode_arc, header_pc, None, Some(ctx));
    for (bank, kind) in [JitArgKind::Int, JitArgKind::Ref, JitArgKind::Float]
        .into_iter()
        .enumerate()
    {
        let args: Vec<_> = green_args
            .iter()
            .filter(|(arg_kind, _)| *arg_kind == kind)
            .map(|(_, value)| *value)
            .collect();
        assert_eq!(
            slot_regs[bank].len(),
            args.len(),
            "merge-point green {kind:?} register count disagrees with its typed arguments",
        );
        for (&reg, value) in slot_regs[bank].iter().zip(args) {
            let opref = match kind {
                JitArgKind::Int => ctx.const_int(value),
                JitArgKind::Ref => ctx.const_ref(value),
                JitArgKind::Float => ctx.const_float(value),
            };
            seed_register(&mut frame, kind, reg, opref, value);
        }
    }
    for (bank, kind) in [JitArgKind::Int, JitArgKind::Ref, JitArgKind::Float]
        .into_iter()
        .enumerate()
    {
        let args: Vec<_> = red_args
            .iter()
            .filter(|(arg_kind, _, _)| *arg_kind == kind)
            .map(|(_, opref, value)| (*opref, *value))
            .collect();
        let regs = &slot_regs[bank + 3];
        assert_eq!(
            regs.len(),
            args.len(),
            "merge-point red {kind:?} register count disagrees with its typed arguments",
        );
        for (&reg, (opref, value)) in regs.iter().zip(args) {
            seed_register(&mut frame, kind, reg, opref, value);
            let concrete = match kind {
                JitArgKind::Int => Value::Int(value),
                JitArgKind::Ref => Value::Ref(majit_ir::GcRef(value as usize)),
                JitArgKind::Float => Value::Float(f64::from_bits(value as u64)),
            };
            debug_assert_box_holds(ctx, opref, concrete);
        }
    }
    // The walker reads from `code_cursor`; `pc` is only the portal anchor.
    // Start both at the merge point so the first executed op is the loop
    // header itself.
    frame.code_cursor = header_pc;
    frame.pc = header_pc;
    if std::env::var_os("MAJIT_BRIDGE_DEBUG").is_some() {
        eprintln!(
            "[portal-red] seed refs={:?} red_args={:?}",
            frame.ref_regs,
            red_args
                .iter()
                .map(|(k, o, v)| (*k, *o, *v))
                .collect::<Vec<_>>(),
        );
    }
    frame
}

/// `b1 is b2` crude fastpath result for comparison opcodes —
/// `pyjitpl.py` `FASTPATHS_SAME_BOXES`. Returns the constant
/// result (1 for TRUE, 0 for FALSE) when both operands are the same
/// box, or `None` for opcodes without a same-box fastpath.
pub(crate) fn fastpath_same_boxes(opcode: OpCode) -> Option<i64> {
    match opcode {
        OpCode::IntEq | OpCode::IntLe | OpCode::IntGe => Some(1),
        OpCode::IntNe | OpCode::IntLt | OpCode::IntGt => Some(0),
        OpCode::PtrEq | OpCode::InstancePtrEq => Some(1),
        OpCode::PtrNe | OpCode::InstancePtrNe => Some(0),
        _ => None,
    }
}

pub fn eval_binop_i(opcode: OpCode, lhs: i64, rhs: i64) -> i64 {
    match opcode {
        OpCode::IntAdd | OpCode::IntAddOvf => lhs.wrapping_add(rhs),
        OpCode::IntSub | OpCode::IntSubOvf => lhs.wrapping_sub(rhs),
        OpCode::IntMul | OpCode::IntMulOvf => lhs.wrapping_mul(rhs),
        OpCode::IntFloorDiv => {
            if rhs == 0 {
                0
            } else {
                lhs.wrapping_div(rhs)
            }
        }
        OpCode::IntMod => {
            if rhs == 0 {
                0
            } else {
                lhs.wrapping_rem(rhs)
            }
        }
        OpCode::IntAnd => lhs & rhs,
        OpCode::IntSignext => crate::support::int_signext(lhs, rhs),
        OpCode::IntOr => lhs | rhs,
        OpCode::IntXor => lhs ^ rhs,
        OpCode::IntLshift => lhs.wrapping_shl(rhs as u32),
        OpCode::IntRshift => lhs.wrapping_shr(rhs as u32),
        OpCode::IntEq => i64::from(lhs == rhs),
        OpCode::IntNe => i64::from(lhs != rhs),
        OpCode::IntLt => i64::from(lhs < rhs),
        OpCode::IntLe => i64::from(lhs <= rhs),
        OpCode::IntGt => i64::from(lhs > rhs),
        OpCode::IntGe => i64::from(lhs >= rhs),
        OpCode::UintRshift => (lhs as u64).wrapping_shr(rhs as u32) as i64,
        OpCode::UintMulHigh => (((lhs as u64) as u128 * (rhs as u64) as u128) >> 64) as i64,
        OpCode::UintLt => i64::from((lhs as u64) < (rhs as u64)),
        OpCode::UintLe => i64::from((lhs as u64) <= (rhs as u64)),
        OpCode::UintGt => i64::from((lhs as u64) > (rhs as u64)),
        OpCode::UintGe => i64::from((lhs as u64) >= (rhs as u64)),
        other => panic!("unsupported jitcode integer binop {other:?}"),
    }
}

pub fn eval_unary_i(opcode: OpCode, value: i64) -> i64 {
    match opcode {
        OpCode::IntNeg => value.wrapping_neg(),
        OpCode::IntInvert => !value,
        OpCode::IntIsTrue => i64::from(value != 0),
        OpCode::IntIsZero => i64::from(value == 0),
        // `opimpl.py op_int_force_ge_zero` / `blackhole.py bhimpl_int_force_ge_zero`.
        OpCode::IntForceGeZero => {
            if value < 0 {
                0
            } else {
                value
            }
        }
        other => panic!("unsupported jitcode integer unary op {other:?}"),
    }
}

/// Evaluate a float binary operation. Values are stored as i64 (bit-cast).
pub fn eval_binop_f(opcode: OpCode, lhs: i64, rhs: i64) -> i64 {
    let a = f64::from_bits(lhs as u64);
    let b = f64::from_bits(rhs as u64);
    let result = match opcode {
        OpCode::FloatAdd => a + b,
        OpCode::FloatSub => a - b,
        OpCode::FloatMul => a * b,
        OpCode::FloatTrueDiv => a / b,
        OpCode::FloatFloorDiv => (a / b).floor(),
        OpCode::FloatMod => a % b,
        other => panic!("unsupported jitcode float binop {other:?}"),
    };
    f64::to_bits(result) as i64
}

/// Evaluate a float comparison. Operands are stored as i64 (bit-cast f64).
/// Result is bool encoded as i64 (0 or 1).
pub fn eval_float_cmp(opcode: OpCode, lhs: i64, rhs: i64) -> i64 {
    let a = f64::from_bits(lhs as u64);
    let b = f64::from_bits(rhs as u64);
    match opcode {
        OpCode::FloatLt => i64::from(a < b),
        OpCode::FloatLe => i64::from(a <= b),
        OpCode::FloatEq => i64::from(a == b),
        OpCode::FloatNe => i64::from(a != b),
        OpCode::FloatGt => i64::from(a > b),
        OpCode::FloatGe => i64::from(a >= b),
        other => panic!("unsupported jitcode float compare {other:?}"),
    }
}

/// Evaluate a float unary operation.
pub fn eval_unary_f(opcode: OpCode, value: i64) -> i64 {
    let a = f64::from_bits(value as u64);
    let result = match opcode {
        OpCode::FloatNeg => -a,
        OpCode::FloatAbs => a.abs(),
        other => panic!("unsupported jitcode float unary op {other:?}"),
    };
    f64::to_bits(result) as i64
}

/// executor.py constant_from_op — typed Value from raw i64 + Type.
fn typed_value_from_raw(raw: i64, tp: majit_ir::Type) -> majit_ir::Value {
    match tp {
        majit_ir::Type::Int => majit_ir::Value::Int(raw),
        majit_ir::Type::Ref => majit_ir::Value::Ref(majit_ir::GcRef(raw as usize)),
        majit_ir::Type::Float => majit_ir::Value::Float(f64::from_bits(raw as u64)),
        majit_ir::Type::Void => majit_ir::Value::Void,
    }
}

/// executor.py:544 parity: build typed concrete_values for call_pure_results key.
/// First element is func_ptr (always Int), rest use arg_types.
fn build_concrete_values(
    func_ptr: *const (),
    concrete_args: &[i64],
    arg_types: &[majit_ir::Type],
) -> CallValues {
    let mut values = CallValues::with_capacity(1 + concrete_args.len());
    values.push(majit_ir::Value::Int(func_ptr as usize as i64));
    for (i, &v) in concrete_args.iter().enumerate() {
        let tp = arg_types[i];
        values.push(typed_value_from_raw(v, tp));
    }
    values
}

pub fn call_int_function(func_ptr: *const (), args: &[i64]) -> i64 {
    assert!(
        !func_ptr.is_null(),
        "call_int_function: null function pointer"
    );
    // No descr: an empty type list is all machine words (`None` → Int).
    call_int_function_typed(func_ptr, args, &[])
}

/// `bh_call_f` parity (`backend/model.py`, `llmodel.py`) for callers
/// that hold their arguments in `descr.arg_types()` positional order rather
/// than in the `args_i`/`args_r`/`args_f` banks the bytecode carries.
///
/// The C ABI returns `f64` in xmm0 / d0, so a float-returning callee cannot be
/// reached through [`call_int_function`]'s `-> i64` transmute — that reads the
/// integer return register. Float *arguments* have the same problem in the
/// other direction: they travel in the FP register file, so the ordered C-ABI
/// class sequence is handed to [`bh_call_f_dispatch`], which is pyre's
/// stand-in for the per-descr stub `descr.py:574` / `descr.py:604-605
/// create_call_stub` generates upstream.
///
/// `args[i]` for a `Type::Float` slot carries the raw `f64::to_bits`, matching
/// the `args_f` bank convention (`longlong` float storage).
///
/// `descr.py process` also encodes `'L'` (SignedLongLong — integer
/// register file) and `'S'` (SingleFloat — `f32`) argument classes, which the
/// bank-fed [`majit_backend::call_stub::collect_call_args`] carries arms for.
/// Neither can arrive here: this seam is fed by `descr.arg_types()`, and
/// `CallDescr::arg_classes` (`majit-ir/src/descr.rs`) maps `Type` onto
/// `'i'`/`'r'`/`'f'`/`'v'` exhaustively, so a `Type::Float` slot is always
/// class `'f'`. Teaching `Type` those classes must extend both sites.
#[allow(dead_code)] // llmodel.py bh_call_f
pub fn call_float_function(func_ptr: *const (), args: &[i64], arg_types: &[Type]) -> f64 {
    assert!(
        !func_ptr.is_null(),
        "call_float_function: null function pointer"
    );
    let classes = arg_classes_from_types(args.len(), arg_types);
    unsafe {
        majit_backend::call_stub::bh_call_f_dispatch(
            func_ptr as usize,
            &classes[..args.len()],
            args,
        )
    }
}

/// `descr.arg_types()` projected onto the ordered C-ABI class list the
/// `bh_call_*_dispatch` table takes.
///
/// This is `descr.py`'s `arg_classes = map(map_type_to_argclass, ARGS)`
/// collapsed onto the two register classes the table can express.
/// `Type::Int` and `Type::Ref` share `ArgClass::Int`; `Type::Float` is
/// `ArgClass::Float` (`descr.py TYPE()`).
///
/// Returns the fixed-size buffer so the residual-call path stays
/// allocation-free; callers slice it to `args.len()`.
///
/// A non-empty `arg_types` must cover every positional slot: a slot the descr
/// does not describe is forwarded as a machine word, which is the very
/// mis-placement this projection exists to prevent if the undescribed slot is
/// a `Float`. An empty list is the no-descr seam, so every slot is a machine
/// word. Typed callers take the argument list and the type list from the same
/// calldescr, so the two agree by construction.
#[allow(dead_code)] // descr.py process arg classes
fn arg_classes_from_types(
    args_len: usize,
    arg_types: &[Type],
) -> [majit_backend::call_stub::ArgClass; MAX_HOST_CALL_ARITY] {
    assert!(
        args_len <= MAX_HOST_CALL_ARITY,
        "unsupported JitCode typed call arity {args_len} (max {MAX_HOST_CALL_ARITY})"
    );
    // An empty `arg_types` is the no-descr seam (`call_int_function`,
    // `call_void_function`): every slot is a machine word. A non-empty list
    // that stops short of `args_len` would send an undescribed Float as Int.
    debug_assert!(
        arg_types.is_empty() || arg_types.len() >= args_len,
        "typed call: calldescr describes {} argument types for {args_len} positional \
         arguments; an undescribed Float slot would travel in an integer register",
        arg_types.len()
    );
    let mut classes = [majit_backend::call_stub::ArgClass::Int; MAX_HOST_CALL_ARITY];
    for (i, slot) in classes.iter_mut().enumerate().take(args_len) {
        *slot = match arg_types.get(i) {
            Some(Type::Float) => majit_backend::call_stub::ArgClass::Float,
            Some(Type::Int | Type::Ref) | None => majit_backend::call_stub::ArgClass::Int,
            // `descr.py TYPE('v')` is `lltype.Void`, which upstream
            // never puts in `arg_classes` for a call it dispatches.
            Some(Type::Void) => panic!("typed call: void argument class at slot {i}"),
        };
    }
    classes
}

/// `bh_call_i` / `bh_call_r` parity (`llmodel.py`, `:818`) for callers that
/// hold the `CallDescr`.
///
/// `executor.py` hands `descr` to `cpu.bh_call_i` and `cpu.bh_call_r`
/// exactly as `:66-72` does to `cpu.bh_call_f`, so the generated stub's
/// parameter types come from `arg_classes` on all three paths. An Int- or
/// Ref-returning callee with a `Float` parameter therefore reads it from the
/// floating-point register file, which [`call_int_function`]'s all-`i64`
/// transmute cannot deliver.
///
/// [`call_int_function`] stays for the seams that genuinely hold no descr —
/// `execute_varargs`'s portal runner and the CALL_ASSEMBLER family, whose
/// entry wrapper is `extern "C" fn(..) -> i64` by construction.
#[allow(dead_code)] // llmodel.py bh_call_i
pub fn call_int_function_typed(func_ptr: *const (), args: &[i64], arg_types: &[Type]) -> i64 {
    assert!(
        !func_ptr.is_null(),
        "call_int_function_typed: null function pointer"
    );
    let classes = arg_classes_from_types(args.len(), arg_types);
    unsafe {
        majit_backend::call_stub::bh_call_i_dispatch(
            func_ptr as usize,
            &classes[..args.len()],
            args,
        )
    }
}

/// `bh_call_r` parity (`backend/model.py`, `blackhole.py:1113`).
///
/// Pyre's GC ref is a `*const PyObject` carried as `i64` via the
/// pointer-size ABI alias, so `call_ref_function` shares the same
/// underlying `extern "C" fn(...) -> i64` signature with
/// [`call_int_function`].  The function exists as a structurally
/// distinct name so the ref-result dispatch site reads as the upstream
/// `bh_call_r` rather than a re-use of `bh_call_i` — when the GC handle
/// shape diverges from `i64` the call site can pick the right ABI by
/// switching here without touching the caller.
pub fn call_ref_function(func_ptr: *const (), args: &[i64]) -> i64 {
    call_int_function(func_ptr, args)
}

/// `bh_call_r` for a caller that holds `descr.arg_types()`.
pub fn call_ref_function_typed(func_ptr: *const (), args: &[i64], arg_types: &[Type]) -> i64 {
    assert!(
        !func_ptr.is_null(),
        "call_ref_function_typed: null function pointer"
    );
    let classes = arg_classes_from_types(args.len(), arg_types);
    unsafe {
        majit_backend::call_stub::bh_call_r_dispatch(
            func_ptr as usize,
            &classes[..args.len()],
            args,
        )
    }
}

pub fn call_void_function(func_ptr: *const (), args: &[i64]) {
    assert!(
        !func_ptr.is_null(),
        "call_void_function: null function pointer"
    );
    // No descr: an empty type list is all machine words (`None` → Int).
    call_void_function_typed(func_ptr, args, &[])
}

/// `bh_call_v` parity (`llmodel.py`) for callers that hold the `CallDescr`.
///
/// Args reach here packed into machine words, so a float argument holds its
/// bits in an `i64` while the callee's C ABI expects it in a floating-point
/// register; only `arg_types` still records which is which.  The
/// host-trampoline path reflects the callee's real signature and coerces each
/// argument itself, so it takes the positional list unchanged.
#[allow(dead_code)] // llmodel.py bh_call_v
pub fn call_void_function_typed(func_ptr: *const (), args: &[i64], arg_types: &[Type]) {
    assert!(
        !func_ptr.is_null(),
        "call_void_function_typed: null function pointer"
    );
    let classes = arg_classes_from_types(args.len(), arg_types);
    unsafe {
        majit_backend::call_stub::bh_call_v_dispatch(
            func_ptr as usize,
            &classes[..args.len()],
            args,
        );
    }
}

/// `opencoder.py capture_resumedata` walks `MetaInterp.framestack` and
/// reads per-frame liveness via `MIFrame.get_list_of_active_boxes`.
/// Each frame decodes the current BC_LIVE liveness entry and emits only
/// live int/ref/float registers. Portal reds already sit in those
/// registers (`MIFrame.setup_call` / the walk-start identity-slot seed).
///
/// The top frame's `pc` here holds the *JitCode-internal* resume position
/// (`record_state_guard` swapped it to the guard's orgpc just before this
/// call), matching RPython's `pyjitpl.py frame.pc = resumepc` swap.
/// Intermediate frames keep their natural `pc` (= return-to byte position
/// in their jitcode, set by `BC_INLINE_CALL` at
/// `dispatch.rs frame.pc = frame.code_cursor`).
///
/// Multi-frame walk parallels RPython
/// `opencoder.py capture_resumedata` + `_ensure_parent_resumedata`:
/// emit a `SnapshotFrame` per `MIFrame` from outermost (root) to
/// innermost (top). Parent snapshots pass `in_a_call = true`, matching
/// `opencoder.py _ensure_parent_resumedata`, so the in-flight inline
/// call result register is cleared before liveness is read.
///
/// `jitcode_index` mirrors RPython `resume.py:1050/1338`'s `jitcode_pos`
/// (an index into `metainterp_sd.jitcodes`). Every frame — root and inline —
/// stamps its own ABSOLUTE global index (`JitCode::index`, assigned in
/// `register_dispatch_jitcode`: root = 0, sub-JitCodes = their flat-registry
/// slot). Resume resolves it statelessly via `jitcode_registry.get(index)`
/// with no root/sub branch and no parent-relative `descrs` walk.
pub fn build_state_field_snapshot(
    frames: &mut MIFrameStack,
    op_live: u8,
    all_liveness: &[u8],
    after_residual_call: bool,
    virtualizable_boxes: &[OpRef],
    virtualref_boxes: &[(OpRef, usize)],
) -> crate::recorder::Snapshot {
    let frame_count = frames.frames.len();
    let mut snapshot_frames = Vec::with_capacity(frame_count);
    // Walk outer → inner (RPython _ensure_parent_resumedata convention).
    for (i, frame) in frames.frames.iter_mut().enumerate() {
        let is_top = i + 1 == frame_count;
        // RPython opencoder.py:769/808:
        // top snapshot calls get_list_of_active_boxes(False, ...);
        // parent snapshots call get_list_of_active_boxes(True, ...), which
        // clears the in-flight call result register before reading liveness.
        //
        // `after_residual_call` is propagated to the top frame only;
        // parent frames are always "in a call" relative to the top, so
        // pyjitpl.py's residual-call branch only fires once.
        let boxes = frame.get_list_of_active_snapshot_boxes(
            !is_top,
            /* clear_result_register */ !is_top,
            op_live,
            all_liveness,
            if is_top { after_residual_call } else { false },
        );
        // resume.py/1338 `jitcode = jitcodes[jitcode_pos]` — stamp each
        // frame's own ABSOLUTE global jitcode index (`JitCode::index`, assigned
        // in `register_dispatch_jitcode`: root = 0, sub-frames = their flat
        // registry slot). The resume decoders resolve it statelessly with no
        // root/sub branch and no parent-relative descrs walk.
        let jitcode_index = frame.jitcode.try_index().unwrap_or(0) as u32;
        snapshot_frames.push(crate::recorder::SnapshotFrame {
            jitcode_index,
            pc: frame.pc as u32,
            boxes,
        });
    }
    // `pyjitpl.py capture_resumedata` `_snapshot_box_list(virtualizable_boxes /
    // virtualref_boxes)` — both lists are appended to the snapshot
    // as `SnapshotTagged::Box(opref, type)` entries.  The type
    // comes from `OpRef::ty()` which carries the SSA-level result
    // type that `_number_boxes` (`resume.py`) uses for
    // TAG_BOX encoding on the resume side.
    //
    // `opencoder.py _list_of_boxes_virtualizable` reorders
    // the virtualizable list: the virtualizable identity (stored at
    // `boxes[-1]` per `TraceCtx::init_virtualizable_boxes`) is moved
    // to the FRONT, then the rest follow in original order.  The
    // resume reader (`resume.py consume_vable_info` and
    // `resume.rs::consume_vable_info`) reads the first entry as the virtualizable
    // pointer, so this reorder is load-bearing.
    // `opencoder.py _list_of_boxes_virtualizable` /
    // `opencoder.py _list_of_boxes` encode every list element
    // unconditionally via `_add_box_to_storage(box)` — no per-element
    // skip.  RPython relies on every box on `virtualref_boxes` /
    // `virtualizable_boxes` being typed; we mirror that invariant by
    // requiring `OpRef::ty()` to be `Some` rather than silently dropping
    // misshapen entries (which would shrink the snapshot relative to
    // upstream and desync the resume reader).
    let vable_boxes_snap = build_vable_snapshot_boxes(virtualizable_boxes);
    let vref_boxes_snap = build_vref_snapshot_boxes(virtualref_boxes);
    crate::recorder::Snapshot {
        resume_position: -1,
        frames: snapshot_frames,
        vable_boxes: vable_boxes_snap,
        vref_boxes: vref_boxes_snap,
    }
}

/// `pyjitpl.py MIFrame.implement_guard_value` for a caller that owns
/// the live `MIFrameStack`. `generate_guard` captures resume data at
/// record time (`capture_resumedata`). An empty stack is a missing
/// owner, not a snapshot-less guard.
pub fn implement_guard_value_on_frames(
    ctx: &mut TraceCtx,
    frames: &mut MIFrameStack,
    box_: OpRef,
    runtime_value: i64,
    resume_pc: usize,
) -> OpRef {
    if box_.is_constant() {
        return box_;
    }
    if frames.frames.is_empty() {
        panic!(
            "implement_guard_value_on_frames: missing framestack \
             (pyjitpl.py generate_guard / capture_resumedata)"
        );
    }
    let promoted_box = ctx.const_int(runtime_value);
    ctx.record_guard(OpCode::GuardValue, &[box_, promoted_box], 0);
    let top_idx = frames.frames.len() - 1;
    let saved_top_pc = frames.frames[top_idx].pc;
    frames.frames[top_idx].pc = resume_pc;
    let snapshot_id = if ctx.recorder.has_byte_buffer() {
        ctx.capture_resumedata_from_framestack(&mut frames.frames, false)
    } else {
        let op_live = ctx.metainterp_sd().op_live as u8;
        let all_liveness = ctx.metainterp_sd().liveness_info.snapshot_arc();
        let virtualizable_snapshot = ctx.virtualizable_boxes.clone().unwrap_or_default();
        let virtualref_snapshot = ctx.virtualref_boxes.clone();
        let snapshot = build_state_field_snapshot(
            frames,
            op_live,
            &all_liveness,
            false,
            &virtualizable_snapshot,
            &virtualref_snapshot,
        );
        ctx.capture_resumedata(snapshot)
    };
    frames.frames[top_idx].pc = saved_top_pc;
    ctx.set_last_guard_resume_position(snapshot_id);
    for frame in frames.frames.iter_mut() {
        frame.replace_active_box_in_frame(box_, promoted_box, Type::Int);
    }
    ctx.replace_box(box_, promoted_box);
    promoted_box
}

/// `opencoder.py _list_of_boxes_virtualizable` parity: identity-front
/// reorder for the virtualizable box list.  `virtualizable_boxes[-1]` is the
/// virtualizable identity (placed there by
/// `TraceCtx::init_virtualizable_boxes`); the snapshot moves it to slot 0 so
/// the resume reader's `consume_vable_info` (in `resume.rs`, mirroring
/// `resume.py`) reads the identity first.  Each entry must carry
/// `OpRef::ty()`; misshapen entries panic rather than silently shrink the
/// snapshot relative to upstream.
pub fn build_vable_snapshot_boxes(
    virtualizable_boxes: &[OpRef],
) -> Vec<crate::recorder::SnapshotTagged> {
    let mut vable_boxes_snap: Vec<crate::recorder::SnapshotTagged> = Vec::new();
    if !virtualizable_boxes.is_empty() {
        let last = virtualizable_boxes.last().copied().unwrap();
        // `pyjitpl.py:3319`: the virtualizable identity is the live red input
        // box at `virtualizable_boxes[-1]`.  It must remain a TAGBOX failarg,
        // never a trace-time Ref constant: resume.py reads the
        // current failing jitframe slot, whose GC map keeps a moving-GC pointer
        // updated in place.
        let last_ty = last
            .ty()
            .expect("build_vable_snapshot_boxes: virtualizable identity must be typed");
        vable_boxes_snap.push(crate::recorder::SnapshotTagged::Box(last, last_ty));
        for opref in &virtualizable_boxes[..virtualizable_boxes.len() - 1] {
            let ty = opref
                .ty()
                .expect("build_vable_snapshot_boxes: virtualizable_boxes entry must be typed");
            vable_boxes_snap.push(crate::recorder::SnapshotTagged::Box(*opref, ty));
        }
    }
    vable_boxes_snap
}

/// `opencoder.py _list_of_boxes` parity for the virtualref array.
/// `virtualref_boxes` carries `(opref, ptr)` pairs (`TraceCtx::virtualref_boxes`);
/// the snapshot keeps the opref order verbatim — the resume reader walks the
/// pairs in `consume_virtualref_info` (`resume.py`).  As with vable, every
/// entry must carry `OpRef::ty()`.
pub fn build_vref_snapshot_boxes(
    virtualref_boxes: &[(OpRef, usize)],
) -> Vec<crate::recorder::SnapshotTagged> {
    virtualref_boxes
        .iter()
        .map(|(opref, _ptr)| {
            let ty = opref
                .ty()
                .expect("build_vref_snapshot_boxes: virtualref_boxes entry must be typed");
            crate::recorder::SnapshotTagged::Box(*opref, ty)
        })
        .collect()
}

