    /// A `BhDescr::Field` naming `field` of a parent that carries a flattened
    /// one-entry field list and the `type_id` given.
    fn field_descr_with_parent(
        field: &str,
        type_id: u64,
        size: usize,
        vtable: u64,
    ) -> crate::blackhole::BhDescr {
        let spec = majit_jitcode::jitcode::BhFieldSpec {
            index: 0,
            field_key: field.to_string(),
            name: field.to_string(),
            offset: 0,
            field_size: 8,
            field_type: Type::Int,
            field_flag: majit_ir::descr::ArrayFlag::Signed,
            is_field_signed: true,
            is_immutable: false,
            is_quasi_immutable: false,
            index_in_parent: 0,
            is_class_word: None,
            load_is_acquire: false,
        };
        crate::blackhole::BhDescr::Field {
            offset: 0,
            field_size: 8,
            field_type: Type::Int,
            field_flag: majit_ir::descr::ArrayFlag::Signed,
            is_field_signed: true,
            is_immutable: false,
            is_quasi_immutable: false,
            index_in_parent: Some(0),
            parent: Some(std::sync::Arc::new(majit_jitcode::jitcode::BhSizeSpec {
                size,
                type_id,
                vtable,
                owner: String::new(),
                is_gc_managed: true,
                headerless: false,
                all_fielddescrs: vec![spec],
            })),
            name: field.to_string(),
            owner: String::new(),
            load_is_acquire: false,
        }
    }

    fn parent_size_of(descr: &majit_ir::DescrRef) -> usize {
        descr
            .as_field_descr()
            .expect("field descr")
            .get_parent_descr()
            .expect("field descr must carry a parent")
            .as_size_descr()
            .expect("parent is a size descr")
            .size()
    }

    /// `type_id == 0` is the no-STRUCT-identity sentinel, so two parents
    /// wearing it are two different STRUCTs. Publishing them under
    /// `LLType::Struct(0)` would put both in one `_cache_size` slot and one
    /// `_cache_field` name space, and the second resolution would then read
    /// back the first parent's size descr.
    ///
    /// Sharing a field *name* is what makes this observable: it turns the
    /// collapse into a `_cache_field` hit, so the second field would be the
    /// first field's Arc outright.
    #[test]
    fn type_id_less_parents_do_not_share_one_size_descr() {
        let first = field_descr_ref_from_bh(&field_descr_with_parent("x", 0, 16, 0xAA)).1;
        let second = field_descr_ref_from_bh(&field_descr_with_parent("x", 0, 48, 0xBB)).1;

        assert_eq!(parent_size_of(&first), 16);
        assert_eq!(
            parent_size_of(&second),
            48,
            "the second parent must not resolve to the first one's size descr"
        );
        assert!(
            !std::sync::Arc::ptr_eq(&first, &second),
            "two type-id-less parents must not share one field descr"
        );
    }

    /// The empty-`all_fielddescrs` twin of the above. That branch derives the
    /// parent from `size`/`vtable` alone (`descr.py:238 parent_descr =
    /// get_size_descr(gccache, STRUCT, vtable)`), so under `Struct(0)` the
    /// second resolution reads back the first one's published size slot.
    #[test]
    fn type_id_less_parents_without_a_field_list_do_not_share_one_size_descr() {
        let strip_fields = |mut descr: crate::blackhole::BhDescr| {
            if let crate::blackhole::BhDescr::Field {
                parent: Some(p), ..
            } = &mut descr
            {
                std::sync::Arc::make_mut(p).all_fielddescrs.clear();
            }
            descr
        };
        let first =
            field_descr_ref_from_bh(&strip_fields(field_descr_with_parent("z", 0, 24, 0xAA))).1;
        let second =
            field_descr_ref_from_bh(&strip_fields(field_descr_with_parent("z", 0, 56, 0xBB))).1;

        assert_eq!(parent_size_of(&first), 24);
        assert_eq!(
            parent_size_of(&second),
            56,
            "the second parent must not resolve to the first one's size descr"
        );
    }

    /// The same two parents with real, distinct type ids stay on the keyed
    /// path — the carve-out above must not disable caching for everyone.
    #[test]
    fn parents_with_real_type_ids_still_resolve_through_the_keyed_cache() {
        let a = field_descr_ref_from_bh(&field_descr_with_parent("y", 0x51A1, 16, 0xAA)).1;
        let again = field_descr_ref_from_bh(&field_descr_with_parent("y", 0x51A1, 16, 0xAA)).1;
        let other = field_descr_ref_from_bh(&field_descr_with_parent("y", 0x51A2, 48, 0xBB)).1;

        assert!(
            std::sync::Arc::ptr_eq(&a, &again),
            "one type id must resolve to one cached field descr"
        );
        assert!(!std::sync::Arc::ptr_eq(&a, &other));
        assert_eq!(parent_size_of(&other), 48);
    }

    /// Flatten stores `BhDescr::Field.name` as the printable display
    /// (`descr.py` `'%s.%s' % (STRUCT._name, fieldname)`) and `owner` as
    /// the STRUCT leaf. `get_field_descr` keys `_cache_field[STRUCT]` by
    /// the STRUCT-local fieldname only, so reconstitution must ask with
    /// that recovered key (`bh_field_cache_key`) rather than the display
    /// string. A display lookup mints a parallel descr whose `field_key`
    /// is `"PyFrame.flags"`; `slot_holds_field` then refuses the listed
    /// `"flags"` row and `field_slot_index` puts the store in the unslotted
    /// offset band (`0x40000030` at flags offset 48).
    #[test]
    fn display_spelling_field_reconstitutes_to_the_listed_struct_local_row() {
        use majit_ir::descr::{ArrayFlag, SimpleFieldDescrSpec};

        const CACHE_KEY: u64 = 0x5046_4C41_4753_0001;
        const FLAGS_OFFSET: usize = 48;
        const FLAGS_INDEX: usize = 10;
        const PARENT_SIZE: usize = 104;

        let mut specs = Vec::with_capacity(FLAGS_INDEX + 1);
        for i in 0..FLAGS_INDEX {
            specs.push(SimpleFieldDescrSpec {
                index: i as u32,
                field_key: format!("f{i}"),
                is_class_word: None,
                name: format!("T.f{i}"),
                offset: 100 + i,
                field_size: 1,
                field_type: Type::Int,
                is_immutable: false,
                is_quasi_immutable: false,
                flag: ArrayFlag::Unsigned,
                virtualizable: false,
                index_in_parent: i,
                load_is_acquire: false,
            });
        }
        specs.push(SimpleFieldDescrSpec {
            index: FLAGS_INDEX as u32,
            field_key: "flags".to_string(),
            is_class_word: None,
            name: "PyFrame.flags".to_string(),
            offset: FLAGS_OFFSET,
            field_size: 1,
            field_type: Type::Int,
            is_immutable: false,
            is_quasi_immutable: false,
            flag: ArrayFlag::Unsigned,
            virtualizable: false,
            index_in_parent: FLAGS_INDEX,
            load_is_acquire: false,
        });
        let group = majit_ir::descr::make_simple_descr_group_keyed_with_headerless(
            u32::MAX,
            PARENT_SIZE,
            CACHE_KEY as u32,
            CACHE_KEY,
            0,
            true,
            false,
            &specs,
            &[],
        );
        let listed: majit_ir::DescrRef = group.field_descrs[FLAGS_INDEX].clone();
        let listed_field = listed.as_field_descr().expect("listed flags");
        assert_eq!(listed_field.field_key(), "flags");
        assert_eq!(listed_field.offset(), FLAGS_OFFSET);
        assert_eq!(listed_field.index_in_parent(), FLAGS_INDEX);

        let parent_specs: Vec<_> = group
            .field_descrs
            .iter()
            .map(|fd| {
                majit_jitcode::jitcode::BhFieldSpec::from_field_descr(
                    fd.as_ref() as &dyn majit_ir::descr::FieldDescr
                )
            })
            .collect();
        let bh = crate::blackhole::BhDescr::Field {
            offset: FLAGS_OFFSET,
            field_size: 1,
            field_type: Type::Int,
            field_flag: ArrayFlag::Unsigned,
            is_field_signed: false,
            is_immutable: false,
            is_quasi_immutable: false,
            index_in_parent: Some(FLAGS_INDEX),
            parent: Some(std::sync::Arc::new(majit_jitcode::jitcode::BhSizeSpec {
                size: PARENT_SIZE,
                type_id: CACHE_KEY,
                vtable: 0,
                owner: String::new(),
                is_gc_managed: true,
                headerless: false,
                all_fielddescrs: parent_specs,
            })),
            name: "PyFrame.flags".to_string(),
            owner: "PyFrame".to_string(),
            load_is_acquire: false,
        };

        let reconstituted = field_descr_ref_from_bh(&bh).1;
        assert!(
            std::sync::Arc::ptr_eq(&listed, &reconstituted),
            "display spelling must resolve to cache[STRUCT][\"flags\"], not a parallel row"
        );
        assert_eq!(
            crate::optimizeopt::heap::OptHeap::field_slot_index(&reconstituted),
            FLAGS_INDEX as u32,
            "listed flags is all_fielddescrs[{FLAGS_INDEX}]"
        );
    }

    /// A missing cache key says nothing about the STRUCT's shape.
    /// `bh_size_spec_from_descr` (`majit-translate`) reads
    /// `is_gc_managed`/`headerless` straight off a descr while taking
    /// `type_id` from `cache_key()`, so a raw, header-less parent arrives here
    /// with no key — and minting it as GC-managed and headered would hand the
    /// consumer a `GUARD_GC_TYPE` and a header offset the object does not have.
    ///
    /// Both zero arms are covered: with the flattened field list and without.
    #[test]
    fn a_type_id_less_parent_keeps_its_raw_header_less_shape() {
        let make_raw = |field: &str, drop_fields: bool| {
            let mut descr = field_descr_with_parent(field, 0, 16, 0xAA);
            if let crate::blackhole::BhDescr::Field {
                parent: Some(p), ..
            } = &mut descr
            {
                let p = std::sync::Arc::make_mut(p);
                p.is_gc_managed = false;
                p.headerless = true;
                if drop_fields {
                    p.all_fielddescrs.clear();
                }
            }
            descr
        };

        for (field, drop_fields) in [("raw_listed", false), ("raw_bare", true)] {
            let fd = field_descr_ref_from_bh(&make_raw(field, drop_fields)).1;
            let parent = fd
                .as_field_descr()
                .expect("field descr")
                .get_parent_descr()
                .expect("field descr must carry a parent");
            let parent = parent.as_size_descr().expect("parent is a size descr");
            assert!(
                !parent.is_gc_managed(),
                "{field}: a raw parent must not be reconstructed as GC-managed"
            );
            assert!(
                parent.headerless(),
                "{field}: a header-less parent must not regain a GC header"
            );
        }
    }

    #[test]
    fn interleaved_int_after_float_dispatches_in_declaration_order() {
        let result = call_float_function(
            scale_f64 as *const (),
            &[2.5_f64.to_bits() as i64, 3],
            &[Type::Float, Type::Int],
        );
        assert_eq!(result, 7.5, "scale_f64(2.5, 3) == 7.5");
    }

    #[test]
    fn float_after_int_dispatches() {
        extern "C" fn scale_swapped(k: i64, x: f64) -> f64 {
            x * k as f64
        }
        let result = call_float_function(
            scale_swapped as *const (),
            &[3, 2.5_f64.to_bits() as i64],
            &[Type::Int, Type::Float],
        );
        assert_eq!(result, 7.5, "scale_swapped(3, 2.5) == 7.5");
    }

    #[test]
    fn host_call_dispatchers_reject_null_function_pointers() {
        let null = std::ptr::null();
        assert!(std::panic::catch_unwind(|| call_int_function(null, &[])).is_err());
        assert!(std::panic::catch_unwind(|| call_int_function_typed(null, &[], &[])).is_err());
        assert!(std::panic::catch_unwind(|| call_float_function(null, &[], &[])).is_err());
        assert!(std::panic::catch_unwind(|| call_void_function(null, &[])).is_err());
        assert!(std::panic::catch_unwind(|| call_void_function_typed(null, &[], &[])).is_err());
    }

