    fn portal_red_snapshot_machine(
        stack: &mut MIFrameStack,
    ) -> JitCodeMachine<'_, DummySym, ClosureRuntime<fn(usize) -> usize>> {
        JitCodeMachine::with_framestack(stack, &[], &[])
    }

    /// Abort / too-long / Continue before the first merge point still have
    /// empty `last_mp_red_*`. Copying them must not replace a snapshot
    /// already on the ctx (`opimpl_jit_merge_point` / `reached_loop_header`).
    #[test]
    fn snapshot_live_portal_reds_leaves_earlier_snapshot_when_no_merge_point_reds() {
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        let jitcode = std::sync::Arc::new(builder.finish());
        let mut stack = MIFrameStack::empty();
        stack.frames.push(MIFrame::new(jitcode, 0));

        let mut ctx = TraceCtx::for_test(0);
        let earlier = vec![(OpRef::int_op(42), Type::Int)];
        ctx.portal_red_regs_i = vec![3];
        ctx.portal_red_regs_r = vec![1];
        ctx.portal_red_regs_f = vec![2];
        ctx.live_portal_reds = Some(earlier.clone());

        let mut machine = portal_red_snapshot_machine(&mut stack);
        machine.snapshot_live_portal_reds(&mut ctx);

        assert_eq!(ctx.portal_red_regs_i, vec![3]);
        assert_eq!(ctx.portal_red_regs_r, vec![1]);
        assert_eq!(ctx.portal_red_regs_f, vec![2]);
        assert_eq!(ctx.live_portal_reds, Some(earlier));
    }

    #[test]
    fn snapshot_live_portal_reds_rereads_when_merge_point_listed_reds() {
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 0);
        let jitcode = std::sync::Arc::new(builder.finish());
        let mut frame = MIFrame::new(jitcode, 0);
        let live = OpRef::int_op(99);
        frame.int_regs[0] = Some(live);
        let mut stack = MIFrameStack::empty();
        stack.frames.push(frame);

        let mut ctx = TraceCtx::for_test(0);
        ctx.portal_red_regs_i = vec![7];
        ctx.live_portal_reds = Some(vec![(OpRef::int_op(1), Type::Int)]);

        let mut machine = portal_red_snapshot_machine(&mut stack);
        machine.last_mp_red_i = vec![0];
        machine.snapshot_live_portal_reds(&mut ctx);

        assert_eq!(ctx.portal_red_regs_i, vec![0]);
        assert_eq!(ctx.live_portal_reds, Some(vec![(live, Type::Int)]));
    }

    /// pyjitpl.py `MIFrame.opimpl_jit_merge_point`: `redboxes` become the
    /// loop-header live state only at `portal_call_depth == 0`. A merge point
    /// reached inside an inlined portal must leave `last_mp_red_*` /
    /// `portal_red_regs_*` as the root merge point set them.
    #[test]
    fn merge_point_at_inline_depth_leaves_root_last_mp_reds() {
        let mut staticdata = crate::MetaInterpStaticData::new();
        let mut jd = crate::jitdriver::JitDriverStaticData::new(vec![], vec![("x", Type::Int)]);
        jd.index = Some(0);
        staticdata.jitdrivers_sd.push(jd);

        let mut root_builder = JitCodeBuilder::new();
        root_builder.load_const_i_value(0, 10);
        root_builder.jit_merge_point(0, &[], &[], &[], &[0], &[], &[]);
        let root = std::sync::Arc::new(root_builder.finish());

        let mut callee_builder = JitCodeBuilder::new();
        callee_builder.load_const_i_value(1, 99);
        callee_builder.jit_merge_point(0, &[], &[], &[], &[1], &[], &[]);
        let callee = std::sync::Arc::new(callee_builder.finish());

        let mut ctx = TraceCtx::new(
            crate::recorder::Trace::new(),
            0,
            std::sync::Arc::new(staticdata),
        );
        let portal_depth = std::rc::Rc::new(std::cell::Cell::new(0i32));
        let portal_depth_fn = portal_depth.clone();
        ctx.portal_call_depth_fn = Some(Box::new(move || portal_depth_fn.get()));
        let mut stack = MIFrameStack::empty();
        stack.frames.push(MIFrame::new(root, 0));
        let mut machine = portal_red_snapshot_machine(&mut stack);
        let runtime: ClosureRuntime<fn(usize) -> usize> = ClosureRuntime::new(|_pc| 0);
        let mut sym = DummySym;

        assert!(matches!(
            machine.execute_one_instruction(&mut ctx, &mut sym, &runtime),
            TraceAction::Continue
        ));
        assert!(matches!(
            machine.execute_one_instruction(&mut ctx, &mut sym, &runtime),
            TraceAction::Continue
        ));
        let root_red = machine.frames.frames[0].int_regs[0].expect("root red i0");
        assert_eq!(machine.last_mp_red_i, vec![0]);
        assert_eq!(ctx.portal_red_regs_i, vec![0]);
        assert!(machine.last_mp_red_r.is_empty());
        assert!(machine.last_mp_red_f.is_empty());

        assert!(ctx.push_inline_frame((0, 0), u32::MAX));
        portal_depth.set(1);
        assert!(ctx.portal_call_depth() > 0);
        machine.frames.frames.push(MIFrame::new(callee, 0));
        assert!(matches!(
            machine.execute_one_instruction(&mut ctx, &mut sym, &runtime),
            TraceAction::Continue
        ));
        assert!(matches!(
            machine.execute_one_instruction(&mut ctx, &mut sym, &runtime),
            TraceAction::Continue
        ));

        assert_eq!(machine.last_mp_red_i, vec![0]);
        assert_eq!(machine.last_mp_red_r, Vec::<u8>::new());
        assert_eq!(machine.last_mp_red_f, Vec::<u8>::new());
        assert_eq!(ctx.portal_red_regs_i, vec![0]);
        assert!(ctx.portal_red_regs_r.is_empty());
        assert!(ctx.portal_red_regs_f.is_empty());
        machine.snapshot_live_portal_reds(&mut ctx);
        assert_eq!(ctx.live_portal_reds, Some(vec![(root_red, Type::Int)]));
    }

    #[test]
    fn merge_point_setup_starts_at_marker_and_seeds_every_typed_bank() {
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(2, -1);
        builder.load_const_r_value(1, -1);
        builder.load_const_f_value(1, -1);
        builder.jit_merge_point(0, &[0, 1], &[0], &[1], &[2], &[1], &[0]);
        let jitcode = Arc::new(builder.finish());
        let header_pc = jitcode
            .exec
            .jit_merge_point_offset
            .expect("builder recorded the marker offset");

        let mut recorder = crate::recorder::Trace::new();
        let red_i = recorder.record_input_arg_with_value(Type::Int, Some(Value::Int(60)));
        let red_r =
            recorder.record_input_arg_with_value(Type::Ref, Some(Value::Ref(majit_ir::GcRef(40))));
        let red_f = recorder
            .record_input_arg_with_value(Type::Float, Some(Value::Float(f64::from_bits(50u64))));
        let mut ctx = TraceCtx::new(recorder, 0, Arc::new(crate::MetaInterpStaticData::new()));
        let mut frames = MIFrameStack::empty();
        let frame = setup_frame_from_merge_point(
            &mut ctx,
            &mut frames,
            jitcode,
            header_pc,
            &[
                (JitArgKind::Ref, 30),
                (JitArgKind::Int, 10),
                (JitArgKind::Float, 20),
                (JitArgKind::Int, 11),
            ],
            &[
                (JitArgKind::Float, red_f, 50),
                (JitArgKind::Ref, red_r, 40),
                (JitArgKind::Int, red_i, 60),
            ],
        );

        assert_eq!(frame.code_cursor, header_pc);
        assert_eq!(frame.pc, header_pc);
        assert_eq!(frame.int_value_for_blackhole(0), Some(10));
        assert_eq!(frame.int_value_for_blackhole(1), Some(11));
        assert_eq!(frame.ref_value_for_blackhole(0), Some(30));
        assert_eq!(frame.float_value_for_blackhole(1), Some(20));
        assert_eq!(frame.int_regs[2], Some(red_i));
        assert_eq!(frame.ref_regs[1], Some(red_r));
        assert_eq!(frame.float_regs[0], Some(red_f));
    }

    /// Test `JitCodeRuntime` that opts a synthetic portal into the
    /// `BC_RECURSIVE_CALL_*` inline path: it always inlines and resolves
    /// the portal to a fixed jitcode.  Production consumers use the
    /// default (`ResidualCall` / `None`) and never reach the inline path.
    struct RecursivePortalRuntime {
        portal: std::sync::Arc<JitCode>,
    }

    impl JitCodeRuntime for RecursivePortalRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }

        fn recursive_inline_decision(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
            _inline_depth: usize,
            _recursive_depth: usize,
        ) -> crate::pyjitpl::InlineDecision {
            crate::pyjitpl::InlineDecision::Inline
        }

        fn portal_jitcode(&self, _jd_index: usize) -> Option<std::sync::Arc<JitCode>> {
            Some(self.portal.clone())
        }

        fn is_main_portal(&self, _jd_index: usize) -> bool {
            true
        }
    }

    /// recursive-call SLICE 0 — a `BC_RECURSIVE_CALL_INT` whose runtime inlines the
    /// portal must push the portal frame, trace into it, marshal the
    /// argument into the portal's register, and write the portal's typed
    /// return back into the caller's destination register.  The portal
    /// returns its single incoming argument, so the end-to-end value (42)
    /// proves both the argument marshalling and the return writeback.
    #[test]
    fn recursive_call_inlines_portal_and_returns_marshalled_arg() {
        // Portal jitcode: `int_return(reg0)` — returns its incoming arg.
        let mut portal_builder = JitCodeBuilder::new();
        portal_builder.int_return(0);
        let portal = std::sync::Arc::new(portal_builder.finish());

        // Caller jitcode: load 42 into reg 5, recurse into the portal
        // moving reg 5 → portal reg 0 with the result landing in reg 0,
        // then return reg 0.
        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.load_const_i_value(5, 42);
        caller_builder.recursive_call_int(0, 0, &[], &[(JitArgKind::Int, 5)]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        let runtime = RecursivePortalRuntime {
            portal: portal.clone(),
        };
        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);

        let (finish_args, finish_arg_types) = match action {
            TraceAction::Finish {
                finish_args,
                finish_arg_types,
                exit_with_exception: false,
                ..
            } => (finish_args, finish_arg_types),
            other => panic!("expected Finish[Int] from recursive-call portal, got {other:?}"),
        };
        assert_eq!(finish_arg_types, vec![majit_ir::Type::Int]);
        assert_eq!(finish_args.len(), 1);
        assert_eq!(ctx.const_value(finish_args[0]), Some(42));

        // The portal returns normally (int_return, no merge-point cut), so the
        // ENTER_PORTAL_FRAME recorded at the inline-portal push pairs with a
        // LEAVE_PORTAL_FRAME recorded by the normal-return pop
        // (pyjitpl.py enter/leave pairing on the finishframe path).
        let recorder = ctx.into_recorder();
        let ops = recorder.ops();
        let enter_count = ops
            .iter()
            .filter(|o| o.opcode == OpCode::EnterPortalFrame)
            .count();
        let leave_count = ops
            .iter()
            .filter(|o| o.opcode == OpCode::LeavePortalFrame)
            .count();
        assert_eq!(enter_count, 1, "exactly one ENTER_PORTAL_FRAME");
        assert_eq!(
            leave_count, enter_count,
            "normal-return path must balance ENTER_PORTAL_FRAME with LEAVE_PORTAL_FRAME",
        );
    }

    /// [`RecursivePortalRuntime`] without a portal jitcode: the inline
    /// decision has no frame to push.
    struct RecursivePortalWithoutJitcodeRuntime;

    impl JitCodeRuntime for RecursivePortalWithoutJitcodeRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }

        fn recursive_inline_decision(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
            _inline_depth: usize,
            _recursive_depth: usize,
        ) -> crate::pyjitpl::InlineDecision {
            crate::pyjitpl::InlineDecision::Inline
        }
    }

    /// A refused `BC_RECURSIVE_CALL_INT` has not run, so its result register
    /// holds whatever it held before. Handing the post-decode framestack to
    /// the blackhole would resume past the call and read that stale value;
    /// the refusal must instead leave the portal to replay the source arm.
    #[test]
    fn refused_recursive_call_hands_the_blackhole_no_framestack() {
        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.load_const_i_value(5, 42);
        caller_builder.recursive_call_int(0, 0, &[], &[(JitArgKind::Int, 5)]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args_and_runtime(
            &mut ctx,
            &mut sym,
            &caller,
            0,
            &RecursivePortalWithoutJitcodeRuntime,
            &[],
        );

        assert!(matches!(action, TraceAction::Abort), "got {action:?}");
        assert!(
            ctx.aborted_framestack.is_none(),
            "a refused recursive call must not resume after itself",
        );
        assert_eq!(ctx.walk_final_pc, None);
        assert!(
            !ctx.symbolic_residual_abort,
            "the one-shot refusal flag must be consumed by the publisher",
        );
    }

    thread_local! {
        /// Captures the concrete argument the synthetic compiled callee
        /// was invoked with, so the test can assert the marshalled red arg
        /// reached the `execute_recursive_assembler_int` seam.
        static RECURSIVE_CALLEE_ARG: std::cell::Cell<i64> = const { std::cell::Cell::new(-1) };
    }

    /// Test `JitCodeRuntime` that routes a `BC_RECURSIVE_CALL_INT` through
    /// the CALL_ASSEMBLER path: it decides `CallAssembler`, resolves the
    /// callee loop to a fixed `(token, green_key)` pair, and runs the
    /// concrete leg by recording the marshalled red arg and returning
    /// `arg + 100` (so the result, 105 for arg 5, is distinguishable from
    /// the input).  Production consumers use the trait defaults (`None`)
    /// and never reach this path.
    struct RecursiveAssemblerRuntime {
        token: std::sync::Arc<majit_backend::JitCellToken>,
    }

    impl JitCodeRuntime for RecursiveAssemblerRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }

        fn recursive_inline_decision(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
            _inline_depth: usize,
            _recursive_depth: usize,
        ) -> crate::pyjitpl::InlineDecision {
            crate::pyjitpl::InlineDecision::CallAssembler
        }

        fn recursive_call_assembler_target(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
        ) -> Option<(std::sync::Arc<majit_backend::JitCellToken>, u64)> {
            // The test ignores greens (S3 exercises green-key hashing); a
            // fixed green key stands in for the resolved loop identity.
            Some((self.token.clone(), 0))
        }

        fn execute_recursive_assembler_int(
            &self,
            _token: &majit_backend::JitCellToken,
            reds: &[Value],
        ) -> Option<i64> {
            let arg = match reds.first() {
                Some(Value::Int(v)) => *v,
                _ => return None,
            };
            RECURSIVE_CALLEE_ARG.with(|c| c.set(arg));
            Some(arg + 100)
        }

        fn execute_recursive_assembler_ref(
            &self,
            _token: &majit_backend::JitCellToken,
            reds: &[Value],
        ) -> Option<i64> {
            let arg = match reds.first() {
                Some(Value::Int(v)) => *v,
                _ => return None,
            };
            RECURSIVE_CALLEE_ARG.with(|c| c.set(arg));
            // A ref result is a raw `GcRef`-bits payload; return a distinct,
            // recognizable non-zero value.
            Some(arg + 200)
        }

        fn execute_recursive_assembler_float(
            &self,
            _token: &majit_backend::JitCellToken,
            reds: &[Value],
        ) -> Option<i64> {
            let arg = match reds.first() {
                Some(Value::Int(v)) => *v,
                _ => return None,
            };
            RECURSIVE_CALLEE_ARG.with(|c| c.set(arg));
            // A float result carries `f64::to_bits()`; return a recognizable
            // float value packed the way `execute_token_raw` would.
            Some(f64::to_bits(arg as f64 + 0.5) as i64)
        }

        fn execute_recursive_assembler_void(
            &self,
            _token: &majit_backend::JitCellToken,
            reds: &[Value],
        ) -> Option<()> {
            let arg = match reds.first() {
                Some(Value::Int(v)) => *v,
                _ => return None,
            };
            RECURSIVE_CALLEE_ARG.with(|c| c.set(arg));
            Some(())
        }
    }

    /// Test `JitCodeSym` for the recursive CALL_ASSEMBLER fresh-frame path: a
    /// single-virt-array state (one zeroed scalar + a `&state` Ref + capacity),
    /// mirroring the `tl` shape.  `recursive_fresh_entry_reds` allocates a
    /// fresh backing `Vec<i64>` (kept alive by the returned owner) and reports
    /// its address as the `&state` identity; `recursive_fresh_alloc_free_targets`
    /// exposes host alloc/free addresses the dispatcher records as residual
    /// `CallR`/`CallN`.  The dispatcher uses the owner box as the trace-time
    /// fresh state and records — but does not invoke — the alloc/free targets,
    /// so trivial stand-ins suffice here (the real helpers are exercised by the
    /// `tl` example's `recursive_fresh_alloc_free_roundtrip`).
    #[derive(Default)]
    struct RecursiveFreshSym;

    extern "C" fn test_recursive_fresh_alloc(_cap: i64) -> i64 {
        0
    }

    extern "C" fn test_recursive_fresh_free(_ptr: i64) {}

    impl JitCodeSym for RecursiveFreshSym {
        fn total_slots(&self) -> usize {
            0
        }

        fn loop_header_pc(&self) -> usize {
            0
        }

        fn recursive_fresh_entry_reds(&self) -> Option<(Vec<Value>, Box<dyn std::any::Any>)> {
            let fresh: Box<Vec<i64>> = Box::new(vec![0i64; 12]);
            let base = &*fresh as *const Vec<i64> as usize;
            Some((
                vec![Value::Int(0), Value::Ref(majit_ir::GcRef(base))],
                fresh as Box<dyn std::any::Any>,
            ))
        }

        fn recursive_fresh_entry_vable_capacities(&self) -> Option<Vec<i64>> {
            Some(vec![12])
        }

        fn recursive_fresh_alloc_free_targets(&self) -> Option<(*const (), *const ())> {
            Some((
                test_recursive_fresh_alloc as *const () as usize as *const (),
                test_recursive_fresh_free as *const () as usize as *const (),
            ))
        }
    }

    /// recursive-call S3f — a `BC_RECURSIVE_CALL_INT` whose runtime decides
    /// `CallAssembler` must run the callee with a FRESH frame: the reds are
    /// the freshly-allocated callee state (`recursive_fresh_entry_reds`), not
    /// the caller's registers.  Each virt-array `&state` red is recorded as a
    /// residual `CallR` to the host allocator, the CALL_ASSEMBLER carries the
    /// fresh reds, and a residual `CallN` frees afterwards.  The concrete leg
    /// sees the fresh `stackpos = 0` (not the caller's value), and the call
    /// result is wired into the caller's destination register.
    #[test]
    fn recursive_call_assembler_records_fresh_frame_and_returns_result() {
        RECURSIVE_CALLEE_ARG.with(|c| c.set(-1));
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();

        // Caller jitcode: recurse (decision = CallAssembler), result into reg
        // 0, then return reg 0.  The callee runs with a fresh frame, so no
        // caller reds flow in (the arg-triple is ignored).
        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.recursive_call_int(0, 0, &[], &[]);
        caller_builder.live(&mut asm, &[0], &[], &[]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        let runtime = RecursiveAssemblerRuntime {
            token: std::sync::Arc::new(majit_backend::JitCellToken::new(7)),
        };
        let mut ctx = context_with_liveness(&[], &asm);
        let mut sym = RecursiveFreshSym;
        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);

        let finish_args = match action {
            TraceAction::Finish {
                finish_args,
                finish_arg_types,
                exit_with_exception: false,
                ..
            } => {
                assert_eq!(finish_arg_types, vec![majit_ir::Type::Int]);
                finish_args
            }
            other => panic!("expected Finish[Int] from recursive CALL_ASSEMBLER, got {other:?}"),
        };
        assert_eq!(finish_args.len(), 1);

        // The callee's concrete entry ran with the FRESH reds: the first red
        // is the zeroed `stackpos`, not the caller's register.
        assert_eq!(RECURSIVE_CALLEE_ARG.with(|c| c.get()), 0);

        let recorder = ctx.into_recorder();
        let ops = recorder.ops();
        // One residual alloc (CallR) for the single virt array, ...
        let alloc_ops: Vec<_> = ops.iter().filter(|o| o.opcode == OpCode::CallR).collect();
        assert_eq!(alloc_ops.len(), 1, "one residual fresh-state alloc CallR");
        // ... one residual free (CallN), ...
        let free_ops: Vec<_> = ops.iter().filter(|o| o.opcode == OpCode::CallN).collect();
        assert_eq!(free_ops.len(), 1, "one residual fresh-state free CallN");
        // ... and exactly one CallAssemblerI carrying the two declared fresh
        // reds (`stackpos`, `&state`). Capacity belongs to the allocator.
        let call_ops: Vec<_> = ops
            .iter()
            .filter(|o| o.opcode == OpCode::CallAssemblerI)
            .collect();
        assert_eq!(
            call_ops.len(),
            1,
            "recursive CALL_ASSEMBLER must record exactly one CallAssemblerI op",
        );
        let call_op = call_ops[0];
        assert_eq!(
            call_op.num_args(),
            2,
            "fresh reds in extract_live order: stackpos, &state",
        );
        // The alloc is recorded before, and the free after, the call.
        let alloc_idx = ops.iter().position(|o| o.opcode == OpCode::CallR).unwrap();
        let call_idx = ops
            .iter()
            .position(|o| o.opcode == OpCode::CallAssemblerI)
            .unwrap();
        let free_idx = ops.iter().position(|o| o.opcode == OpCode::CallN).unwrap();
        assert!(
            alloc_idx < call_idx,
            "alloc CallR must precede CALL_ASSEMBLER"
        );
        assert!(call_idx < free_idx, "free CallN must follow CALL_ASSEMBLER");
        // The call result (the op), not a marshalled input, is wired into the
        // caller's return register.
        assert_eq!(
            finish_args[0],
            call_op.pos().get(),
            "the recursive CALL_ASSEMBLER result must be wired into the caller's return register",
        );
    }

    /// A runtime that reports `ResidualCall` — no callee token PROVEN when the
    /// decision was taken — while its `recursive_call_assembler_target` seam
    /// still resolves one.  This is the production shape on the first recursive
    /// edge: `decide_recursive_inline` is pure in five scalars and cannot reach
    /// a synthesiser, but the seam is backed by `get_assembler_token` /
    /// `compile_tmp_callback`.  `token: None` models the seam that cannot build
    /// one either.
    struct RecursiveResidualDecisionRuntime {
        token: Option<std::sync::Arc<majit_backend::JitCellToken>>,
    }

    impl JitCodeRuntime for RecursiveResidualDecisionRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }

        fn recursive_inline_decision(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
            _inline_depth: usize,
            _recursive_depth: usize,
        ) -> crate::pyjitpl::InlineDecision {
            crate::pyjitpl::InlineDecision::ResidualCall
        }

        fn recursive_call_assembler_target(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
        ) -> Option<(std::sync::Arc<majit_backend::JitCellToken>, u64)> {
            self.token.clone().map(|token| (token, 0))
        }

        fn execute_recursive_assembler_int(
            &self,
            _token: &majit_backend::JitCellToken,
            reds: &[Value],
        ) -> Option<i64> {
            let arg = match reds.first() {
                Some(Value::Int(v)) => *v,
                _ => return None,
            };
            RECURSIVE_CALLEE_ARG.with(|c| c.set(arg));
            Some(arg + 100)
        }
    }

    /// `_opimpl_recursive_call` sets `assembler_call = True` for every
    /// non-inlined recursive call once `warmrunnerstate.inlining` holds, and
    /// builds the callee token on demand below that point
    /// (`direct_assembler_call` → `get_assembler_token` →
    /// `compile_tmp_callback`).  It has no callee-not-compiled case here, so
    /// `ResidualCall` — which only records that no token was proven when the
    /// pure decision predicate ran — must reach the same emitter as
    /// `CallAssembler` and let the seam answer.
    ///
    /// Declining from the decision instead loses the whole trace on the first
    /// recursive edge and does not recover until the callee happens to compile
    /// on its own.
    #[test]
    fn a_residual_decision_still_reaches_call_assembler_through_the_token_seam() {
        RECURSIVE_CALLEE_ARG.with(|c| c.set(-1));
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();

        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.recursive_call_int(0, 0, &[], &[]);
        caller_builder.live(&mut asm, &[0], &[], &[]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        let runtime = RecursiveResidualDecisionRuntime {
            token: Some(std::sync::Arc::new(majit_backend::JitCellToken::new(7))),
        };
        let mut ctx = context_with_liveness(&[], &asm);
        let mut sym = RecursiveFreshSym;
        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);

        assert!(
            matches!(
                action,
                TraceAction::Finish {
                    exit_with_exception: false,
                    ..
                }
            ),
            "a ResidualCall decision whose seam resolves a token must record the \
             call and finish, not abort: got {action:?}",
        );
        // The concrete leg ran with the FRESH reds, same as the CallAssembler
        // decision — the two differ only in what the decision had proven.
        assert_eq!(RECURSIVE_CALLEE_ARG.with(|c| c.get()), 0);

        let recorder = ctx.into_recorder();
        let call_ops = recorder
            .ops()
            .iter()
            .filter(|o| o.opcode == OpCode::CallAssemblerI)
            .count();
        assert_eq!(
            call_ops, 1,
            "exactly one CallAssemblerI, resolved through the token seam",
        );
    }

    /// The abort is kept for the case that actually has no token: a seam that
    /// cannot synthesise one either. That is the retry-until-the-callee-compiles
    /// behaviour, now reached only when no token can be built at all rather
    /// than whenever the decision predicate could not prove one.
    #[test]
    fn a_residual_decision_aborts_when_the_token_seam_is_also_empty() {
        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.recursive_call_int(0, 0, &[], &[]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        let runtime = RecursiveResidualDecisionRuntime { token: None };
        let mut ctx = TraceCtx::for_test(0);
        let mut sym = RecursiveFreshSym;
        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);

        assert!(
            matches!(action, TraceAction::Abort),
            "no token anywhere must still abort: got {action:?}",
        );
    }

    /// Ref recursive call — a `BC_RECURSIVE_CALL_REF` whose runtime decides
    /// `CallAssembler` records a `CallAssemblerR` (+ GUARD_NOT_FORCED) carrying
    /// the fresh reds, and the ref result flows into the caller's ref return
    /// register.  The concrete leg still runs with the FRESH `stackpos = 0`.
    #[test]
    fn recursive_call_assembler_ref_records_and_returns_result() {
        RECURSIVE_CALLEE_ARG.with(|c| c.set(-1));
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();

        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.recursive_call_ref(0, 0, &[], &[]);
        caller_builder.live(&mut asm, &[], &[0], &[]);
        caller_builder.ref_return(0);
        let caller = caller_builder.finish();

        let runtime = RecursiveAssemblerRuntime {
            token: std::sync::Arc::new(majit_backend::JitCellToken::new(7)),
        };
        let mut ctx = context_with_liveness(&[], &asm);
        let mut sym = RecursiveFreshSym;
        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);

        let finish_args = match action {
            TraceAction::Finish {
                finish_args,
                finish_arg_types,
                exit_with_exception: false,
                ..
            } => {
                assert_eq!(finish_arg_types, vec![majit_ir::Type::Ref]);
                finish_args
            }
            other => {
                panic!("expected Finish[Ref] from recursive CALL_ASSEMBLER, got {other:?}")
            }
        };
        assert_eq!(finish_args.len(), 1);
        // The callee's concrete entry ran with the FRESH reds (zeroed stackpos).
        assert_eq!(RECURSIVE_CALLEE_ARG.with(|c| c.get()), 0);

        let recorder = ctx.into_recorder();
        let ops = recorder.ops();
        let call_ops: Vec<_> = ops
            .iter()
            .filter(|o| o.opcode == OpCode::CallAssemblerR)
            .collect();
        assert_eq!(
            call_ops.len(),
            1,
            "recursive CALL_ASSEMBLER[Ref] must record exactly one CallAssemblerR op",
        );
        let call = ops
            .iter()
            .position(|o| o.opcode == OpCode::CallAssemblerR)
            .unwrap();
        let gnf = ops
            .iter()
            .position(|o| o.opcode == OpCode::GuardNotForced)
            .expect("CALL_ASSEMBLER[Ref] must record a GUARD_NOT_FORCED");
        assert!(call < gnf, "CALL_ASSEMBLER must precede GUARD_NOT_FORCED");
        assert_eq!(
            finish_args[0],
            call_ops[0].pos().get(),
            "the recursive CALL_ASSEMBLER[Ref] result must be wired into the caller's ref return register",
        );
    }

