    /// `BC_CALL_ASSEMBLER_VOID` with `num_args == 0` and descr 0 naming
    /// `concrete_ptr`. One ref register holds the virtualizable.
    fn call_assembler_void_jitcode(
        token: Option<&std::sync::Arc<majit_backend::JitCellToken>>,
        concrete_ptr: *const (),
    ) -> JitCode {
        let mut startpoints = indexmap::IndexSet::new();
        startpoints.insert(0usize);
        let mut jitcode = JitCode::new("call_assembler_void");
        jitcode.set_body(majit_jitcode::jitcode::JitCodeBody {
            code: vec![
                jitcode::insns::BC_CALL_ASSEMBLER_VOID,
                0,
                0, // fn_ptr_idx
                0,
                0, // num_args
            ],
            c_num_regs_r: 1,
            startpoints: Some(startpoints),
            ..Default::default()
        });
        let target = match token {
            Some(tok) => crate::jitcode::JitCallAssemblerTarget::new(tok, concrete_ptr),
            None => crate::jitcode::JitCallAssemblerTarget::unresolved(concrete_ptr),
        };
        jitcode.exec.descrs = vec![crate::jitcode::RuntimeBhDescr::AssemblerToken(target)];
        jitcode
    }

    /// Drive `BC_CALL_ASSEMBLER_VOID` with a live token-bearing virtualizable
    /// in ref register 0, matching `virtualizable_boxes[-1]`.
    ///
    /// `initialize_virtualizable` (pyjitpl.py) mints the identity as a Ref
    /// inputarg (`original_boxes[index_of_virtualizable]`) and appends that
    /// same box as `virtualizable_boxes[-1]`. A recorder with no inputargs
    /// leaves `OpRef::input_arg_ref(0)` without a `*FrontendOp`, so
    /// `box_bits` fails and `prepare_standard_virtualizable_before_residual_call`
    /// records no `FORCE_TOKEN`.
    fn trace_call_assembler_void<R: JitCodeRuntime>(
        concrete_ptr: *const (),
        runtime: &R,
        token: Option<&std::sync::Arc<majit_backend::JitCellToken>>,
    ) -> (TraceAction, crate::virtualizable::VableToken, Vec<OpCode>) {
        #[repr(C)]
        struct VableObj {
            token: usize,
        }
        let mut obj = VableObj { token: 0 };
        let addr = std::hint::black_box(std::ptr::addr_of_mut!(obj) as usize);
        let info = VirtualizableInfo::new(0).finalize_arc(majit_ir::descr::make_size_descr(
            std::mem::size_of::<VableObj>(),
        ));
        let jitcode = call_assembler_void_jitcode(token, concrete_ptr);
        let asm = majit_jitcode::codewriter::assembler::Assembler::new();
        let mut ctx = context_with_liveness(&[Type::Ref], &asm);
        ctx.install_virtualizable_info(info.clone());
        let vable_ref = OpRef::input_arg_ref(0);
        let vable_value = Value::Ref(majit_ir::GcRef(addr));
        ctx.stamp_live_inputargs(&[vable_value]);
        ctx.init_virtualizable_boxes(info.as_ref(), vable_ref, vable_value, &[], &[], &[]);
        let mut sym = DummySym;
        let _ = crate::take_walk_abort();
        let action = trace_jitcode_with_args_and_runtime(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            runtime,
            &[(JitArgKind::Ref, vable_ref, addr as i64)],
        );
        let token = unsafe { info.read_token(addr as *const u8) };
        let opcodes = ctx
            .into_recorder()
            .ops()
            .iter()
            .map(|op| op.opcode)
            .collect();
        std::hint::black_box(obj);
        (action, token, opcodes)
    }

    struct LabelOnlyRuntime;

    impl JitCodeRuntime for LabelOnlyRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }
    }

    /// A null `BC_CALL_ASSEMBLER_VOID` target aborts before
    /// `vable_and_vrefs_before_residual_call`, so the vable token stays
    /// `TOKEN_NONE` and the trace records no `FORCE_TOKEN`.
    #[test]
    fn call_assembler_void_null_target_aborts_without_vable_token() {
        let (action, token, opcodes) =
            trace_call_assembler_void(std::ptr::null(), &LabelOnlyRuntime, None);
        assert!(
            matches!(action, TraceAction::Abort),
            "null CALL_ASSEMBLER target must abort, got {action:?}"
        );
        assert_eq!(token, crate::virtualizable::VableToken::None);
        assert!(
            !opcodes.contains(&OpCode::ForceToken),
            "null target must refuse before tracing_before_residual_call, ops={opcodes:?}"
        );
    }

    std::thread_local! {
        static CALL_ASSEMBLER_VOID_HOST_ABORT_RAN: std::cell::Cell<bool> =
            const { std::cell::Cell::new(false) };
    }

    extern "C" fn call_assembler_void_host_abort() {
        CALL_ASSEMBLER_VOID_HOST_ABORT_RAN.with(|ran| ran.set(true));
        crate::request_walk_abort();
    }

    struct AssemblerTokenRuntime {
        token: std::sync::Arc<majit_backend::JitCellToken>,
    }

    impl JitCodeRuntime for AssemblerTokenRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }
    }

    /// A host walk-abort is latched during the call, after the stamp.
    /// `escaped_standard_virtualizable` must clear `TOKEN_TRACING_RESCALL`
    /// before the trace returns `Abort`.
    #[test]
    fn call_assembler_void_host_abort_clears_vable_token() {
        CALL_ASSEMBLER_VOID_HOST_ABORT_RAN.with(|ran| ran.set(false));
        let runtime = AssemblerTokenRuntime {
            token: std::sync::Arc::new(majit_backend::JitCellToken::new(7)),
        };
        let (action, token, opcodes) = trace_call_assembler_void(
            call_assembler_void_host_abort as *const (),
            &runtime,
            Some(&runtime.token),
        );
        assert!(
            CALL_ASSEMBLER_VOID_HOST_ABORT_RAN.with(|ran| ran.get()),
            "the concrete void target must run before the host abort"
        );
        assert!(
            matches!(action, TraceAction::Abort),
            "host walk-abort must abort the trace, got {action:?}"
        );
        assert!(
            opcodes.contains(&OpCode::ForceToken),
            "prepare_standard_virtualizable_before_residual_call must stamp, ops={opcodes:?}"
        );
        assert_eq!(
            token,
            crate::virtualizable::VableToken::None,
            "escaped_standard_virtualizable must clear TOKEN_TRACING_RESCALL"
        );
    }

    /// A `jit_merge_point` reached INSIDE an inlined recursive
    /// portal callee (portal_call_depth > 0) must NOT be traced through the
    /// callee's return; it takes the `opimpl_jit_merge_point` else-branch
    /// (pyjitpl.py): finishframe(leave_portal_frame=False) pops the
    /// inline callee, do_recursive_call(assembler_call=True) records a
    /// CALL_ASSEMBLER into the callee's own compiled loop on the caller frame,
    /// then a deferred leave_portal_frame, then ChangeFrame resumes the caller.
    ///
    /// The fixture merges the two existing recursive-portal fixtures: it BOTH
    /// inlines the portal (so `portal_call_depth > 0` and the callee reaches a
    /// merge point at depth > 0) AND resolves a CALL_ASSEMBLER target so the
    /// cut can record the recursion.  The recorded op stream must be
    /// `[ENTER_PORTAL_FRAME … CALL_ASSEMBLER, GUARD_NOT_FORCED,
    /// LEAVE_PORTAL_FRAME]` in that order (LEAVE deferred past the call), and
    /// the callee body after the merge point (its `int_return`) must NOT be
    /// traced inline — the recursion is a single CALL_ASSEMBLER, not an
    /// inlined tail.
    struct RecursivePortalMergePointRuntime {
        portal: std::sync::Arc<JitCode>,
        token: std::sync::Arc<majit_backend::JitCellToken>,
    }

    impl JitCodeRuntime for RecursivePortalMergePointRuntime {
        fn label_at(&self, _pc: usize) -> usize {
            0
        }

        fn recursive_inline_decision(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
            _inline_depth: usize,
            _recursive_depth: usize,
        ) -> crate::pyjitpl::InlineDecision {
            // Inline the portal so `exec_recursive_call` takes the
            // `portal_jitcode` branch and pushes the inline frame.
            crate::pyjitpl::InlineDecision::Inline
        }

        fn portal_jitcode(&self, _jd_index: usize) -> Option<std::sync::Arc<JitCode>> {
            Some(self.portal.clone())
        }

        fn is_main_portal(&self, _jd_index: usize) -> bool {
            true
        }

        fn recursive_call_assembler_target(
            &self,
            _jd_index: usize,
            _green_values: &[i64],
        ) -> Option<(std::sync::Arc<majit_backend::JitCellToken>, u64)> {
            Some((self.token.clone(), 0))
        }

        fn execute_recursive_assembler_int(
            &self,
            _token: &majit_backend::JitCellToken,
            reds: &[Value],
        ) -> Option<i64> {
            // Concrete leg: the fresh reds start with the zeroed scalar, so
            // arg + 100 == 100 is distinguishable from any caller value.
            let arg = match reds.first() {
                Some(Value::Int(v)) => *v,
                _ => return None,
            };
            Some(arg + 100)
        }
    }

    #[test]
    fn recursive_portal_merge_point_cuts_to_call_assembler() {
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();
        // Portal body: a merge point THEN a return.  The merge point is
        // reached at portal_call_depth > 0 (inlined), triggering the
        // else-branch cut; the trailing `int_return` must NOT be traced (the
        // callee frame is popped by the cut before it can run).
        let mut portal_builder = JitCodeBuilder::new();
        portal_builder.jit_merge_point(0, &[], &[], &[], &[], &[], &[]);
        portal_builder.int_return(0);
        let portal = std::sync::Arc::new(portal_builder.finish());

        // Caller: recurse into the portal (decision = Inline), result into
        // reg 0, then return reg 0.
        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.recursive_call_int(0, 0, &[], &[]);
        caller_builder.live(&mut asm, &[0], &[], &[]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        // Register a jitdriver with `no_loop_header = true` so the callee's
        // merge point auto-stamps `seen_loop_header_for_jdindex` (>= 0),
        // bypassing the EDIT-A seen<0 skip and flowing into the depth>0 cut.
        let mut staticdata = crate::MetaInterpStaticData::new();
        staticdata.op_live = crate::jitcode::insns::BC_LIVE as i32;
        staticdata.liveness_info.set(asm.all_liveness().to_vec());
        let mut jd = crate::jitdriver::JitDriverStaticData::new(vec![], vec![("frame", Type::Int)]);
        jd.index = Some(0);
        jd.result_type = Type::Int;
        jd.no_loop_header = true;
        staticdata.jitdrivers_sd.push(jd);

        let recorder = crate::recorder::Trace::new();
        let mut ctx = TraceCtx::new(recorder, 0, std::sync::Arc::new(staticdata));
        let portal_depth = std::rc::Rc::new(std::cell::Cell::new(0i32));
        {
            let portal_depth = portal_depth.clone();
            ctx.portal_call_depth_fn = Some(Box::new(move || portal_depth.get()));
        }
        ctx.portal_call_depth_adjust_fn = Some(Box::new(move |delta| {
            portal_depth.set(portal_depth.get() + delta);
        }));
        let mut sym = RecursiveFreshSym;
        let runtime = RecursivePortalMergePointRuntime {
            portal: portal.clone(),
            token: std::sync::Arc::new(majit_backend::JitCellToken::new(7)),
        };

        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);

        let finish_args = match action {
            TraceAction::Finish {
                finish_args,
                finish_arg_types,
                exit_with_exception: false,
                ..
            } => {
                assert_eq!(finish_arg_types, vec![majit_ir::Type::Int]);
                finish_args
            }
            other => {
                panic!("expected Finish[Int] from recursive-portal merge-point cut, got {other:?}")
            }
        };

        let recorder = ctx.into_recorder();
        let ops = recorder.ops();

        let enter = ops
            .iter()
            .position(|o| o.opcode == OpCode::EnterPortalFrame);
        let call = ops.iter().position(|o| o.opcode == OpCode::CallAssemblerI);
        let gnf = ops.iter().position(|o| o.opcode == OpCode::GuardNotForced);
        let leave = ops
            .iter()
            .position(|o| o.opcode == OpCode::LeavePortalFrame);

        let enter = enter.expect("must record ENTER_PORTAL_FRAME at the inline-portal push");
        let call = call.expect("cut must record a CALL_ASSEMBLER for the recursion");
        let gnf = gnf.expect("CALL_ASSEMBLER must record a GUARD_NOT_FORCED");
        let leave = leave.expect("cut must record the deferred LEAVE_PORTAL_FRAME");

        // Each of the paired ops is unique.
        assert_eq!(
            ops.iter()
                .filter(|o| o.opcode == OpCode::EnterPortalFrame)
                .count(),
            1,
            "exactly one ENTER_PORTAL_FRAME",
        );
        assert_eq!(
            ops.iter()
                .filter(|o| o.opcode == OpCode::CallAssemblerI)
                .count(),
            1,
            "the recursion is a single CALL_ASSEMBLER — the callee was NOT traced inline",
        );
        assert_eq!(
            ops.iter()
                .filter(|o| o.opcode == OpCode::LeavePortalFrame)
                .count(),
            1,
            "exactly one LEAVE_PORTAL_FRAME",
        );

        // Recorded order: [ENTER_PORTAL_FRAME … CALL_ASSEMBLER,
        // GUARD_NOT_FORCED, LEAVE_PORTAL_FRAME] — the LEAVE is deferred past
        // the CALL_ASSEMBLER (leave_portal_frame=False on the pop,
        // re-emitted after the call).
        assert!(
            enter < call && call < gnf && gnf < leave,
            "op order must be ENTER < CALL_ASSEMBLER < GUARD_NOT_FORCED < LEAVE, got \
             enter={enter} call={call} gnf={gnf} leave={leave}",
        );

        // The portal tail after the merge point (`int_return`) produced no
        // inline return-derived ops: the sole finish value is the recursion's
        // CALL_ASSEMBLER result wired into the caller's return register.
        assert_eq!(finish_args.len(), 1);
        assert_eq!(
            finish_args[0],
            ops[call].pos().get(),
            "the finish value must be the recursive CALL_ASSEMBLER result",
        );
    }

    /// A state shape that does not support fresh-frame portal entry (the
    /// `recursive_fresh_entry_reds` default `None`) makes the recursive
    /// CALL_ASSEMBLER abort to the interpreter fallback rather than passing
    /// the caller's live registers as the callee's reds.
    #[test]
    fn recursive_call_assembler_without_fresh_reds_aborts() {
        let mut caller_builder = JitCodeBuilder::new();
        caller_builder.recursive_call_int(0, 0, &[], &[]);
        caller_builder.int_return(0);
        let caller = caller_builder.finish();

        let runtime = RecursiveAssemblerRuntime {
            token: std::sync::Arc::new(majit_backend::JitCellToken::new(7)),
        };
        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action =
            trace_jitcode_with_args_and_runtime(&mut ctx, &mut sym, &caller, 0, &runtime, &[]);
        assert!(
            matches!(action, TraceAction::Abort),
            "recursive CALL_ASSEMBLER without fresh-frame support must abort, got {action:?}",
        );
    }

    fn make_test_vable_info() -> VirtualizableInfo {
        let mut info = VirtualizableInfo::new(0);
        info.add_field("pc", Type::Int, 8);
        info.add_array_field(
            "stack",
            Type::Int,
            24,
            0,
            0,
            majit_ir::make_array_descr(0, 8, Type::Int),
        );
        info.set_parent_descr(majit_ir::descr::make_size_descr(64));
        info
    }

    /// Heap object matching [`make_test_vable_info`]: `pc` at offset 8, array
    /// pointer at offset 24 to a one-item `i64` block whose item 0 is at
    /// offset 0. The items block is owned so the pointer does not dangle.
    #[repr(C)]
    struct TestVableObj {
        _header: u64,
        pc: i64,
        _pad16: u64,
        stack: *mut i64,
        _tail: [u8; 32],
        items: Box<[i64; 1]>,
    }

    const _: () = {
        assert!(std::mem::offset_of!(TestVableObj, pc) == 8);
        assert!(std::mem::offset_of!(TestVableObj, stack) == 24);
    };

    impl TestVableObj {
        fn new() -> Self {
            let mut items = Box::new([0i64; 1]);
            let stack = items.as_mut_ptr();
            Self {
                _header: 0,
                pc: 0,
                _pad16: 0,
                stack,
                _tail: [0; 32],
                items,
            }
        }

        fn addr(&self) -> usize {
            self as *const Self as usize
        }
    }

    #[repr(C)]
    struct ResidualVable {
        token: u64,
    }

    extern "C" fn residual_no_force(_vable: i64) {}

    extern "C" fn residual_int_no_force(_vable: i64) -> i64 {
        7
    }

    extern "C" fn residual_ref_no_force(vable: i64) -> i64 {
        vable
    }

    extern "C" fn residual_float_no_force(_vable: i64) -> i64 {
        f64::to_bits(3.5) as i64
    }

    extern "C" fn residual_void_no_args() {}

    static RESIDUAL_PREFIX_CALLS: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(0);
    static SYMBOLIC_RESIDUAL_COUNTER_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    extern "C" fn residual_count_prefix() {
        RESIDUAL_PREFIX_CALLS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    extern "C" fn residual_void_raises() {
        // exc payload must be a valid OBJECTPTR (typeptr at offset 0) so
        // `DefaultCpu::cls_of_box` can dereference per model.py.
        let exc_typeptr: &'static usize = Box::leak(std::boxed::Box::new(0xc1a55_usize));
        let exc_raw = exc_typeptr as *const usize as i64;
        crate::blackhole::BH_LAST_EXC_VALUE.with(|c| c.set(exc_raw));
    }

    extern "C" fn residual_force(vable: i64) {
        unsafe {
            (*(vable as usize as *mut ResidualVable)).token = 0;
        }
    }

    /// Build a test EI with the requested `extraeffect` while preserving
    /// the `effectinfo.py __new__` invariant: when
    /// `extraeffect != EF_RANDOM_EFFECTS`, all six `_*_descrs_*` raw
    /// sets must be `Some(...)` (not `None`).  `default_effect_info()`
    /// returns `MOST_GENERAL` (raw=None), so a struct-update spread
    /// with only `extraeffect` overridden would produce the
    /// PyPy-impossible "non-random + raw=None" hybrid shape.
    /// Use `const_new` (which seeds empty raw sets) for non-random
    /// effects, fall through to MOST_GENERAL for `RandomEffects` so
    /// the `assert *_descrs_* is None` arm at
    /// `effectinfo.py` holds.
    fn residual_effect(extraeffect: majit_ir::descr::ExtraEffect) -> majit_ir::descr::EffectInfo {
        if extraeffect == majit_ir::descr::ExtraEffect::RandomEffects {
            majit_ir::descr::EffectInfo::MOST_GENERAL.clone()
        } else {
            majit_ir::descr::EffectInfo::const_new(extraeffect, majit_ir::descr::OopSpecIndex::None)
        }
    }

    #[test]
    fn jitcode_vable_reads_use_standard_boxes_without_heap_ops() {
        let mut builder = JitCodeBuilder::new();
        let vr = 0;
        // The vable identity is threaded in as an argbox so the single
        // ConstPtr Box that populates `virtualizable_boxes[-1]` also
        // populates `ref_regs[vr]` — pyjitpl.py:1131 `box is standard_box`
        // is an identity check, so the two sources MUST be the same Box.
        builder.load_const_i_value(0, 0);
        builder.vable_getfield_int_with_base(1, vr, 0);
        builder.vable_getarrayitem_int_with_base(2, vr, 0, 0);
        builder.vable_arraylen_with_base(3, vr, 0);
        let jitcode = builder.finish();

        let mut obj = TestVableObj::new();
        obj.pc = 111;
        obj.items[0] = 222;
        let addr = obj.addr();

        let mut ctx = TraceCtx::for_test(0);
        let info = make_test_vable_info();
        let field_box = ctx.const_int(111);
        let array_box = ctx.const_int(222);
        let vable_ref = ctx.const_ref(addr as i64);
        ctx.init_virtualizable_boxes(
            &info,
            vable_ref,
            Value::Ref(majit_ir::GcRef(addr)),
            &[field_box, array_box],
            &[Value::Int(111), Value::Int(222)],
            &[1],
        );

        let mut sym = DummySym;
        let action = trace_jitcode_with_args(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            |_pc| 0,
            &[(JitArgKind::Ref, vable_ref, addr as i64)],
        );
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        assert_eq!(recorder.num_ops(), 0);
    }

    /// A symbol whose two state slots already reside in the live MIFrame.
    struct LiveSlotsSym {
        num_slots: usize,
    }

    impl JitCodeSym for LiveSlotsSym {
        fn total_slots(&self) -> usize {
            self.num_slots
        }

        fn loop_header_pc(&self) -> usize {
            0
        }
    }

    #[test]
    fn vable_setarrayitem_promote_guard_snapshot_predates_the_store() {
        // `_opimpl_setarrayitem_vable` (pyjitpl.py) promotes the
        // index in `_get_arrayitem_vable_index` (:1201-1216) and only THEN
        // reaches `virtualizable_boxes[index] = valuebox`.  The promote's
        // `implement_guard_value` captures resume data at the promote, so the
        // guard's snapshot names the slot's OLD Box.
        //
        // Were it captured after the store, a failing index promote would
        // restore the traced write into the promoted slot and then re-execute
        // the setter at the real index — one spurious write per failure.
        // The snapshot's liveness decode reads the `-live-` marker in front of
        // the vable op (`lower_vable.rs`, jtransform.py:764/798/814/845/926).
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();
        let mut builder = JitCodeBuilder::new();
        builder.live(&mut asm, &[0, 1], &[0], &[]);
        builder.vable_setarrayitem_int_with_base(0, 0, 0, 1);
        let jitcode = builder.finish();

        let mut staticdata = crate::MetaInterpStaticData::new();
        staticdata.op_live = crate::jitcode::insns::BC_LIVE as i32;
        staticdata.liveness_info.set(asm.all_liveness().to_vec());
        let mut recorder = crate::recorder::Trace::new();
        recorder.record_input_arg(majit_ir::Type::Int); // index
        recorder.record_input_arg(majit_ir::Type::Int); // value
        let mut ctx = TraceCtx::new(recorder, 0, std::sync::Arc::new(staticdata));
        let mut obj = TestVableObj::new();
        obj.pc = 111;
        obj.items[0] = 222;
        let addr = obj.addr();
        let info = make_test_vable_info();
        let field_box = ctx.const_int(111);
        let array_box = ctx.const_int(222);
        let vable_ref = ctx.const_ref(addr as i64);
        ctx.init_virtualizable_boxes(
            &info,
            vable_ref,
            Value::Ref(majit_ir::GcRef(addr)),
            &[field_box, array_box],
            &[Value::Int(111), Value::Int(222)],
            &[1],
        );
        // Flat layout is [static field 0, array slot 0, identity]; the write
        // below lands on slot 1, which currently holds `array_box`.
        assert_eq!(
            ctx.virtualizable_entry_at(1).map(|(op, _)| op),
            Some(array_box)
        );

        let mut sym = LiveSlotsSym { num_slots: 2 };
        let action = trace_jitcode_with_args(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            |_pc| 0,
            &[
                (JitArgKind::Ref, vable_ref, addr as i64),
                // A non-constant index is what makes the promote emit a guard;
                // a Const index short-circuits `implement_guard_value`.
                (JitArgKind::Int, OpRef::input_arg_int(0), 0),
                (JitArgKind::Int, OpRef::input_arg_int(1), 777),
            ],
        );
        assert!(matches!(action, TraceAction::Continue));

        let value_box = ctx
            .virtualizable_entry_at(1)
            .map(|(op, _)| op)
            .expect("the store must have landed on slot 1");
        assert_ne!(
            value_box, array_box,
            "the setter must have replaced the slot's Box",
        );

        let snapshots = ctx.snapshots().to_vec();
        let recorder = ctx.into_recorder();
        let guard = recorder
            .ops()
            .iter()
            .rev()
            .find(|op| op.opcode == OpCode::GuardValue)
            .expect("a non-constant vable array index must promote");
        let resume = guard.rd_resume_position();
        assert!(
            resume >= 0,
            "the promote guard must carry a resume position",
        );
        // `build_vable_snapshot_boxes` moves the identity Box to the front, so
        // assert on membership rather than on the shadow's flat index.
        let boxes = &crate::recorder::Snapshot::by_resume_position(&snapshots, resume)
            .expect("promote guard snapshot looked up by resume_position")
            .vable_boxes;
        assert!(
            boxes.contains(&crate::recorder::SnapshotTagged::Box(
                array_box,
                majit_ir::Type::Int
            )) || boxes.contains(&crate::recorder::SnapshotTagged::Const(
                222,
                majit_ir::Type::Int
            )),
            "the promote guard's snapshot must hold the PRE-store value; got {boxes:?}",
        );
        assert!(
            !boxes.contains(&crate::recorder::SnapshotTagged::Box(
                value_box,
                majit_ir::Type::Int
            )),
            "the snapshot must not carry the write its resume pc re-executes; got {boxes:?}",
        );
    }

    #[test]
    fn both_promote_guards_of_one_vable_opcode_are_stamped() {
        // When the vable Box is not the standard Box but carries its pointer,
        // `_nonstandard_virtualizable` cannot short-circuit on Box identity
        // (pyjitpl.py) and promotes the `isstandard` PTR_EQ (:1135-1138);
        // `_get_arrayitem_vable_index` then promotes the index (:1201-1216).
        // One opcode, two guards, and upstream captures resume data at each
        // `implement_guard_value` — so neither may be left unstamped.
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();
        let mut builder = JitCodeBuilder::new();
        builder.live(&mut asm, &[0, 1], &[0], &[]);
        builder.vable_setarrayitem_int_with_base(0, 0, 0, 1);
        let jitcode = builder.finish();
        jitcode.set_index(3);

        let mut staticdata = crate::MetaInterpStaticData::new();
        staticdata.op_live = crate::jitcode::insns::BC_LIVE as i32;
        staticdata.liveness_info.set(asm.all_liveness().to_vec());
        let mut recorder = crate::recorder::Trace::new();
        let vable_arg = recorder.record_input_arg(majit_ir::Type::Ref);
        let index_arg = recorder.record_input_arg(majit_ir::Type::Int);
        let value_arg = recorder.record_input_arg(majit_ir::Type::Int);
        let mut ctx = TraceCtx::new(recorder, 0, std::sync::Arc::new(staticdata));
        // `virtualizable.py finish()` / `finalize_arc` stamps every field
        // descr with the vinfo backref. `_nonstandard_virtualizable` only
        // emits the isstandard PTR_EQ when `vinfo is fielddescr.get_vinfo()`.
        let info = make_test_vable_info().finalize_arc(majit_ir::descr::make_size_descr(64));
        let mut obj = TestVableObj::new();
        obj.pc = 111;
        obj.items[0] = 222;
        let addr = obj.addr();
        let field_box = ctx.const_int(111);
        let array_box = ctx.const_int(222);
        let standard_box = ctx.const_ref(addr as i64);
        ctx.install_virtualizable_info(info.clone());
        ctx.init_virtualizable_boxes(
            &info,
            standard_box,
            Value::Ref(majit_ir::GcRef(addr)),
            &[field_box, array_box],
            &[Value::Int(111), Value::Int(222)],
            &[1],
        );
        // Same pointer, different Box: `concrete_ptrs_eq` answers isstandard=1,
        // which is the leg that emits the PTR_EQ guard and then continues into
        // the standard path instead of falling back to the heap.
        ctx.set_opref_concrete(vable_arg, Value::Ref(majit_ir::GcRef(addr)));

        let mut sym = LiveSlotsSym { num_slots: 2 };
        let action = trace_jitcode_with_args(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            |_pc| 0,
            &[
                (JitArgKind::Ref, vable_arg, addr as i64),
                (JitArgKind::Int, index_arg, 0),
                (JitArgKind::Int, value_arg, 777),
            ],
        );
        assert!(matches!(action, TraceAction::Continue));

        let snapshots = ctx.snapshots().to_vec();
        let recorder = ctx.into_recorder();
        let guards: Vec<_> = recorder
            .ops()
            .iter()
            .filter(|op| op.opcode.is_guard())
            .collect();
        assert_eq!(
            guards.len(),
            2,
            "one setarrayitem_vable over a non-identical standard Box promotes \
             twice; got {:?}",
            guards.iter().map(|op| op.opcode).collect::<Vec<_>>(),
        );
        // Each promote captures through `implement_guard_value` →
        // `record_state_guard` → `build_state_field_snapshot`, so the
        // snapshot is complete at record time: a real `jitcode_index` and
        // the live boxes from the `-live-` marker.
        for (i, guard) in guards.iter().enumerate() {
            let resume = guard.rd_resume_position();
            assert!(
                resume >= 0,
                "guard {i} ({:?}) was left without a resume position",
                guard.opcode,
            );
            let snap = crate::recorder::Snapshot::by_resume_position(&snapshots, resume)
                .expect("guard snapshot looked up by resume_position");
            let top = snap
                .frames
                .last()
                .expect("generate_guard captures the live framestack");
            assert_eq!(
                top.jitcode_index, 3,
                "guard {i} ({:?}) top frame jitcode_index",
                guard.opcode,
            );
            assert!(
                !top.boxes.is_empty(),
                "guard {i} ({:?}) top frame must carry the live boxes; got {:?}",
                guard.opcode,
                top.boxes,
            );
            assert!(
                !snap.vable_boxes.is_empty(),
                "guard {i} ({:?}) must capture the virtualizable boxes; got {:?}",
                guard.opcode,
                snap.vable_boxes,
            );
        }
    }

    #[test]
    fn every_guard_one_vable_opcode_emits_gets_a_resume_position() {
        // `set_guard_op_resume_position_from_end` stamps a guard that is no
        // longer last: `emit_force_virtualizable` records GETFIELD_GC /
        // PTR_NE / COND_CALL on top of a promote that captured later.
        let mut recorder = crate::recorder::Trace::new();
        let a = recorder.record_input_arg(majit_ir::Type::Int);
        recorder.record_guard(OpCode::GuardValue, &[a, OpRef::const_int(0)], None);
        recorder.record_op(OpCode::IntAdd, &[a, a]);
        recorder.record_guard(OpCode::GuardValue, &[a, OpRef::const_int(1)], None);

        recorder.set_guard_op_resume_position_from_end(0, 7);
        recorder.set_guard_op_resume_position_from_end(1, 5);

        recorder.materialize_into_ops();
        let guards: Vec<i32> = recorder
            .ops()
            .iter()
            .filter(|op| op.opcode.is_guard())
            .map(|op| op.rd_resume_position())
            .collect();
        assert_eq!(guards, vec![5, 7]);
        // Past the end is a no-op, not a panic or a mis-stamp.
        recorder.set_guard_op_resume_position_from_end(2, 9);
        let guards: Vec<i32> = recorder
            .ops()
            .iter()
            .filter(|op| op.opcode.is_guard())
            .map(|op| op.rd_resume_position())
            .collect();
        assert_eq!(guards, vec![5, 7]);
    }

    #[test]
    fn jitcode_new_struct_records_new_with_size_descr_and_ref_result() {
        // blackhole.py bhimpl_new: the tracer records `New` carrying a
        // SizeDescr (size from the per-jitcode descr pool) and binds the
        // allocation pointer to the destination ref register.
        let mut builder = JitCodeBuilder::new();
        builder.new_struct(0, 16, 0xCD, false, &[], "");
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        assert_eq!(recorder.num_ops(), 1);
        let op = recorder.get_op_by_pos(OpRef::ref_op(0)).unwrap();
        assert_eq!(op.opcode, OpCode::New);
        assert_eq!(
            op.getdescr()
                .and_then(|d| d.as_size_descr().map(|s| s.size())),
            Some(16)
        );
    }

    #[test]
    fn jitcode_newlist_clear_records_new_setfield_newarrayclear_setfield() {
        // opimpl_newlist_clear (pyjitpl.py): ONE opcode decomposes
        // into New + SetfieldGc(length) + NewArrayClear + SetfieldGc(items).
        // The `list` header is { length: i64 @0, items: ref @8 } (size 16)
        // wrapping a length-prefixed items block of i64 elements.
        let mut builder = JitCodeBuilder::new();
        builder.load_const_i_value(0, 3); // int reg 0 = list length 3
        builder.newlist_clear(
            0,    // dest ref reg 0 = list header
            0,    // length_reg = int reg 0
            0x51, // struct_type_id (list header identity)
            16,   // struct_size (length @0, items @8)
            0,    // length_offset
            8,    // items_offset
            0xA1, // array_type_id (items block identity)
            majit_ir::value::Type::Int,
        );
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        // The leading int_copy const load records nothing; the four resops
        // are the entire trace.
        let opcodes: Vec<_> = recorder.ops().iter().map(|o| o.opcode).collect();
        assert_eq!(
            opcodes,
            vec![
                OpCode::New,
                OpCode::SetfieldGc,
                OpCode::NewArrayClear,
                OpCode::SetfieldGc,
            ]
        );

        // The New (sbox) result feeds BOTH SetfieldGc records as arg 0.
        let new_pos = recorder.ops()[0].pos().get().raw();
        assert_eq!(recorder.ops()[1].arg(0).position(), Some(new_pos));
        assert_eq!(recorder.ops()[3].arg(0).position(), Some(new_pos));
        // The NewArrayClear (abox) result feeds the items SetfieldGc as arg 1.
        let arr_pos = recorder.ops()[2].pos().get().raw();
        assert_eq!(recorder.ops()[3].arg(1).position(), Some(arr_pos));

        // The recorded field descrs carry the resolved byte offsets.
        let len_off = recorder.ops()[1]
            .getdescr()
            .and_then(|d| d.as_field_descr().map(|f| f.offset()));
        let items_off = recorder.ops()[3]
            .getdescr()
            .and_then(|d| d.as_field_descr().map(|f| f.offset()));
        assert_eq!(len_off, Some(0));
        assert_eq!(items_off, Some(8));

        // The New carries a SizeDescr sized like the list header.
        let struct_size = recorder.ops()[0]
            .getdescr()
            .and_then(|d| d.as_size_descr().map(|s| s.size()));
        assert_eq!(struct_size, Some(16));
        // The sbox result is bound to a live (non-null) list-header pointer.
        let sbox_val = recorder.ops()[0].get_value();
        assert!(
            matches!(sbox_val, Some(Value::Ref(r)) if r.as_usize() != 0),
            "list header pointer must be a non-null ref, got {sbox_val:?}"
        );
    }

    #[test]
    fn jitcode_new_with_vtable_records_new_with_vtable_and_size_descr() {
        // blackhole.py bhimpl_new_with_vtable: same as `new` but the
        // SizeDescr carries the vtable, and the recorded op is NewWithVtable.
        let mut builder = JitCodeBuilder::new();
        builder.new_with_vtable(0, 24, 0xAB, 0x1234);
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        assert_eq!(recorder.num_ops(), 1);
        let op = recorder.get_op_by_pos(OpRef::ref_op(0)).unwrap();
        assert_eq!(op.opcode, OpCode::NewWithVtable);
        assert_eq!(
            op.getdescr()
                .and_then(|d| d.as_size_descr().map(|s| s.size())),
            Some(24)
        );
    }

    #[test]
    fn jitcode_new_then_field_round_trip_records_setfield_getfield() {
        // Node { value: i64 @0, next: ref @8 }: allocate, store both fields
        // through the live struct ptr, then read them back.  The stores
        // record; the loads are served from the heapcache even when the
        // descr pool was never numbered.
        let mut builder = JitCodeBuilder::new();
        builder.new_struct(
            0,
            16,
            0xCD,
            false,
            &[
                (0, false, "value", 8, true, false),
                (8, true, "next", 8, false, false),
            ],
            "",
        ); // ref reg 0 = Node*
        builder.load_const_i_value(0, 99); // int reg 0 = 99
        builder.setfield_gc_i(0, 0, 0, 0xCD, "value"); // Node.value = 99
        builder.setfield_gc_r(0, 0, 8, 0xCD, "next"); // Node.next  = Node (self-ref)
        builder.getfield_gc_i(1, 0, 0, 0xCD, "value"); // int reg 1 = Node.value
        builder.getfield_gc_r(1, 0, 8, 0xCD, "next"); // ref reg 1 = Node.next
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        let opcodes: Vec<_> = recorder.ops().iter().map(|o| o.opcode).collect();
        assert_eq!(
            opcodes,
            vec![OpCode::New, OpCode::SetfieldGc, OpCode::SetfieldGc],
            "GETFIELD_GC reads of a just-stored field come from the heapcache",
        );

        // The New's SizeDescr carries the full struct layout
        // (`descr.py init_size_descr`) so the optimizer can size
        // `VirtualStructInfo._fields`.
        let n_fields = recorder.ops()[0]
            .getdescr()
            .and_then(|d| d.as_size_descr().map(|s| s.all_fielddescrs().len()));
        assert_eq!(n_fields, Some(2));
        // Each setfield FieldDescr carries `index_in_parent` (descr.py)
        // and a parent SizeDescr (descr.py) so `optimize_setfield_gc`
        // virtualizes the store instead of panicking on a `None` parent.
        let sf_i = recorder.ops()[1].getdescr().and_then(|d| {
            d.as_field_descr()
                .map(|f| (f.index_in_parent(), f.get_parent_descr().is_some()))
        });
        let sf_r = recorder.ops()[2].getdescr().and_then(|d| {
            d.as_field_descr()
                .map(|f| (f.index_in_parent(), f.get_parent_descr().is_some()))
        });
        assert_eq!(sf_i, Some((0, true)));
        assert_eq!(sf_r, Some((1, true)));
    }

    /// Stamp each descr-pool entry with its own slot number, the way the
    /// production codewriter numbers every field descr it mints
    /// (`call.rs get_field_descr`).
    ///
    /// `add_bh_descr` already dedups structurally, so a field named by both a
    /// store and a load shares one pool entry and therefore one number —
    /// which is the property `heapcache.get_field_updater(box, fielddescr)`
    /// gets for free by keying on the descr object itself.  Unnumbered
    /// descrs still cache: `Descr::index()` allocates a unique identity
    /// rather than declining the `u32::MAX` sentinel.
    fn number_the_descrs(jitcode: &JitCode) {
        for (slot, entry) in jitcode.exec.descrs.iter().enumerate() {
            if let Some(descr) = entry.as_optimizer_descr() {
                descr.set_index(slot as u32);
            }
        }
    }

    /// A field the trace has already stored answers from the heapcache.
    ///
    /// `_opimpl_getfield_gc_any_pureornot` returns `upd.currfieldbox` and
    /// records nothing when the updater has a value, and
    /// `_opimpl_setfield_gc_any`'s `upd.setfield(valuebox)` is what puts one
    /// there.  Numbering the pool is the codewriter's shape; unnumbered
    /// descrs take the same path because `Descr::index()` supplies a unique
    /// identity.  The registers still answer, and they answer with the
    /// stored box rather than a second load.
    #[test]
    fn a_stored_field_answers_from_the_heapcache_and_records_no_getfield() {
        // Its own type id and field names: `field_descr_ref_from_bh` answers
        // out of `gc_cache()._cache_field`, which is process-wide and keyed by
        // `(LLType::Struct(type_id), fieldname)`.  Numbering the descrs of a
        // struct a sibling test also names would number that test's descrs
        // too.
        let mut builder = JitCodeBuilder::new();
        builder.new_struct(
            0,
            16,
            0xCE,
            false,
            &[
                (0, false, "cached_value", 8, true, false),
                (8, true, "cached_next", 8, false, false),
            ],
            "",
        );
        builder.load_const_i_value(0, 99);
        builder.setfield_gc_i(0, 0, 0, 0xCE, "cached_value");
        builder.setfield_gc_r(0, 0, 8, 0xCE, "cached_next");
        builder.getfield_gc_i(1, 0, 0, 0xCE, "cached_value");
        builder.getfield_gc_r(1, 0, 8, 0xCE, "cached_next");
        let jitcode = builder.finish();
        number_the_descrs(&jitcode);

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        let opcodes: Vec<_> = recorder.ops().iter().map(|o| o.opcode).collect();
        assert_eq!(
            opcodes,
            vec![OpCode::New, OpCode::SetfieldGc, OpCode::SetfieldGc],
            "both GETFIELD_GC reads should have come from the heapcache",
        );
    }

