    /// A heapcache hit on a null struct must not ask the executor to
    /// load from address 0. `_opimpl_getfield_gc_any_pureornot`
    /// fabricated `loaded = 0` on that leg; `field_sanity_load` would
    /// dispatch to `bh_getfield_gc_i` and dereference it.
    #[test]
    fn heapcache_hit_on_a_null_struct_skips_the_executor_sanity_load() {
        let mut builder = JitCodeBuilder::new();
        // Register the layout without allocating: `field_descr_ref_from_bh`
        // keys `_cache_field` by `(type_id, fieldname)`, so the store and
        // the load share one heapcache slot. A scalar fallback mint would
        // give each access its own identity and miss.
        builder.register_struct_layout(
            8,
            0xD5,
            true,
            false,
            &[(0, false, "null_cached_i", 8, true, false)],
            "",
        );
        builder.load_const_r_value(0, 0);
        builder.load_const_i_value(0, 99);
        builder.setfield_gc_i(0, 0, 0, 0xD5, "null_cached_i");
        builder.getfield_gc_i(1, 0, 0, 0xD5, "null_cached_i");
        let jitcode = builder.finish();
        number_the_descrs(&jitcode);

        let cpu = RecordingGetfieldCpu {
            loads: std::cell::RefCell::new(Vec::new()),
        };
        let mut ctx = TraceCtx::for_test(0);
        ctx.set_cpu(Some(&cpu));
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));
        assert!(
            !cpu.loads.borrow().iter().any(|&p| p == 0),
            "heapcache-hit getfield must not field_sanity_load a null struct, got {:?}",
            cpu.loads.borrow()
        );

        // The SETFIELD descr converts and a wired cpu dispatches through
        // it, so an empty recording above is the null-struct guard rather
        // than a descr `field_sanity_load` cannot consume.
        let descr = ctx
            .ops()
            .iter()
            .find(|o| o.opcode == OpCode::SetfieldGc)
            .and_then(|o| o.getdescr())
            .expect("setfield recorded a field descr")
            .clone();
        cpu.loads.borrow_mut().clear();
        assert!(
            ctx.field_sanity_load(0, &descr, Type::Int).is_some(),
            "the recorded descr must convert so a skipped load is the null guard"
        );
        assert!(
            cpu.loads.borrow().contains(&0),
            "direct field_sanity_load(0) must dispatch so the empty recording above is the guard"
        );

        let opcodes: Vec<_> = ctx.into_recorder().ops().iter().map(|o| o.opcode).collect();
        assert_eq!(
            opcodes,
            vec![OpCode::SetfieldGc],
            "GETFIELD_GC must have come from the heapcache",
        );
    }

    /// A hand-assembled jitcode never numbers its descr pool.  Two fields of
    /// one box must still be distinct heapcache keys: a store answers a later
    /// load of the same field, a sibling field of the same box records once
    /// and then answers from the cache.
    #[test]
    fn unnumbered_descrs_cache_same_field_and_not_a_sibling() {
        let mut builder = JitCodeBuilder::new();
        builder.new_struct(
            0,
            16,
            0xD1,
            false,
            &[
                (0, false, "hc_size", 8, true, false),
                (8, true, "hc_buf", 8, false, false),
            ],
            "",
        );
        builder.load_const_i_value(0, 99);
        builder.setfield_gc_i(0, 0, 0, 0xD1, "hc_size");
        builder.getfield_gc_i(1, 0, 0, 0xD1, "hc_size");
        builder.getfield_gc_r(1, 0, 8, 0xD1, "hc_buf");
        builder.getfield_gc_r(2, 0, 8, 0xD1, "hc_buf");
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        let opcodes: Vec<_> = recorder.ops().iter().map(|o| o.opcode).collect();
        assert_eq!(
            opcodes,
            vec![OpCode::New, OpCode::SetfieldGc, OpCode::GetfieldGcR],
            "size load and the second buf load should have come from the heapcache",
        );
    }

    /// `_record_helper` counts what it appends and `execute_and_record`
    /// counts what it executes, so a body built only from ops that reach the
    /// trace through that pair leaves `RECORDED_OPS` and `OPS` agreeing with
    /// the trace itself. A dispatch arm that records the operation by hand
    /// without the counts breaks the equality here rather than silently
    /// under-reporting to `jit-summary`.
    #[test]
    fn ops_the_dispatch_records_by_hand_are_still_counted() {
        let mut builder = JitCodeBuilder::new();
        builder.new_struct(
            0,
            16,
            0xCD,
            false,
            &[
                (0, false, "value", 8, true, false),
                (8, true, "next", 8, false, false),
            ],
            "",
        );
        builder.load_const_i_value(0, 99);
        builder.setfield_gc_i(0, 0, 0, 0xCD, "value");
        // Read the sibling field, which was never stored, so the miss path
        // records a GETFIELD.  A read of `value` would hit the heapcache
        // and drop out of RECORDED_OPS / OPS.
        builder.getfield_gc_r(1, 0, 8, 0xCD, "next");
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));
        let recorded = ctx.profiler().get_counter(crate::counters::RECORDED_OPS);
        let executed = ctx.profiler().get_counter(crate::counters::OPS);
        let opcodes: Vec<_> = ctx.into_recorder().ops().iter().map(|o| o.opcode).collect();
        // Naming the arms keeps the equality below from going vacuous if the
        // body ever stops reaching `BC_NEW` and `BC_SETFIELD_GC_I`.
        assert_eq!(
            opcodes,
            vec![OpCode::New, OpCode::SetfieldGc, OpCode::GetfieldGcR],
        );
        assert_eq!(recorded, Some(opcodes.len()), "RECORDED_OPS");
        assert_eq!(executed, Some(opcodes.len()), "OPS");
    }

    #[test]
    fn jitcode_setfield_gc_i_c_records_const_value_and_field_descr() {
        // The `/rcd` c-form (USE_C_FORM, assembler.py) inlines a small
        // ConstInt value as one signed byte in place of the int-register
        // slot.  Dispatch must decode the byte as an inline const, record the
        // store with a ConstInt arg, and resolve the same FieldDescr as the
        // plain `/rid` form — byte 222 (BC_SETFIELD_GC_I_C) is distinct from
        // the NEW family so the arm is reached (insns.rs deconfliction).
        let mut builder = JitCodeBuilder::new();
        builder.new_struct(
            0,
            16,
            0xCE,
            false,
            &[
                (0, false, "value", 8, true, false),
                (8, true, "next", 8, false, false),
            ],
            "",
        );
        builder.setfield_gc_i_c(0, -7, 0, 0xCE, "value"); // Node.value = -7 (inline const)
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode_with_args(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0, &[]);
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        let opcodes: Vec<_> = recorder.ops().iter().map(|o| o.opcode).collect();
        assert_eq!(opcodes, vec![OpCode::New, OpCode::SetfieldGc]);

        // The value operand is the inline signed-byte const, not a register.
        let value = recorder.ops()[1].arg(1).const_int();
        assert_eq!(value, Some(-7));
        // The FieldDescr matches the `/rid` form (offset 0, index_in_parent 0).
        let descr = recorder.ops()[1].getdescr().and_then(|d| {
            d.as_field_descr()
                .map(|f| (f.offset(), f.index_in_parent()))
        });
        assert_eq!(descr, Some((0, 0)));
    }

    #[test]
    fn jitcode_call_may_force_marks_standard_virtualizable_token_and_guards() {
        let mut asm = majit_jitcode::codewriter::assembler::Assembler::new();
        let mut obj = ResidualVable { token: 0 };
        let obj_ptr = (&mut obj as *mut ResidualVable) as usize as i64;

        let mut builder = JitCodeBuilder::new();
        let fn_idx = builder.add_fn_ptr(residual_no_force as *const ());
        builder.call_may_force_void_canonical_via_target(fn_idx, &[JitCallArg::reference(0)]);
        builder.live(&mut asm, &[], &[0], &[]);
        let jitcode = builder.finish();

        let mut ctx = context_with_liveness(&[], &asm);
        let mut info = VirtualizableInfo::new(0);
        info.set_parent_descr(majit_ir::descr::make_size_descr(64));
        let vable_ref = ctx.const_ref(obj_ptr);
        ctx.init_virtualizable_boxes(
            &info,
            vable_ref,
            Value::Ref(majit_ir::GcRef::NULL),
            &[],
            &[],
            &[],
        );

        let mut sym = DummySym;
        // Thread the single vable ConstPtr Box through both the
        // standard-box slot and the argument register so pyjitpl.py:1131
        // `box is standard_box` (identity) holds, matching upstream's
        // Box-flow invariant.
        let action = trace_jitcode_with_args(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            |_pc| 0,
            &[(JitArgKind::Ref, vable_ref, obj_ptr)],
        );
        assert!(matches!(action, TraceAction::Continue));
        assert_eq!(obj.token, 0, "tracing side must restore TOKEN_NONE");

        let recorder = ctx.into_recorder();
        // pyjitpl.py do_residual_call (forces case): record
        // CALL_MAY_FORCE_N, then GUARD_NOT_FORCED via
        // `vable_after_residual_call`, then GUARD_NO_EXCEPTION via
        // `handle_possible_exception` (pyjitpl.py → `pyjitpl.rs`).
        // Pyre's canonical may_force walker mirrors that 5-op shape.
        assert_eq!(recorder.num_ops(), 5);
        assert_eq!(
            recorder.get_op_by_pos(OpRef::ref_op(0)).unwrap().opcode,
            OpCode::ForceToken
        );
        let set_token = recorder.get_op_by_pos(OpRef::void_op(1)).unwrap();
        assert_eq!(set_token.opcode, OpCode::SetfieldGc);
        assert_eq!(
            set_token.getdescr().map(|d| d.index()),
            Some(info.token_field_descr().index())
        );
        assert_eq!(
            recorder.get_op_by_pos(OpRef::void_op(2)).unwrap().opcode,
            OpCode::CallMayForceN
        );
        assert_eq!(
            recorder.get_op_by_pos(OpRef::void_op(3)).unwrap().opcode,
            OpCode::GuardNotForced
        );
        assert_eq!(
            recorder.get_op_by_pos(OpRef::void_op(4)).unwrap().opcode,
            OpCode::GuardNoException
        );
    }

    /// pyjitpl.py `vable_after_residual_call`: `raise SwitchToBlackhole(
    /// Counters.ABORT_ESCAPE, raising_exception=True)`. A plain `Abort` would
    /// let the caller keep walking and compile the call with no
    /// GUARD_NOT_FORCED.
    fn assert_escape_switch_to_blackhole(action: &TraceAction) {
        let TraceAction::SwitchToBlackhole(stb) = action else {
            panic!("an escaped virtualizable must switch to the blackhole, got {action:?}");
        };
        assert_eq!(stb.reason, crate::counters::ABORT_ESCAPE);
        assert!(stb.raising_exception);
    }

    #[test]
    fn jitcode_call_may_force_aborts_when_standard_virtualizable_escapes() {
        let mut obj = ResidualVable { token: 0 };
        let obj_ptr = (&mut obj as *mut ResidualVable) as usize as i64;

        let mut builder = JitCodeBuilder::new();
        let fn_idx = builder.add_fn_ptr(residual_force as *const ());
        builder.call_may_force_void_canonical_via_target(fn_idx, &[JitCallArg::reference(0)]);
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut info = VirtualizableInfo::new(0);
        info.set_parent_descr(majit_ir::descr::make_size_descr(64));
        let vable_ref = ctx.const_ref(obj_ptr);
        ctx.init_virtualizable_boxes(
            &info,
            vable_ref,
            Value::Ref(majit_ir::GcRef::NULL),
            &[],
            &[],
            &[],
        );

        let mut sym = DummySym;
        let action = trace_jitcode_with_args(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            |_pc| 0,
            &[(JitArgKind::Ref, vable_ref, obj_ptr)],
        );
        assert_escape_switch_to_blackhole(&action);
        assert_eq!(obj.token, 0, "forced residual call must clear the token");

        let recorder = ctx.into_recorder();
        assert_eq!(recorder.num_ops(), 3);
        assert_eq!(
            recorder.get_op_by_pos(OpRef::ref_op(0)).unwrap().opcode,
            OpCode::ForceToken
        );
        assert_eq!(
            recorder.get_op_by_pos(OpRef::void_op(1)).unwrap().opcode,
            OpCode::SetfieldGc
        );
        assert_eq!(
            recorder.get_op_by_pos(OpRef::void_op(2)).unwrap().opcode,
            OpCode::CallMayForceN
        );
    }

    #[repr(C)]
    struct ForcingVable {
        token: u64,
        pc: i64,
    }

    /// Force the virtualizable (clear the token) and write a field through the
    /// heap object, the way a real forced residual call does.
    extern "C" fn residual_force_and_write(vable: i64) {
        unsafe {
            let vable = &mut *(vable as usize as *mut ForcingVable);
            vable.pc = 99;
            vable.token = 0;
        }
    }

    /// pyjitpl.py `vable_after_residual_call` calls
    /// `load_fields_from_virtualizable()` before raising
    /// `SwitchToBlackhole(ABORT_ESCAPE)`, so the fields the forced callee wrote
    /// through the heap become the resumed interpreter's state.  Without the
    /// reload the box cache still holds the pre-call values.
    #[test]
    fn escaping_standard_virtualizable_reloads_fields_before_abort() {
        let mut obj = ForcingVable { token: 0, pc: 1 };
        let obj_ptr = (&mut obj as *mut ForcingVable) as usize as i64;

        let mut builder = JitCodeBuilder::new();
        let fn_idx = builder.add_fn_ptr(residual_force_and_write as *const ());
        builder.call_may_force_void_canonical_via_target(fn_idx, &[JitCallArg::reference(0)]);
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut info = VirtualizableInfo::new(0);
        info.add_field("pc", Type::Int, 8);
        info.set_parent_descr(majit_ir::descr::make_size_descr(64));
        let vable_ref = ctx.const_ref(obj_ptr);
        let stale_pc = ctx.const_int(1);
        ctx.init_virtualizable_boxes(
            &info,
            vable_ref,
            Value::Ref(majit_ir::GcRef(obj_ptr as usize)),
            &[stale_pc],
            &[Value::Int(1)],
            &[],
        );

        let mut sym = DummySym;
        let action = trace_jitcode_with_args(
            &mut ctx,
            &mut sym,
            &jitcode,
            0,
            |_pc| 0,
            &[(JitArgKind::Ref, vable_ref, obj_ptr)],
        );
        assert_escape_switch_to_blackhole(&action);
        assert_eq!(obj.pc, 99, "the forced residual call wrote the heap field");

        let (_, reloaded) = ctx
            .virtualizable_entry_at(0)
            .expect("escape path must leave the virtualizable box cache populated");
        assert_eq!(
            reloaded,
            Value::Int(99),
            "load_fields_from_virtualizable must refresh the box cache from the heap",
        );
    }

    #[test]
    fn residual_call_cannot_raise_does_not_record_guard_no_exception() {
        let mut builder = JitCodeBuilder::new();
        let fn_idx = builder.add_fn_ptr(residual_void_no_args as *const ());
        builder.residual_call_void_canonical_via_target_with_effect_info(
            fn_idx,
            &[],
            residual_effect(majit_ir::descr::ExtraEffect::CannotRaise),
        );
        let jitcode = builder.finish();

        let mut ctx = TraceCtx::for_test(0);
        let mut sym = DummySym;
        let action = trace_jitcode(&mut ctx, &mut sym, &jitcode, 0, |_pc| 0);
        crate::blackhole::BH_LAST_EXC_VALUE.with(|c| c.set(0));
        assert!(matches!(action, TraceAction::Continue));

        let recorder = ctx.into_recorder();
        assert!(
            recorder.ops().iter().any(|op| op.opcode == OpCode::CallN),
            "cannot-raise residual call still records the call"
        );
        let pool_descr = jitcode
            .exec
            .descrs
            .iter()
            .filter_map(crate::jitcode::RuntimeBhDescr::as_optimizer_descr)
            .find(|descr| descr.as_call_descr().is_some())
            .expect("call descriptor belongs to the JitCode pool");
        let recorded = recorder
            .ops()
            .iter()
            .find(|op| op.opcode == OpCode::CallN)
            .unwrap()
            .getdescr()
            .unwrap();
        assert!(std::sync::Arc::ptr_eq(pool_descr, &recorded));
        assert!(
            !recorder
                .ops()
                .iter()
                .any(|op| op.opcode == OpCode::GuardNoException),
            "pyjitpl.execute_varargs(exc=False) must only assert_no_exception"
        );
    }

